        meaning: "\u0635\u0646\u0639 \u062A\u0637\u0628\u064A\u0642\u0627\u062A \u062A\u0639\u0644\u064A\u0645\u064A\u0629 \u0628\u0646\u0641\u0633\u0643 \u0623\u0635\u0628\u062D \u0633\u0647\u0644\u0627\u064B \u0648\u0645\u062C\u0627\u0646\u0627\u064B",
        keywords: ["leichter lernen = \u062A\u0639\u0644\u0645 \u0623\u0633\u0647\u0644", "selbst gemachte = \u0635\u0646\u0639 \u0630\u0627\u062A\u064A", "Apps = \u062A\u0637\u0628\u064A\u0642\u0627\u062A", "digitales Quiz = \u0627\u062E\u062A\u0628\u0627\u0631 \u0631\u0642\u0645\u064A", "Know-how = \u062E\u0628\u0631\u0629 \u062A\u0642\u0646\u064A\u0629"],
