        simplified: "\u0634\u0631\u0643\u0629 \u062A\u0642\u062F\u0645 \u062E\u062F\u0645\u0627\u062A \u0627\u0644\u0627\u0646\u062A\u0642\u0627\u0644 \u0627\u0644\u0643\u0627\u0645\u0644 \u0645\u0646 \u0627\u0644\u0623\u0644\u0641 \u0625\u0644\u0649 \u0627\u0644\u064A\u0627\u0621",
        imagine: "\u0631\u062C\u0644 \u064A\u0636\u0639 \u0642\u062F\u0645\u064A\u0647 \u0639\u0644\u0649 \u0627\u0644\u0637\u0627\u0648\u0644\u0629 \u0648\u064A\u0634\u0631\u0628 \u0642\u0647\u0648\u0629 \u0648\u0639\u0645\u0627\u0644 \u064A\u062D\u0645\u0644\u0648\u0646 \u0635\u0646\u0627\u062F\u064A\u0642 \u062E\u0644\u0641\u0647",
