        simplified: "\u062A\u0637\u0628\u064A\u0642 \u0647\u0627\u062A\u0641 \u0644\u0644\u0637\u0642\u0633 \u0641\u064A \u0623\u064A \u0645\u062F\u064A\u0646\u0629 \u0641\u064A \u0627\u0644\u0639\u0627\u0644\u0645",
        imagine: "\u0627\u0645\u0631\u0623\u0629 \u062A\u0646\u0638\u0631 \u0625\u0644\u0649 \u0634\u0627\u0634\u0629 \u0647\u0627\u062A\u0641 \u0648\u0639\u0644\u064A\u0647\u0627 \u0634\u0645\u0633 \u0641\u0648\u0642 \u062E\u0631\u064A\u0637\u0629 \u0625\u064A\u0637\u0627\u0644\u064A\u0627",
