        simplified: "\u062F\u0648\u0631\u0627\u062A \u0641\u064A \u0641\u0646 \u0627\u0644\u062D\u0648\u0627\u0631 \u0645\u0639 \u0627\u0644\u0631\u062C\u0627\u0644 \u0648\u062D\u0644 \u0627\u0644\u062E\u0644\u0627\u0641\u0627\u062A \u0628\u0630\u0643\u0627\u0621",
        imagine: "\u0627\u0645\u0631\u0623\u0629 \u062A\u0642\u0641 \u0623\u0645\u0627\u0645 \u0631\u062C\u0644 \u0648\u0643\u0644\u0627\u0647\u0645\u0627 \u064A\u062D\u0627\u0648\u0644 \u0625\u0642\u0646\u0627\u0639 \u0627\u0644\u0622\u062E\u0631 \u0628\u0623\u0648\u0631\u0627\u0642 \u0641\u064A \u064A\u062F\u064A\u0647",
