      HELP_DATA2["m\xFCndlich_exam1_q1"] = { text: "Antibiotika \u2192 Wirkung \u2192 fr\xFCher viele Krankheiten \u2192 heute resistent \u2192 falsch verwendet \u2192 Heilpflanzen Alternative", meaning: "\u0627\u0644\u0645\u0636\u0627\u062F\u0627\u062A \u0627\u0644\u062D\u064A\u0648\u064A\u0629 \u0643\u0627\u0646\u062A \u0641\u0639\u0627\u0644\u0629 \u0633\u0627\u0628\u0642\u0627\u064B \u0644\u0643\u0646 \u0627\u0644\u0628\u0643\u062A\u064A\u0631\u064A\u0627 \u0623\u0635\u0628\u062D\u062A \u0645\u0642\u0627\u0648\u0645\u0629", keywords: ["Antibiotika", "Wirkung", "resistent", "Heilpflanzen"], simplified: "\u0627\u0644\u0645\u0636\u0627\u062F\u0627\u062A \u0627\u0644\u062D\u064A\u0648\u064A\u0629 \u0643\u0627\u0646\u062A \u062A\u0642\u062A\u0644 \u0627\u0644\u062C\u0631\u0627\u062B\u064A\u0645 \u0644\u0643\u0646\u0647\u0627 \u0623\u0635\u0628\u062D\u062A \u0644\u0627 \u062A\u0624\u062B\u0631\u060C \u0641\u0627\u0644\u0646\u0628\u0627\u062A\u0627\u062A \u0627\u0644\u0637\u0628\u064A\u0629 \u0647\u064A \u0627\u0644\u062D\u0644", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u062C\u064A\u0634\u064B\u0627 \u0645\u0646 \u0627\u0644\u0645\u0636\u0627\u062F\u0627\u062A \u0627\u0644\u062D\u064A\u0648\u064A\u0629 \u{1F52B} \u064A\u0642\u0636\u064A \u0639\u0644\u0649 \u0627\u0644\u062C\u0631\u0627\u062B\u064A\u0645 \u{1F9A0} \u0628\u0633\u0647\u0648\u0644\u0629 \u0641\u064A \u0627\u0644\u0645\u0627\u0636\u064A. \u0644\u0643\u0646 \u0641\u062C\u0623\u0629\u060C \u062A\u062A\u062D\u0648\u0644 \u0627\u0644\u062C\u0631\u0627\u062B\u064A\u0645 \u0625\u0644\u0649 \u0648\u062D\u0648\u0634 \u0636\u062E\u0645\u0629 \u{1F4AA}\u{1F9A0} \u062A\u062E\u0631\u062C \u0645\u0646 \u0627\u0644\u0645\u0633\u062A\u0634\u0641\u0649 \u0648\u062A\u0631\u062A\u062F\u064A \u062F\u0631\u0648\u0639\u064B\u0627 \u0645\u0643\u062A\u0648\u0628\u064B\u0627 \u0639\u0644\u064A\u0647\u0627 'RESISTENT'. \u0627\u0644\u0637\u0628\u064A\u0628 \u064A\u062D\u0627\u0648\u0644 \u0625\u0639\u0637\u0627\u0621 \u0627\u0644\u0645\u0632\u064A\u062F \u0645\u0646 \u0627\u0644\u0645\u0636\u0627\u062F\u0627\u062A \u0644\u0643\u0646\u0647\u0627 \u0644\u0627 \u062A\u0624\u062B\u0631! \u0641\u062C\u0623\u0629\u060C \u062A\u0623\u062A\u064A \u0646\u0628\u0627\u062A\u0627\u062A \u0637\u0628\u064A\u0629 \u{1F33F} \u0639\u0645\u0644\u0627\u0642\u0629 \u0648\u062A\u0642\u0641 \u0623\u0645\u0627\u0645 \u0627\u0644\u0648\u062D\u0648\u0634 \u0648\u062A\u0648\u0642\u0641\u0647\u0627. \u{1F6D1}" };
      HELP_DATA2["m\xFCndlich_exam1_q2"] = { text: "Antibiotika nur wenn n\xF6tig \u2192 resistent \u2192 Heilpflanzen \u2192 gesunde Alternative", meaning: "\u0627\u0644\u0645\u0636\u0627\u062F\u0627\u062A \u0627\u0644\u062D\u064A\u0648\u064A\u0629 \u0641\u0642\u0637 \u0639\u0646\u062F \u0627\u0644\u0636\u0631\u0648\u0631\u0629 \u0627\u0644\u0642\u0635\u0648\u0649", keywords: ["nur wenn n\xF6tig", "resistent", "gesunde Alternative"], simplified: "\u0627\u0644\u0625\u0641\u0631\u0627\u0637 \u0641\u064A \u0627\u0644\u0645\u0636\u0627\u062F\u0627\u062A \u064A\u0633\u0628\u0628 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629\u060C \u0644\u0630\u0627 \u0627\u0633\u062A\u062E\u062F\u0645\u0647\u0627 \u0641\u0642\u0637 \u0639\u0646\u062F \u0627\u0644\u0636\u0631\u0648\u0631\u0629 \u0648\u062C\u0631\u0628 \u0627\u0644\u0646\u0628\u0627\u062A\u0627\u062A \u0627\u0644\u0637\u0628\u064A\u0629 \u0628\u062F\u0644\u0627\u064B \u0645\u0646\u0647\u0627", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0646\u0641\u0633\u0643 \u0641\u064A \u0635\u064A\u062F\u0644\u064A\u0629 \u{1F3E5}. \u062A\u0645\u062F \u064A\u062F\u0643 \u0644\u0634\u0631\u0627\u0621 \u0645\u0636\u0627\u062F \u062D\u064A\u0648\u064A \u{1F48A}\u060C \u0641\u062C\u0623\u0629 \u064A\u0635\u0631\u062E \u0627\u0644\u0635\u064A\u062F\u0644\u064A \u{1F5E3}\uFE0F '\u0644\u0627! \u0641\u0642\u0637 \u0639\u0646\u062F \u0627\u0644\u0636\u0631\u0648\u0631\u0629!' \u062B\u0645 \u062A\u0638\u0647\u0631 \u0634\u0627\u0634\u0629 \u0643\u0628\u064A\u0631\u0629 \u{1F4FA} \u0645\u0643\u062A\u0648\u0628 \u0639\u0644\u064A\u0647\u0627 '\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0632\u0627\u0626\u062F = \u0628\u0643\u062A\u064A\u0631\u064A\u0627 RESISTENT! \u{1F6AB}\u{1F9A0}'. \u062B\u0645 \u064A\u0646\u0645\u0648 \u0646\u0628\u0627\u062A \u0627\u0644\u0646\u0639\u0646\u0627\u0639 \u{1F331} \u0639\u0645\u0644\u0627\u0642 \u0645\u0646 \u0627\u0644\u0623\u0631\u0636 \u0648\u064A\u0639\u0637\u064A\u0643 \u0625\u064A\u0627\u0647 \u0627\u0644\u0635\u064A\u062F\u0644\u064A \u0645\u0628\u062A\u0633\u0645\u064B\u0627 \u{1F60A}\u{1F49A}." };
      HELP_DATA2["m\xFCndlich_exam1_q3"] = { text: "Halsschmerzen \u2192 Arzt \u2192 Tee \u2192 Heilpflanzen \u2192 besser \u2192 nicht immer n\xF6tig", meaning: "\u062A\u062C\u0631\u0628\u0629 \u0634\u062E\u0635\u064A\u0629 \u0645\u0639 \u0627\u0644\u062A\u0647\u0627\u0628 \u0627\u0644\u062D\u0644\u0642", keywords: ["Halsschmerzen", "Arzt", "Tee", "Heilpflanzen"], simplified: "\u0627\u0644\u0637\u0628\u064A\u0628 \u0646\u0635\u062D\u0646\u064A \u0628\u0627\u0644\u0634\u0627\u064A \u0648\u0627\u0644\u0646\u0628\u0627\u062A\u0627\u062A \u0627\u0644\u0637\u0628\u064A\u0629 \u0628\u062F\u0644 \u0627\u0644\u0645\u0636\u0627\u062F\u0627\u062A\u060C \u0648\u062A\u062D\u0633\u0646\u062A \u0628\u0633\u0631\u0639\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0646\u0641\u0633\u0643 \u062C\u0627\u0644\u0633\u064B\u0627 \u0641\u064A \u063A\u0631\u0641\u0629 \u0627\u0644\u0645\u0639\u064A\u0634\u0629 \u{1F6CB}\uFE0F\u060C \u062D\u0644\u0642\u0643 \u064A\u0624\u0644\u0645\u0643 \u0628\u0634\u062F\u0629 \u{1F525}. \u062A\u0630\u0647\u0628 \u0644\u0644\u0637\u0628\u064A\u0628 \u{1F468}\u200D\u2695\uFE0F\u060C \u0644\u0643\u0646\u0647 \u0628\u062F\u0644 \u0623\u0646 \u064A\u0639\u0637\u064A\u0643 \u062F\u0648\u0627\u0621\u060C \u064A\u0642\u062F\u0645 \u0644\u0643 \u0643\u0648\u0628 \u0634\u0627\u064A \u0623\u062E\u0636\u0631 \u{1F375} \u0636\u062E\u0645 \u064A\u062E\u0631\u062C \u0645\u0646\u0647 \u0628\u062E\u0627\u0631 \u0639\u0644\u0649 \u0634\u0643\u0644 \u0646\u0628\u0627\u062A\u0627\u062A \u0637\u0628\u064A\u0629 \u{1F33F}. \u062A\u0634\u0631\u0628 \u0627\u0644\u0643\u0648\u0628 \u0648\u0628\u0639\u062F \u0644\u062D\u0638\u0627\u062A \u064A\u062E\u062A\u0641\u064A \u0627\u0644\u0623\u0644\u0645 \u2728 \u0648\u062A\u0636\u062D\u0643 \u0642\u0627\u0626\u0644\u064B\u0627 '\u0644\u0645 \u0623\u0643\u0646 \u0628\u062D\u0627\u062C\u0629 \u0644\u0645\u0636\u0627\u062F \u062D\u064A\u0648\u064A!' \u{1F604}." };
      HELP_DATA2["m\xFCndlich_exam2_q1"] = { text: "Selber-Kochen \u2192 gesund \u2192 frisch \u2192 ohne Zusatzstoffe \u2192 wissen was drin \u2192 lohnt sich", meaning: "\u0627\u0644\u0637\u0628\u062E \u0627\u0644\u0645\u0646\u0632\u0644\u064A \u0635\u062D\u064A \u0648\u0637\u0627\u0632\u062C", keywords: ["gesund", "frisch", "ohne Zusatzstoffe"], simplified: "\u0639\u0646\u062F\u0645\u0627 \u062A\u0637\u0628\u062E \u0628\u0646\u0641\u0633\u0643\u060C \u0623\u0646\u062A \u062A\u062A\u062D\u0643\u0645 \u0641\u064A \u0627\u0644\u0645\u0643\u0648\u0646\u0627\u062A \u0648\u062A\u062A\u062C\u0646\u0628 \u0627\u0644\u0645\u0648\u0627\u062F \u0627\u0644\u0636\u0627\u0631\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0645\u0637\u0628\u062E\u064B\u0627 \u0645\u0646\u0632\u0644\u064A\u064B\u0627 \u{1F373}\u060C \u0648\u0641\u062C\u0623\u0629 \u062A\u0642\u0641\u0632 \u0627\u0644\u062E\u0636\u0631\u0648\u0627\u062A \u{1F955}\u{1F966} \u0645\u0646 \u0627\u0644\u062B\u0644\u0627\u062C\u0629 \u0648\u062A\u0631\u0642\u0635 \u0641\u0631\u062D\u064B\u0627 \u0644\u0623\u0646\u0647\u0627 \u0633\u062A\u0635\u0628\u062D \u0637\u0639\u0627\u0645\u064B\u0627 \u0635\u062D\u064A\u064B\u0627 \u0628\u062F\u0648\u0646 \u0645\u0648\u0627\u062F \u062D\u0627\u0641\u0638\u0629. \u0648\u0641\u064A \u0627\u0644\u0632\u0627\u0648\u064A\u0629\u060C \u0639\u0644\u0628\u0629 \u0637\u0639\u0627\u0645 \u062C\u0627\u0647\u0632 \u{1F96B} \u062A\u0628\u0643\u064A \u0644\u0623\u0646\u0647\u0627 \u0648\u062D\u064A\u062F\u0629 \u0648\u0645\u0644\u064A\u0626\u0629 \u0628\u0627\u0644\u0645\u0648\u0627\u062F \u0627\u0644\u0643\u064A\u0645\u064A\u0627\u0626\u064A\u0629!" };
      HELP_DATA2["m\xFCndlich_exam2_q2"] = { text: "selbst kochen \u2192 besser \u2192 ges\xFCnder \u2192 Kontrolle \u2192 Zutaten", meaning: "\u0627\u0644\u0637\u0628\u062E \u0627\u0644\u0645\u0646\u0632\u0644\u064A \u0623\u0641\u0636\u0644 \u0648\u0623\u0635\u062D", keywords: ["besser", "ges\xFCnder", "Kontrolle"], simplified: "\u0627\u0644\u0637\u0628\u062E \u0628\u0646\u0641\u0633\u0643 \u064A\u0639\u0646\u064A \u0623\u0646\u062A \u0645\u0646 \u064A\u0642\u0631\u0631 \u0645\u0627\u0630\u0627 \u064A\u062F\u062E\u0644 \u0625\u0644\u0649 \u062C\u0633\u062F\u0643", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0646\u0641\u0633\u0643 \u0642\u0628\u0637\u0627\u0646 \u0633\u0641\u064A\u0646\u0629 \u{1F6A2}\u060C \u0648\u064A\u062F\u0643 \u0639\u0644\u0649 \u0645\u0642\u0648\u062F \u0627\u0644\u0642\u064A\u0627\u062F\u0629. \u0643\u0644 \u0645\u0643\u0648\u0646 \u062A\u0636\u0639\u0647 \u0641\u064A \u0627\u0644\u0637\u0628\u062E\u0629 \u0647\u0648 \u0628\u0648\u0635\u0644\u0629 \u062A\u0648\u062C\u0647 \u0635\u062D\u062A\u0643 \u0646\u062D\u0648 \u0627\u0644\u0623\u0645\u0627\u0646. \u0628\u064A\u0646\u0645\u0627 \u0627\u0644\u0623\u0643\u0644 \u0627\u0644\u062C\u0627\u0647\u0632 \u0645\u062B\u0644 \u0633\u0641\u064A\u0646\u0629 \u0628\u0644\u0627 \u0642\u0628\u0637\u0627\u0646 \u062A\u0635\u0637\u062F\u0645 \u0628\u0635\u062E\u0648\u0631 \u{1FAA8} \u0627\u0644\u0645\u0648\u0627\u062F \u0627\u0644\u0636\u0627\u0631\u0629!" };
      HELP_DATA2["m\xFCndlich_exam2_q3"] = { text: "letzte Woche \u2192 selbst gekocht \u2192 Gem\xFCse \u2192 Obst \u2192 gut geschmeckt \u2192 gesund \u2192 lecker", meaning: "\u062A\u062C\u0631\u0628\u0629 \u0637\u0628\u062E \u0645\u0646\u0632\u0644\u064A\u0629 \u0646\u0627\u062C\u062D\u0629", keywords: ["selbst gekocht", "Gem\xFCse", "Obst", "lecker"], simplified: "\u062C\u0631\u0628\u062A \u0627\u0644\u0637\u0628\u062E \u0627\u0644\u0645\u0646\u0632\u0644\u064A \u0628\u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u0645\u0627\u0636\u064A \u0648\u0643\u0627\u0646 \u0644\u0630\u064A\u0630\u064B\u0627 \u062C\u062F\u064B\u0627 \u0648\u0635\u062D\u064A\u064B\u0627", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0637\u0628\u0642\u064B\u0627 \u0639\u0645\u0644\u0627\u0642\u064B\u0627 \u0645\u0646 \u0627\u0644\u062E\u0636\u0631\u0648\u0627\u062A \u0627\u0644\u0645\u0644\u0648\u0646\u0629 \u{1F957} \u064A\u0628\u062A\u0633\u0645 \u0644\u0643 \u0648\u064A\u0642\u0648\u0644: '\u0623\u0646\u0627 \u0644\u0630\u064A\u0630 \u0648\u0635\u062D\u064A\u060C \u062A\u0639\u0627\u0644 \u0643\u0644\u0646\u064A!' \u0648\u0628\u062C\u0627\u0646\u0628\u0647\u060C \u0639\u0644\u0628\u0629 \u0648\u062C\u0628\u0629 \u0633\u0631\u064A\u0639\u0629 \u{1F354} \u062A\u062A\u0646\u0647\u062F \u0648\u062A\u0642\u0648\u0644: '\u0623\u0646\u0627 \u0633\u0631\u064A\u0639 \u0644\u0643\u0646\u064A \u0644\u0646 \u0623\u062C\u0639\u0644 \u0633\u0639\u064A\u062F\u064B\u0627 \u0645\u062B\u0644 \u0647\u0630\u0627 \u0627\u0644\u0637\u0628\u0642!'" };
      HELP_DATA2["m\xFCndlich_exam3_q1"] = { text: "Rentenalter \u2192 Lebenserwartung steigt \u2192 l\xE4nger arbeiten \u2192 Experten \u2192 flexible Rente \u2192 selbst entscheiden", meaning: "\u0633\u0646 \u0627\u0644\u062A\u0642\u0627\u0639\u062F \u064A\u0632\u062F\u0627\u062F \u0645\u0639 \u0627\u0631\u062A\u0641\u0627\u0639 \u0645\u062A\u0648\u0633\u0637 \u0627\u0644\u0639\u0645\u0631", keywords: ["Rentenalter", "Lebenserwartung", "flexible Rente"], simplified: "\u0627\u0644\u0646\u0627\u0633 \u064A\u0639\u064A\u0634\u0648\u0646 \u0623\u0637\u0648\u0644\u060C \u0644\u0630\u0627 \u064A\u0645\u0643\u0646\u0647\u0645 \u0627\u0644\u0639\u0645\u0644 \u0623\u0643\u062B\u0631 \u0628\u0645\u0631\u0648\u0646\u0629 \u0648\u0627\u062E\u062A\u064A\u0627\u0631 \u0648\u0642\u062A \u0627\u0644\u062A\u0642\u0627\u0639\u062F \u0628\u0623\u0646\u0641\u0633\u0647\u0645", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0633\u0627\u0639\u0629 \u0631\u0645\u0644\u064A\u0629 \u0639\u0645\u0644\u0627\u0642\u0629 \u23F3\u060C \u0627\u0644\u0631\u0645\u0644 \u064A\u0633\u0642\u0637 \u0628\u0628\u0637\u0621. \u0641\u062C\u0623\u0629\u060C \u062A\u062A\u0648\u0642\u0641 \u0627\u0644\u0633\u0627\u0639\u0629 \u0648\u062A\u0638\u0647\u0631 \u064A\u062F \u{1F44B} \u062A\u0648\u0642\u0641 \u0627\u0644\u0631\u0645\u0644. \u0634\u062E\u0635 \u0645\u0633\u0646 \u{1F474} \u064A\u0642\u0641 \u0648\u064A\u0642\u0648\u0644: '\u0623\u0646\u0627 \u0644\u0633\u062A \u0645\u062C\u0628\u0631\u064B\u0627 \u0639\u0644\u0649 \u0627\u0644\u062A\u0642\u0627\u0639\u062F \u0627\u0644\u0622\u0646\u060C \u0633\u0623\u0639\u0645\u0644 \u0637\u0627\u0644\u0645\u0627 \u0623\u0634\u0639\u0631 \u0628\u0627\u0644\u0646\u0634\u0627\u0637!' \u0648\u062A\u0638\u0647\u0631 \u0634\u0627\u0634\u0629 \u{1F4FA} \u0645\u0643\u062A\u0648\u0628 \u0639\u0644\u064A\u0647\u0627 '\u0627\u062E\u062A\u0631 \u0623\u0646\u062A \u0645\u062A\u0649 \u062A\u062A\u0642\u0627\u0639\u062F!'" };
      HELP_DATA2["m\xFCndlich_exam3_q2"] = { text: "Rentenalter flexibel \u2192 entscheiden \u2192 in Rente gehen \u2192 Arbeitszeit einteilen", meaning: "\u0633\u0646 \u0627\u0644\u062A\u0642\u0627\u0639\u062F \u0627\u0644\u0645\u0631\u0646 \u064A\u062A\u064A\u062D \u0644\u0643 \u0627\u0644\u062D\u0631\u064A\u0629", keywords: ["flexibel", "entscheiden", "Arbeitszeit"], simplified: "\u0627\u0644\u062A\u0642\u0627\u0639\u062F \u0627\u0644\u0645\u0631\u0646 \u064A\u0639\u0646\u064A \u0623\u0646\u062A \u0645\u0646 \u062A\u062A\u062D\u0643\u0645 \u0641\u064A \u0648\u0642\u062A \u062E\u0631\u0648\u062C\u0643 \u0645\u0646 \u0627\u0644\u0639\u0645\u0644", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0645\u0641\u062A\u0627\u062D\u064B\u0627 \u0630\u0647\u0628\u064A\u064B\u0627 \u{1F511} \u064A\u0641\u062A\u062D \u0628\u0627\u0628\u064A\u0646: \u0628\u0627\u0628 \u0645\u0643\u062A\u0648\u0628 \u0639\u0644\u064A\u0647 '\u062A\u0642\u0627\u0639\u062F \u0645\u0628\u0643\u0631' \u{1F6AA} \u0648\u0628\u0627\u0628 \u0645\u0643\u062A\u0648\u0628 \u0639\u0644\u064A\u0647 '\u0639\u0645\u0644 \u0623\u0643\u062B\u0631'. \u0623\u0646\u062A \u062A\u0645\u0633\u0643 \u0627\u0644\u0645\u0641\u062A\u0627\u062D \u0648\u062A\u0642\u0631\u0631 \u0623\u064A \u0628\u0627\u0628 \u062A\u062E\u062A\u0627\u0631. \u062A\u0638\u0647\u0631 \u0639\u0644\u0627\u0645\u0629 \u2705 \u062E\u0636\u0631\u0627\u0621 \u0648\u062A\u0642\u0648\u0644: '\u0627\u0644\u0642\u0631\u0627\u0631 \u0644\u0643 \u0648\u062D\u062F\u0643!'" };
      HELP_DATA2["m\xFCndlich_exam3_q3"] = { text: "Onkel \u2192 l\xE4nger gearbeitet \u2192 Tischler \u2192 Arbeitszeiten selbst \u2192 zufrieden \u2192 sinnvoll", meaning: "\u062A\u062C\u0631\u0628\u0629 \u0627\u0644\u0639\u0645 \u0645\u0639 \u0633\u0627\u0639\u0627\u062A \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0645\u0631\u0646\u0629", keywords: ["Onkel", "l\xE4nger gearbeitet", "zufrieden"], simplified: "\u0639\u0645\u064A \u0639\u0645\u0644 \u0628\u0646\u0641\u0633\u0647 \u062C\u062F\u0648\u0644 \u0639\u0645\u0644\u0647 \u0648\u0643\u0627\u0646 \u0633\u0639\u064A\u062F\u064B\u0627 \u062C\u062F\u064B\u0627\u060C \u0648\u0647\u0630\u0627 \u064A\u0624\u0643\u062F \u0641\u0643\u0631\u0629 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0645\u0631\u0646", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0639\u0645\u0643 \u{1F9D4} \u064A\u0642\u0641 \u0623\u0645\u0627\u0645 \u0648\u0631\u0634\u0629 \u0646\u062C\u0627\u0631\u0629 \u{1FA9A}\u060C \u0648\u0639\u0644\u0649 \u0627\u0644\u062D\u0627\u0626\u0637 \u0633\u0627\u0639\u0629 \u23F0 \u0639\u0642\u0627\u0631\u0628\u0647\u0627 \u062A\u0634\u064A\u0631 \u0625\u0644\u0649 \u0633\u0627\u0639\u0627\u062A \u0645\u062E\u062A\u0644\u0641\u0629. \u064A\u0642\u0648\u0644 \u0639\u0645\u0643 \u0645\u0628\u062A\u0633\u0645\u064B\u0627: '\u0623\u0646\u0627 \u0627\u0644\u0630\u064A \u0623\u062D\u062F\u062F \u0645\u062A\u0649 \u0623\u0639\u0645\u0644\u060C \u0644\u0633\u062A \u0639\u0628\u062F\u064B\u0627 \u0644\u0644\u0633\u0627\u0639\u0629!' \u0648\u062A\u0638\u0647\u0631 \u0642\u0637\u0639\u0629 \u062E\u0634\u0628 \u0645\u0646\u062D\u0648\u062A\u0629 \u{1F4BA} \u0631\u0627\u0626\u0639\u0629 \u0643\u062F\u0644\u064A\u0644 \u0639\u0644\u0649 \u0625\u062A\u0642\u0627\u0646\u0647 \u0631\u063A\u0645 \u062A\u0642\u062F\u0645\u0647 \u0641\u064A \u0627\u0644\u0633\u0646." };
      HELP_DATA2["m\xFCndlich_exam4_q1"] = { text: "Lernmethoden \u2192 mehrere Sinne \u2192 H\xF6ren 20% \u2192 H\xF6ren/Sehen/Reden/Tun 90% \u2192 Wiederholen \u2192 Zusammenfassen", meaning: "\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0623\u0643\u062B\u0631 \u0645\u0646 \u062D\u0627\u0633\u0629 \u0641\u064A \u0627\u0644\u062A\u0639\u0644\u0645 \u064A\u0631\u0641\u0639 \u0627\u0644\u0641\u0647\u0645 \u0625\u0644\u0649 90%", keywords: ["mehrere Sinne", "Wiederholen", "Zusammenfassen"], simplified: "\u0627\u0644\u062A\u0639\u0644\u0645 \u0628\u0627\u0644\u0623\u0630\u0646 \u0641\u0642\u0637 \u064A\u0639\u0637\u064A\u0643 20%\u060C \u0623\u0645\u0627 \u0625\u0630\u0627 \u0627\u0633\u062A\u0639\u0645\u0644\u062A \u0627\u0644\u0639\u064A\u0646 \u0648\u0627\u0644\u0623\u0630\u0646 \u0648\u0627\u0644\u064A\u062F \u0648\u0627\u0644\u0641\u0645 \u0641\u062A\u0631\u062A\u0641\u0639 \u0627\u0644\u0646\u0633\u0628\u0629 \u0625\u0644\u0649 90% \u0645\u0639 \u0627\u0644\u062A\u0643\u0631\u0627\u0631 \u0648\u0627\u0644\u062A\u0644\u062E\u064A\u0635", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u062F\u0645\u0627\u063A\u064B\u0627 \u0643\u0628\u064A\u0631\u064B\u0627 \u{1F9E0} \u0648\u0642\u062F \u0633\u062D\u0628 \u0644\u0633\u0627\u0646\u064B\u0627 \u{1F445} \u0648\u0639\u064A\u0646\u064A\u0646 \u{1F440} \u0648\u0623\u0630\u0646\u064B\u0627 \u{1F442} \u0648\u064A\u062F\u064B\u0627 \u270B \u0646\u062D\u0648\u0647. \u062A\u0642\u0648\u0644 \u0627\u0644\u0623\u0630\u0646: '\u0623\u0646\u0627 20% \u0641\u0642\u0637!' \u0641\u064A\u0642\u0627\u0637\u0639\u0647\u0627 \u0627\u0644\u062F\u0645\u0627\u063A: '\u0627\u062C\u062A\u0645\u0639\u0648\u0627 \u062C\u0645\u064A\u0639\u064B\u0627\u060C \u0633\u062A\u0635\u0628\u062D\u0648\u0646 90%!' \u062B\u0645 \u062A\u0638\u0647\u0631 \u0648\u0631\u0642\u0629 \u{1F4DD} \u0648\u0642\u0644\u0645 \u270D\uFE0F \u064A\u0643\u062A\u0628\u0627\u0646 \u0627\u0644\u062A\u0644\u062E\u064A\u0635." };
      HELP_DATA2["m\xFCndlich_exam4_q2"] = { text: "Lerntipps sinnvoll \u2192 mehrere Sinne \u2192 regelm\xE4\xDFig wiederholen \u2192 l\xE4nger im Ged\xE4chtnis", meaning: "\u0646\u0635\u0627\u0626\u062D \u0627\u0644\u062A\u0639\u0644\u0645 \u0645\u0641\u064A\u062F\u0629 \u062C\u062F\u064B\u0627", keywords: ["sinnvoll", "regelm\xE4\xDFig wiederholen", "Ged\xE4chtnis"], simplified: "\u0627\u0644\u062A\u0643\u0631\u0627\u0631 \u0627\u0644\u0645\u0646\u062A\u0638\u0645 \u0648\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0627\u0644\u062D\u0648\u0627\u0633 \u064A\u062B\u0628\u062A \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0629 \u0641\u064A \u0627\u0644\u0630\u0627\u0643\u0631\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0645\u0639\u0644\u0648\u0645\u0627\u062A \u{1F4DA} \u062A\u0631\u064A\u062F \u0627\u0644\u0647\u0631\u0648\u0628 \u0645\u0646 \u0627\u0644\u062F\u0645\u0627\u063A. \u0641\u062C\u0623\u0629\u060C \u062A\u0638\u0647\u0631 \u0623\u0635\u0641\u0627\u062F \u{1F517} \u0648\u062A\u0642\u0648\u0645 \u0628\u0631\u0628\u0637 \u0643\u0644 \u0645\u0639\u0644\u0648\u0645\u0629 \u0628\u0635\u0648\u0631 \u0648\u0623\u0635\u0648\u0627\u062A \u0648\u062D\u0631\u0643\u0627\u062A. \u062A\u062D\u0627\u0648\u0644 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0629 \u0627\u0644\u0641\u0631\u0627\u0631 \u0644\u0643\u0646\u0647\u0627 \u0644\u0627 \u062A\u0633\u062A\u0637\u064A\u0639. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0633\u0627\u0639\u0629 \u23F0 \u062A\u0642\u0648\u0644: '\u0643\u0631\u0631 \u0643\u0644 \u064A\u0648\u0645\u060C \u0648\u0633\u062A\u0628\u0642\u0649 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062A \u062D\u0628\u064A\u0633\u0629 \u0641\u064A \u0630\u0627\u0643\u0631\u062A\u0643 \u0625\u0644\u0649 \u0627\u0644\u0623\u0628\u062F!'" };
