      HELP_DATA2["m\xFCndlich_exam8_q1"] = { text: "Praktikanten \u2192 wenig Geld \u2192 trotzdem zufrieden \u2192 Branche \u2192 Qualifikation \u2192 nur wenige Branchen", meaning: "\u0627\u0644\u0645\u062A\u062F\u0631\u0628\u0648\u0646 \u0631\u0627\u0636\u0648\u0646 \u0631\u063A\u0645 \u0642\u0644\u0629 \u0627\u0644\u0645\u0627\u0644 \u062D\u0633\u0628 \u0627\u0644\u0642\u0637\u0627\u0639 \u0648\u0627\u0644\u0645\u0624\u0647\u0644", keywords: ["Praktikanten", "zufrieden", "Branche"], simplified: "\u0627\u0644\u0645\u062A\u062F\u0631\u0628\u0648\u0646 \u0633\u0639\u062F\u0627\u0621 \u0631\u063A\u0645 \u0642\u0644\u0629 \u0627\u0644\u0631\u0627\u062A\u0628 \u0644\u0643\u0646 \u0647\u0630\u0627 \u064A\u062E\u062A\u0644\u0641 \u062D\u0633\u0628 \u0627\u0644\u0645\u062C\u0627\u0644 \u0648\u0627\u0644\u0645\u0624\u0647\u0644\u0627\u062A", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0645\u062A\u062F\u0631\u0628\u064B\u0627 \u{1F468}\u200D\u{1F393} \u062C\u0627\u0644\u0633\u064B\u0627 \u0639\u0644\u0649 \u0645\u0643\u062A\u0628\u060C \u0623\u0645\u0627\u0645\u0647 \u0643\u0648\u0645\u0629 \u0646\u0642\u0648\u062F \u0635\u063A\u064A\u0631\u0629 \u{1F4B0} \u0644\u0643\u0646\u0647 \u064A\u0628\u062A\u0633\u0645 \u{1F60A}. \u0641\u062C\u0623\u0629\u060C \u062A\u0638\u0647\u0631 \u0645\u0642\u0627\u0628\u0636 \u{1F527} \u0648\u0645\u0641\u0627\u062A\u064A\u062D \u{1F511} \u0648\u062A\u0631\u062A\u0641\u0639 \u0627\u0644\u0646\u0642\u0648\u062F. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0627\u062A: '\u0637\u0628' \u{1F3E5} '\u0647\u0646\u062F\u0633\u0629' \u{1F527} '\u0625\u0639\u0644\u0627\u0645' \u{1F4FA}\u060C \u0628\u0639\u0636\u0647\u0627 \u064A\u0631\u0641\u0639 \u0627\u0644\u0631\u0627\u062A\u0628 \u0648\u0628\u0639\u0636\u0647\u0627 \u0644\u0627." };
      HELP_DATA2["m\xFCndlich_exam8_q2"] = { text: "Praktika wichtig \u2192 Erfahrung \u2192 besser bezahlt \u2192 motiviert \u2192 fair behandelt", meaning: "\u0627\u0644\u062A\u062F\u0631\u064A\u0628 \u0627\u0644\u0639\u0645\u0644\u064A \u0645\u0647\u0645 \u0644\u0644\u062E\u0628\u0631\u0629 \u0648\u064A\u062C\u0628 \u0623\u0646 \u064A\u0643\u0648\u0646 \u0627\u0644\u0623\u062C\u0631 \u0623\u0641\u0636\u0644", keywords: ["wichtig", "Erfahrung", "fair behandelt"], simplified: "\u0627\u0644\u062A\u062F\u0631\u064A\u0628 \u064A\u0645\u0646\u062D\u0643 \u062E\u0628\u0631\u0629 \u0644\u0643\u0646 \u064A\u062C\u0628 \u0623\u0646 \u064A\u064F\u062F\u0641\u0639 \u0644\u0643 \u062C\u064A\u062F\u064B\u0627 \u0644\u062A\u0643\u0648\u0646 \u0645\u062A\u062D\u0645\u0633\u064B\u0627", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0645\u062A\u062F\u0631\u0628\u064B\u0627 \u064A\u0643\u062A\u0628 \u0639\u0644\u0649 \u0644\u0648\u062D\u0629 \u{1F4DD} '\u062E\u0628\u0631\u0629' \u0648\u064A\u0636\u0639\u0647\u0627 \u0641\u064A \u062C\u064A\u0628\u0647. \u0641\u062C\u0623\u0629\u060C \u062A\u0638\u0647\u0631 \u064A\u062F \u{1F932} \u062A\u0636\u0639 \u0646\u0642\u0648\u062F\u064B\u0627 \u{1F4B0} \u0628\u062C\u0627\u0646\u0628\u0647\u0627. \u062B\u0645 \u064A\u0628\u062A\u0633\u0645 \u0627\u0644\u0645\u062A\u062F\u0631\u0628 \u{1F60A} \u0648\u062A\u0638\u0647\u0631 \u0639\u0644\u0627\u0645\u0629 '\u062A\u062D\u0641\u064A\u0632' \u{1F680}. \u062B\u0645 \u064A\u0638\u0647\u0631 \u0645\u064A\u0632\u0627\u0646 \u2696\uFE0F \u064A\u062D\u0642\u0642 \u0627\u0644\u0639\u062F\u0627\u0644\u0629 \u0628\u064A\u0646 \u0627\u0644\u062C\u0647\u062F \u0648\u0627\u0644\u0623\u062C\u0631." };
