      HELP_DATA2["m\xFCndlich_exam9_q1"] = { text: "Sch\xF6nheitsoperationen \u2192 Minderj\xE4hrige \u2192 unn\xF6tige Eingriffe \u2192 Ausnahmen \u2192 schwierig unterscheiden", meaning: "\u0639\u0645\u0644\u064A\u0627\u062A \u0627\u0644\u062A\u062C\u0645\u064A\u0644 \u0644\u0644\u0642\u0635\u0631 \u0645\u062D\u062F\u0648\u062F\u0629 \u0648\u064A\u0635\u0639\u0628 \u0627\u0644\u062A\u0645\u064A\u064A\u0632 \u0628\u064A\u0646 \u0627\u0644\u062D\u0627\u062C\u0629 \u0648\u0627\u0644\u0631\u063A\u0628\u0629", keywords: ["Minderj\xE4hrige", "unn\xF6tige Eingriffe", "schwierig unterscheiden"], simplified: "\u0645\u0646 \u0627\u0644\u0635\u0639\u0628 \u0627\u0644\u062A\u0641\u0631\u0642\u0629 \u0628\u064A\u0646 \u0627\u0644\u062D\u0627\u062C\u0629 \u0627\u0644\u0637\u0628\u064A\u0629 \u0648\u0631\u063A\u0628\u0629 \u0627\u0644\u062A\u062C\u0645\u064A\u0644 \u0639\u0646\u062F \u0627\u0644\u0623\u0637\u0641\u0627\u0644", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0637\u0641\u0644\u0629 \u{1F467} \u062A\u0642\u0641 \u0623\u0645\u0627\u0645 \u0645\u0631\u0622\u0629 \u{1F487} \u0648\u062A\u0646\u0638\u0631 \u0625\u0644\u0649 \u0623\u0646\u0641\u0647\u0627. \u0641\u062C\u0623\u0629\u060C \u064A\u0638\u0647\u0631 \u0645\u0644\u0627\u0643 \u{1F47C} \u0648\u0645\u0639\u0647 \u0633\u0643\u064A\u0646 \u{1F52A}\u060C \u0648\u0634\u064A\u0637\u0627\u0646 \u{1F47F} \u0648\u0645\u0639\u0647 \u0633\u0643\u064A\u0646 \u0622\u062E\u0631. \u0627\u0644\u0627\u062B\u0646\u0627\u0646 \u064A\u0635\u0631\u062E\u0627\u0646: '\u0623\u0646\u0627 \u0627\u0644\u0635\u0648\u0627\u0628!' \u062A\u0638\u0647\u0631 \u0639\u0644\u0627\u0645\u0629 \u0627\u0633\u062A\u0641\u0647\u0627\u0645 \u2753 \u0643\u0628\u064A\u0631\u0629 \u0648\u062A\u062A\u0633\u0627\u0621\u0644: '\u0645\u0646 \u0639\u0644\u0649 \u062D\u0642\u061F'" };
      HELP_DATA2["m\xFCndlich_exam9_q2"] = { text: "unn\xF6tige Operationen vermeiden \u2192 Notf\xE4lle okay \u2192 Kinder lernen \u2192 selbstbewusst umgehen", meaning: "\u062A\u062C\u0646\u0628 \u0627\u0644\u0639\u0645\u0644\u064A\u0627\u062A \u063A\u064A\u0631 \u0627\u0644\u0636\u0631\u0648\u0631\u064A\u0629\u060C \u0648\u0627\u0644\u0637\u0648\u0627\u0631\u0626 \u0627\u0633\u062A\u062B\u0646\u0627\u0621\u060C \u0648\u0639\u0644\u0651\u0645 \u0637\u0641\u0644\u0643 \u0627\u0644\u062B\u0642\u0629 \u0628\u0646\u0641\u0633\u0647", keywords: ["vermeiden", "Notf\xE4lle", "selbstbewusst"], simplified: "\u0644\u0627 \u062A\u062C\u0631\u064A \u0639\u0645\u0644\u064A\u0627\u062A \u062A\u062C\u0645\u064A\u0644 \u063A\u064A\u0631 \u0636\u0631\u0648\u0631\u064A\u0629 \u0644\u0644\u0623\u0637\u0641\u0627\u0644\u060C \u0648\u0639\u0644\u0645\u0647\u0645 \u0623\u0646 \u064A\u0643\u0648\u0646\u0648\u0627 \u0648\u0627\u062B\u0642\u064A\u0646 \u0645\u0646 \u0623\u0646\u0641\u0633\u0647\u0645", imagine: "\u{1F9E0} \u062A\u062E\u064A\u062F \u0637\u0641\u0644\u0627\u064B \u062E\u062C\u0648\u0644\u0627\u064B \u{1F614} \u064A\u0646\u0638\u0631 \u0625\u0644\u0649 \u0627\u0644\u0645\u0631\u0622\u0629. \u0641\u062C\u0623\u0629\u060C \u062A\u0633\u0642\u0637 \u0633\u0645\u0627\u0621 \u0627\u0644\u062B\u0642\u0629 \u{1F4AA} \u0639\u0644\u064A\u0647 \u0648\u064A\u0635\u0628\u062D \u0648\u0627\u0642\u0641\u064B\u0627 \u0628\u0634\u0645\u0648\u062E \u{1F981}. \u062A\u0638\u0647\u0631 \u0644\u0648\u062D\u0629 \u{1F5BC}\uFE0F \u0645\u0643\u062A\u0648\u0628 \u0639\u0644\u064A\u0647\u0627 '\u062C\u0645\u0627\u0644\u0643 \u0627\u0644\u062F\u0627\u062E\u0644\u064A \u0623\u0647\u0645'. \u062B\u0645 \u064A\u062E\u062A\u0641\u064A \u0627\u0644\u0645\u0634\u0631\u0637 \u{1F52A} \u0646\u0647\u0627\u0626\u064A\u064B\u0627." };
      HELP_DATA2["m\xFCndlich_exam9_q3"] = { text: "Mitsch\xFCler \u2192 schiefe Z\xE4hne \u2192 Zahnspange \u2192 unsicher \u2192 unterst\xFCtzt \u2192 selbstbewusst", meaning: "\u062A\u062C\u0631\u0628\u0629 \u0632\u0645\u064A\u0644: \u0623\u0633\u0646\u0627\u0646 \u0645\u0639\u0648\u062C\u0629\u060C \u062A\u0642\u0648\u064A\u0645\u060C \u062F\u0639\u0645 \u0627\u0644\u0623\u0647\u0644\u060C \u062B\u0642\u0629", keywords: ["schiefe Z\xE4hne", "Zahnspange", "selbstbewusst"], simplified: "\u0632\u0645\u064A\u0644\u064A \u0643\u0627\u0646 \u062E\u062C\u0648\u0644\u0627\u064B \u0645\u0646 \u0623\u0633\u0646\u0627\u0646\u0647 \u0644\u0643\u0646 \u0627\u0644\u062F\u0639\u0645 \u062D\u0648\u0644\u0647 \u0625\u0644\u0649 \u0634\u062E\u0635 \u0648\u0627\u062B\u0642", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0641\u0645\u0627\u064B \u0628\u0623\u0633\u0646\u0627\u0646 \u0645\u0639\u0648\u062C\u0629 \u{1F9B7}\u060C \u062B\u0645 \u062A\u0648\u0636\u0639 \u062A\u0642\u0648\u064A\u0645\u0627\u062A \u0645\u0639\u062F\u0646\u064A\u0629 \u{1F517}. \u0627\u0644\u0648\u062C\u0647 \u0643\u0627\u0646 \u0639\u0627\u0628\u0633\u064B\u0627 \u{1F612} \u062B\u0645 \u064A\u0638\u0647\u0631 \u0627\u0644\u0623\u0647\u0644 \u{1F468}\u200D\u{1F469}\u200D\u{1F466} \u0648\u064A\u0635\u0641\u0642\u0648\u0646 \u{1F44F}. \u0628\u0639\u062F \u0641\u062A\u0631\u0629\u060C \u062A\u0628\u062A\u0633\u0645 \u0627\u0644\u0623\u0633\u0646\u0627\u0646 \u{1F601} \u0648\u062A\u062A\u0623\u0644\u0642 \u2B50. \u062B\u0645 \u064A\u0642\u0648\u0644 \u0627\u0644\u0641\u0645: '\u0634\u0643\u0631\u064B\u0627 \u0644\u0644\u062F\u0627\u0639\u0645\u064A\u0646!'" };
      HELP_DATA2["m\xFCndlich_exam10_q1"] = { text: "Kinderuniversit\xE4ten \u2192 2002 \u2192 Kinder 8\u201312 \u2192 Universit\xE4t T\xFCbingen \u2192 freiwillig \u2192 ohne Noten \u2192 beliebt \u2192 \xC4rzte \u2192 Bewegung", meaning: "\u062C\u0627\u0645\u0639\u0627\u062A \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0645\u0646 8-12 \u0633\u0646\u0629 \u0641\u064A \u062A\u0648\u0628\u0646\u063A\u0646 \u0645\u0646\u0630 2002\u060C \u062A\u0637\u0648\u0639\u064A\u0629 \u0648\u0628\u062F\u0648\u0646 \u062F\u0631\u062C\u0627\u062A \u0644\u0643\u0646 \u0627\u0644\u0623\u0637\u0628\u0627\u0621 \u064A\u0646\u062A\u0642\u062F\u0648\u0646 \u0642\u0644\u0629 \u0627\u0644\u062D\u0631\u0643\u0629", keywords: ["Kinderuniversit\xE4ten", "freiwillig", "ohne Noten"], simplified: "\u0623\u0637\u0641\u0627\u0644 \u064A\u062A\u0639\u0644\u0645\u0648\u0646 \u0641\u064A \u0627\u0644\u062C\u0627\u0645\u0639\u0629 \u0628\u062F\u0648\u0646 \u0636\u063A\u0637 \u062F\u0631\u062C\u0627\u062A\u060C \u0644\u0643\u0646\u0647\u0645 \u064A\u062D\u062A\u0627\u062C\u0648\u0646 \u0644\u0631\u064A\u0627\u0636\u0629 \u0623\u0643\u062B\u0631", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0623\u0637\u0641\u0627\u0644\u0627\u064B \u{1F467}\u{1F9D2} \u064A\u0631\u062A\u062F\u0648\u0646 \u0642\u0628\u0639\u0627\u062A \u062A\u062E\u0631\u062C \u{1F393} \u0648\u064A\u062C\u0644\u0633\u0648\u0646 \u0641\u064A \u0642\u0627\u0639\u0629 \u062C\u0627\u0645\u0639\u064A\u0629. \u0641\u062C\u0623\u0629\u060C \u062A\u0638\u0647\u0631 \u0643\u0631\u0629 \u0642\u062F\u0645 \u26BD \u0648\u062A\u0637\u0644\u0628 \u0627\u0644\u0644\u0639\u0628. \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u064A\u062A\u062C\u0627\u0647\u0644\u0648\u0646\u0647\u0627\u060C \u0641\u062A\u062D\u0632\u0646 \u0627\u0644\u0643\u0631\u0629. \u062B\u0645 \u064A\u0638\u0647\u0631 \u0637\u0628\u064A\u0628 \u{1F468}\u200D\u2695\uFE0F \u0648\u064A\u0642\u0648\u0644: '\u062A\u062D\u0631\u0643\u0648\u0627! \u0627\u0644\u0635\u062D\u0629 \u0623\u0647\u0645 \u0645\u0646 \u0627\u0644\u0642\u0628\u0639\u0629!'" };
      HELP_DATA2["m\xFCndlich_exam10_q2"] = { text: "Kinderuniversit\xE4ten gute Idee \u2192 Interesse \u2192 Wissenschaft \u2192 Sport \u2192 Bewegung", meaning: "\u062C\u0627\u0645\u0639\u0627\u062A \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0641\u0643\u0631\u0629 \u062C\u064A\u062F\u0629 \u062A\u0646\u0645\u064A \u0627\u0644\u0641\u0636\u0648\u0644 \u0627\u0644\u0639\u0644\u0645\u064A \u0645\u0639 \u0636\u0631\u0648\u0631\u0629 \u0627\u0644\u0631\u064A\u0627\u0636\u0629", keywords: ["gute Idee", "Interesse", "Wissenschaft"], simplified: "\u062C\u0627\u0645\u0639\u0627\u062A \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u062A\u0646\u0645\u064A \u062D\u0628 \u0627\u0644\u0639\u0644\u0645 \u0644\u0643\u0646 \u0627\u0644\u0631\u064A\u0627\u0636\u0629 \u0636\u0631\u0648\u0631\u064A\u0629 \u0623\u064A\u0636\u064B\u0627", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u062F\u0645\u0627\u063A \u0637\u0641\u0644 \u{1F9E0} \u064A\u0646\u0645\u0648 \u0648\u062A\u062E\u0631\u062C \u0645\u0646\u0647 \u0645\u062C\u0631\u0629 \u{1F52D} \u0648\u0643\u0648\u0627\u0643\u0628 \u{1F30D}. \u0641\u062C\u0623\u0629\u060C \u062A\u0638\u0647\u0631 \u0639\u0636\u0644\u0627\u062A \u{1F4AA} \u0648\u062A\u0631\u0642\u0635. \u0627\u0644\u0637\u0641\u0644 \u064A\u062C\u0631\u064A \u0628\u064A\u0646 \u0627\u0644\u0643\u062A\u0627\u0628 \u{1F4D6} \u0648\u0627\u0644\u0643\u0631\u0629 \u26BD \u0648\u064A\u0642\u0648\u0644: '\u0623\u0631\u064A\u062F \u0627\u0644\u0627\u062B\u0646\u064A\u0646 \u0645\u0639\u064B\u0627!' \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u062A\u0648\u0627\u0632\u0646 = \u0646\u062C\u0627\u062D'" };
      HELP_DATA2["m\xFCndlich_exam10_q3"] = { text: "Sommerferien \u2192 Hallenbad \u2192 schwimmen \u2192 ohne Noten \u2192 ohne Stress \u2192 Neues gelernt", meaning: "\u062A\u062C\u0631\u0628\u0629 \u062A\u0639\u0644\u0645 \u0627\u0644\u0633\u0628\u0627\u062D\u0629 \u0628\u062F\u0648\u0646 \u0636\u063A\u0637 \u0641\u064A \u0627\u0644\u0635\u064A\u0641", keywords: ["Sommerferien", "schwimmen", "ohne Druck"], simplified: "\u062A\u0639\u0644\u0645\u062A \u0627\u0644\u0633\u0628\u0627\u062D\u0629 \u0641\u064A \u0627\u0644\u0625\u062C\u0627\u0632\u0629 \u0628\u062F\u0648\u0646 \u062F\u0631\u062C\u0627\u062A \u0648\u0628\u062F\u0648\u0646 \u0642\u0644\u0642\u060C \u0648\u0643\u0627\u0646\u062A \u062A\u062C\u0631\u0628\u0629 \u0631\u0627\u0626\u0639\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0637\u0641\u0644\u0627\u064B \u064A\u0642\u0641\u0632 \u0641\u064A \u0627\u0644\u0645\u0633\u0628\u062D \u{1F3CA}\u200D\u2642\uFE0F\u060C \u0648\u0641\u0648\u0642 \u0631\u0623\u0633\u0647 \u0639\u0644\u0627\u0645\u0629 '\u0628\u062F\u0648\u0646 \u062F\u0631\u062C\u0627\u062A' \u{1F6AB}\u{1F4DD}. \u064A\u0633\u0628\u062D \u0648\u064A\u0636\u062D\u0643 \u{1F60A}\u060C \u0648\u062A\u062E\u0631\u062C \u0645\u0646 \u0627\u0644\u0645\u0627\u0621 \u0646\u062C\u0645\u0629 \u2B50. \u062B\u0645 \u064A\u0642\u0648\u0644: '\u062A\u0639\u0644\u0645\u062A \u0628\u062F\u0648\u0646 \u062E\u0648\u0641!' \u0648\u062A\u0638\u0647\u0631 \u0633\u0645\u0643\u0629 \u{1F41F} \u062A\u0631\u0641\u0639 \u0632\u0639\u0646\u0641\u062A\u0647\u0627 \u0643\u0639\u0644\u0627\u0645\u0629 \u0646\u062C\u0627\u062D." };
      HELP_DATA2["m\xFCndlich_exam11_q1"] = { text: "Fast Food \u2192 Sucht \u2192 Ratten \u2192 Kontrolle verloren \u2192 Menschen achten", meaning: "\u0627\u0644\u0648\u062C\u0628\u0627\u062A \u0627\u0644\u0633\u0631\u064A\u0639\u0629 \u0642\u062F \u062A\u0633\u0628\u0628 \u0627\u0644\u0625\u062F\u0645\u0627\u0646 \u0645\u062B\u0644\u0645\u0627 \u062D\u062F\u062B \u0645\u0639 \u0627\u0644\u0641\u0626\u0631\u0627\u0646", keywords: ["Fast Food", "Sucht", "Ratten"], simplified: "\u0627\u0644\u0641\u0626\u0631\u0627\u0646 \u0641\u0642\u062F\u062A \u0627\u0644\u0633\u064A\u0637\u0631\u0629 \u0628\u0639\u062F \u0623\u0643\u0644 \u0627\u0644\u062F\u0647\u0648\u0646\u060C \u0648\u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u064A\u062C\u0628 \u0623\u0646 \u064A\u062D\u0630\u0631", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0641\u0623\u0631\u064B\u0627 \u{1F42D} \u064A\u0623\u0643\u0644 \u0628\u0631\u062C\u0631 \u{1F354} \u0628\u0634\u0631\u0627\u0647\u0629\u060C \u062B\u0645 \u064A\u062F\u0648\u0631 \u0641\u064A \u0639\u062C\u0644\u0629 \u{1F3A1} \u0628\u0633\u0631\u0639\u0629 \u062C\u0646\u0648\u0646\u064A\u0629 \u0648\u0644\u0627 \u064A\u062A\u0648\u0642\u0641. \u0641\u062C\u0623\u0629\u060C \u064A\u062A\u062D\u0648\u0644 \u0625\u0644\u0649 \u0641\u0623\u0631 \u0636\u062E\u0645 \u{1F4AA}\u{1F9B7} \u0648\u064A\u0643\u0633\u0631 \u0627\u0644\u0642\u0641\u0635. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629 \u26A0\uFE0F: '\u0647\u0644 \u0623\u0646\u062A \u0645\u062B\u0644 \u0647\u0630\u0627 \u0627\u0644\u0641\u0623\u0631\u061F'" };
      HELP_DATA2["m\xFCndlich_exam11_q2"] = { text: "Fast Food vermeiden \u2192 s\xFCchtig \u2192 Gesundheit schaden \u2192 gesunde Ern\xE4hrung besser", meaning: "\u062A\u062C\u0646\u0628 \u0627\u0644\u0648\u062C\u0628\u0627\u062A \u0627\u0644\u0633\u0631\u064A\u0639\u0629 \u0641\u0647\u064A \u062A\u0633\u0628\u0628 \u0627\u0644\u0625\u062F\u0645\u0627\u0646 \u0648\u062A\u0636\u0631 \u0628\u0627\u0644\u0635\u062D\u0629", keywords: ["vermeiden", "s\xFCchtig", "gesunde Ern\xE4hrung"], simplified: "\u0627\u0644\u0623\u0643\u0644 \u0627\u0644\u0635\u062D\u064A \u0623\u0641\u0636\u0644 \u062F\u0627\u0626\u0645\u064B\u0627\u060C \u0648\u0627\u0644\u0648\u062C\u0628\u0627\u062A \u0627\u0644\u0633\u0631\u064A\u0639\u0629 \u062A\u062F\u0645\u0631 \u0635\u062D\u062A\u0643", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0634\u062E\u0635\u064B\u0627 \u064A\u0645\u0633\u0643 \u0628\u064A\u062F\u0647 \u0627\u0644\u064A\u0645\u0646\u0649 \u0633\u0644\u0637\u0629 \u{1F957} \u062E\u0636\u0631\u0627\u0621\u060C \u0648\u0628\u0627\u0644\u064A\u0633\u0631\u0649 \u0628\u0631\u062C\u0631 \u{1F354}. \u0641\u062C\u0623\u0629\u060C \u062A\u062A\u062D\u0631\u0643 \u0627\u0644\u064A\u062F \u0627\u0644\u064A\u0633\u0631\u0649 \u0648\u062A\u0631\u0645\u064A \u0627\u0644\u0628\u0631\u062C\u0631 \u0628\u0639\u064A\u062F\u064B\u0627 \u{1F5D1}\uFE0F\u060C \u0628\u064A\u0646\u0645\u0627 \u062A\u0631\u0641\u0639 \u0627\u0644\u0633\u0644\u0637\u0629 \u0639\u0627\u0644\u064A\u064B\u0627 \u{1F31F}. \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u062E\u062A\u0631 \u0635\u062D\u062A\u0643!'" };
      HELP_DATA2["m\xFCndlich_exam11_q3"] = { text: "Cousin \u2192 viel Fast Food \u2192 nicht aufh\xF6ren \u2192 sp\xE4ter ges\xFCnder \u2192 besser gef\xFChlt", meaning: "\u062A\u062C\u0631\u0628\u0629 \u0627\u0628\u0646 \u0627\u0644\u0639\u0645: \u0623\u0643\u0644 \u0633\u0631\u064A\u0639 \u0628\u0643\u062B\u0631\u0629\u060C \u062B\u0645 \u062A\u062D\u0648\u0644 \u0644\u0644\u0623\u0643\u0644 \u0627\u0644\u0635\u062D\u064A \u0648\u062A\u062D\u0633\u0646", keywords: ["Cousin", "Fast Food", "besser gef\xFChlt"], simplified: "\u0627\u0628\u0646 \u0639\u0645\u064A \u0643\u0627\u0646 \u0645\u062F\u0645\u0646\u064B\u0627 \u0644\u0644\u0648\u062C\u0628\u0627\u062A \u0627\u0644\u0633\u0631\u064A\u0639\u0629\u060C \u0648\u0644\u0645\u0627 \u062A\u0631\u0643\u0647\u0627 \u0634\u0639\u0631 \u0628\u062A\u062D\u0633\u0646 \u0643\u0628\u064A\u0631", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0627\u0628\u0646 \u0639\u0645\u0643 \u{1F9D1} \u0623\u0645\u0627\u0645 \u062C\u0628\u0644 \u0645\u0646 \u0648\u062C\u0628\u0627\u062A \u0633\u0631\u064A\u0639\u0629 \u{1F35F}\u{1F354}\u060C \u0648\u0639\u0644\u064A\u0647 \u0642\u064A\u0648\u062F \u26D3\uFE0F. \u0641\u062C\u0623\u0629\u060C \u064A\u0646\u0641\u062C\u0631 \u0627\u0644\u062C\u0628\u0644 \u{1F4A5} \u0648\u064A\u062E\u0631\u062C \u0645\u0646 \u062A\u062D\u062A\u0647 \u0633\u0644\u0637\u0629 \u062E\u0636\u0631\u0627\u0621 \u{1F957}. \u064A\u0631\u0643\u0636 \u0646\u062D\u0648\u0647\u0627 \u0648\u064A\u0623\u0643\u0644\u0647\u0627\u060C \u062B\u0645 \u062A\u0638\u0647\u0631 \u0639\u0636\u0644\u0627\u062A \u{1F4AA} \u0648\u0648\u062C\u0647 \u0645\u0628\u062A\u0633\u0645 \u{1F60A}. \u064A\u0642\u0648\u0644: '\u0627\u0644\u062D\u0631\u064A\u0629 \u0641\u064A \u0627\u0644\u0635\u062D\u0629!'" };
      HELP_DATA2["m\xFCndlich_exam12_q1"] = { text: "Zweisprachigkeit \u2192 Kinder \u2192 Vorteile Kultur \u2192 Denken \u2192 Zukunft", meaning: "\u062A\u0639\u062F\u062F \u0627\u0644\u0644\u063A\u0627\u062A \u0639\u0646\u062F \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0645\u0641\u064A\u062F \u062B\u0642\u0627\u0641\u064A\u064B\u0627 \u0648\u0641\u0643\u0631\u064A\u064B\u0627 \u0648\u0645\u0633\u062A\u0642\u0628\u0644\u064A\u064B\u0627", keywords: ["Zweisprachigkeit", "Vorteile", "Kultur"], simplified: "\u0627\u0644\u0637\u0641\u0644 \u062B\u0646\u0627\u0626\u064A \u0627\u0644\u0644\u063A\u0629 \u064A\u062A\u0645\u062A\u0639 \u0628\u0645\u064A\u0632\u0627\u062A \u0641\u064A \u0627\u0644\u062A\u0641\u0643\u064A\u0631 \u0648\u0627\u0644\u062B\u0642\u0627\u0641\u0629 \u0648\u0627\u0644\u0641\u0631\u0635", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u062F\u0645\u0627\u063A \u0637\u0641\u0644 \u{1F9E0} \u064A\u0646\u0642\u0633\u0645 \u0625\u0644\u0649 \u0646\u0635\u0641\u064A\u0646: \u0646\u0635\u0641 \u064A\u062A\u062D\u062F\u062B \u0623\u0644\u0645\u0627\u0646\u064A\u064B\u0627 \u{1F1E9}\u{1F1EA}\u060C \u0648\u0646\u0635\u0641 \u064A\u062A\u062D\u062F\u062B \u0639\u0631\u0628\u064A\u064B\u0627 \u{1F1F8}\u{1F1E6}. \u0641\u062C\u0623\u0629\u060C \u064A\u062E\u0631\u062C \u0645\u0646 \u0627\u0644\u062F\u0645\u0627\u063A \u0623\u0634\u0639\u0629 \u{1F4A1} \u062A\u0636\u064A\u0621 \u0627\u0644\u0639\u0627\u0644\u0645. \u062A\u0638\u0647\u0631 \u062E\u0631\u064A\u0637\u0629 \u{1F5FA}\uFE0F \u0648\u062A\u062A\u0648\u0633\u0639\u060C \u062B\u0645 \u062A\u0638\u0647\u0631 \u0641\u0631\u0635 \u0639\u0645\u0644 \u{1F4BC} \u0648\u0633\u0641\u0631 \u2708\uFE0F." };
      HELP_DATA2["m\xFCndlich_exam12_q2"] = { text: "Zweisprachigkeit positiv \u2192 Kulturen \u2192 reisen \u2192 arbeiten \u2192 kommunizieren", meaning: "\u062A\u0639\u062F\u062F \u0627\u0644\u0644\u063A\u0627\u062A \u064A\u0641\u062A\u062D \u0622\u0641\u0627\u0642 \u0627\u0644\u0633\u0641\u0631 \u0648\u0627\u0644\u0639\u0645\u0644 \u0648\u0627\u0644\u062A\u0648\u0627\u0635\u0644", keywords: ["positiv", "Kulturen", "kommunizieren"], simplified: "\u062A\u0639\u062F\u062F \u0627\u0644\u0644\u063A\u0627\u062A \u064A\u0633\u0647\u0644 \u0627\u0644\u0633\u0641\u0631 \u0648\u0627\u0644\u0639\u0645\u0644 \u0648\u0627\u0644\u062A\u0641\u0627\u0647\u0645 \u0645\u0639 \u0627\u0644\u062B\u0642\u0627\u0641\u0627\u062A \u0627\u0644\u0623\u062E\u0631\u0649", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0637\u0641\u0644\u0627\u064B \u064A\u0631\u0643\u0628 \u0637\u0627\u0626\u0631\u0629 \u2708\uFE0F \u0648\u064A\u062D\u0645\u0644 \u062C\u0648\u0627\u0632 \u0633\u0641\u0631 \u064A\u062D\u0645\u0644 \u0623\u0639\u0644\u0627\u0645\u064B\u0627 \u0645\u062A\u0639\u062F\u062F\u0629 \u{1F3F3}\uFE0F\u200D\u{1F308}. \u064A\u0647\u0628\u0637 \u0641\u064A \u0628\u0644\u062F \u062C\u062F\u064A\u062F\u060C \u064A\u062A\u062D\u062F\u062B \u0645\u0639 \u0627\u0644\u0646\u0627\u0633 \u{1F4AC}\u060C \u0648\u064A\u0628\u062F\u0623 \u0627\u0644\u0639\u0645\u0644 \u{1F4BC}. \u062B\u0645 \u062A\u0638\u0647\u0631 \u062C\u0633\u0648\u0631 \u{1F309} \u062A\u0631\u0628\u0637 \u0628\u064A\u0646 \u0627\u0644\u062B\u0642\u0627\u0641\u0627\u062A \u0648\u062A\u0643\u062A\u0628 '\u0644\u063A\u0629 \u0648\u0627\u062D\u062F\u0629 = \u062C\u0633\u0631 \u0648\u0627\u062D\u062F\u060C \u0644\u063A\u062A\u0627\u0646 = \u062C\u0633\u0631\u0627\u0646!'" };
      HELP_DATA2["m\xFCndlich_exam12_q3"] = { text: "Freund \u2192 kleine Schwester \u2192 zwei Sprachen \u2192 schwierig \u2192 sp\xE4ter gut gesprochen", meaning: "\u062A\u062C\u0631\u0628\u0629 \u0623\u062E\u062A \u0635\u062F\u064A\u0642: \u0635\u0639\u0648\u0628\u0629 \u0641\u064A \u0627\u0644\u0628\u062F\u0627\u064A\u0629 \u062B\u0645 \u0625\u062A\u0642\u0627\u0646", keywords: ["kleine Schwester", "zwei Sprachen", "gut gesprochen"], simplified: "\u0623\u062E\u062A \u0635\u062F\u064A\u0642 \u0627\u0644\u0635\u063A\u064A\u0631\u0629 \u062A\u0639\u0644\u0645\u062A \u0644\u063A\u062A\u064A\u0646\u060C \u0648\u0627\u062C\u0647\u062A \u0635\u0639\u0648\u0628\u0629 \u062B\u0645 \u0623\u062A\u0642\u0646\u062A\u0647\u0645\u0627", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0637\u0641\u0644\u0629 \u0635\u063A\u064A\u0631\u0629 \u{1F467} \u062A\u062D\u0645\u0644 \u0643\u062A\u0627\u0628\u064A\u0646 \u{1F4DA}\u{1F4DA}\u060C \u062A\u0633\u0642\u0637 \u0645\u0646\u0647\u0645\u0627 \u0641\u062A\u062A\u0639\u062B\u0631. \u062A\u0628\u0643\u064A \u0642\u0644\u064A\u0644\u0627\u064B \u{1F622} \u062B\u0645 \u062A\u0645\u0633\u062D \u062F\u0645\u0648\u0639\u0647\u0627. \u0628\u0639\u062F \u0641\u062A\u0631\u0629\u060C \u062A\u0637\u064A\u0631 \u0627\u0644\u0643\u062A\u0628 \u2708\uFE0F \u0648\u062A\u062F\u062E\u0644 \u0625\u0644\u0649 \u0631\u0623\u0633\u0647\u0627 \u{1F9E0} \u0628\u0633\u0644\u0627\u0633\u0629. \u062B\u0645 \u062A\u0642\u0641 \u0648\u062A\u0642\u0648\u0644 \u0628\u0643\u0644 \u0641\u062E\u0631: '\u0623\u0646\u0627 \u0623\u062A\u062D\u062F\u062B \u0644\u063A\u062A\u064A\u0646!' \u0648\u062A\u0638\u0647\u0631 \u0646\u062C\u0645\u0629 \u2B50 \u0639\u0644\u0649 \u062C\u0628\u064A\u0646\u0647\u0627." };
      HELP_DATA2["m\xFCndlich_exam13_q1"] = { text: "Blutspenden \u2192 Deutschland \u2192 15.000 t\xE4glich \u2192 wenige spenden \u2192 Gesundheitscheck \u2192 Leben retten", meaning: "\u0623\u0644\u0645\u0627\u0646\u064A\u0627 \u062A\u062D\u062A\u0627\u062C 15,000 \u062A\u0628\u0631\u0639 \u062F\u0645 \u064A\u0648\u0645\u064A\u064B\u0627\u060C \u0644\u0643\u0646 \u0627\u0644\u0642\u0644\u064A\u0644 \u0641\u0642\u0637 \u064A\u062A\u0628\u0631\u0639\u0648\u0646", keywords: ["Blutspenden", "Gesundheitscheck", "Leben retten"], simplified: "\u0627\u0644\u062F\u0645 \u0627\u0644\u0645\u0646\u0642\u0648\u0644 \u064A\u0646\u0642\u0630 \u062D\u064A\u0627\u0629\u060C \u0648\u0627\u0644\u0641\u062D\u0635 \u0627\u0644\u0637\u0628\u064A \u0645\u062C\u0627\u0646\u064A\u060C \u062A\u0628\u0631\u0639 \u0648\u0627\u0646\u0642\u0630 \u062D\u064A\u0627\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0645\u0633\u062A\u0634\u0641\u0649 \u{1F3E5}\u060C 15,000 \u0633\u0631\u064A\u0631 \u0641\u0627\u0631\u063A \u0628\u0627\u0646\u062A\u0638\u0627\u0631 \u0627\u0644\u062F\u0645. \u0641\u062C\u0623\u0629\u060C \u064A\u062F\u062E\u0644 \u0623\u0634\u062E\u0627\u0635 \u{1F465} \u0642\u0644\u064A\u0644\u0648\u0646 \u0641\u0642\u0637. \u0644\u0643\u0646 \u0646\u0642\u0637\u0629 \u062F\u0645 \u0648\u0627\u062D\u062F\u0629 \u{1FA78} \u062A\u062A\u062D\u0648\u0644 \u0625\u0644\u0649 \u0642\u0644\u0628 \u064A\u0646\u0628\u0636 \u2764\uFE0F \u0648\u062A\u0646\u0642\u0630 \u0633\u0631\u064A\u0631\u064B\u0627. \u062B\u0645 \u062A\u062A\u0636\u0627\u0639\u0641 \u0627\u0644\u0646\u0642\u0627\u0637 \u0648\u062A\u0645\u0644\u0623 \u0643\u0644 \u0627\u0644\u0623\u0633\u0631\u0629. \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u062A\u0628\u0631\u0639 \u0648\u0627\u062D\u062F = \u062D\u064A\u0627\u0629 \u0648\u0627\u062D\u062F\u0629!'" };
      HELP_DATA2["m\xFCndlich_exam13_q2"] = { text: "Blutspenden wichtig \u2192 Leben retten \u2192 mehr Menschen spenden", meaning: "\u0627\u0644\u062A\u0628\u0631\u0639 \u0628\u0627\u0644\u062F\u0645 \u0645\u0647\u0645 \u062C\u062F\u064B\u0627\u060C \u064A\u062C\u0628 \u0623\u0646 \u064A\u062A\u0628\u0631\u0639 \u0627\u0644\u0645\u0632\u064A\u062F \u0645\u0646 \u0627\u0644\u0646\u0627\u0633", keywords: ["wichtig", "Leben retten", "mehr Menschen"], simplified: "\u062A\u0628\u0631\u0639 \u0628\u0627\u0644\u062F\u0645\u060C \u0641\u0623\u0646\u062A \u062A\u0646\u0642\u0630 \u062D\u064A\u0627\u0629 \u0628\u0634\u0631. \u0623\u0643\u062B\u0631 \u0627\u0644\u0646\u0627\u0633 \u062A\u0641\u0639\u0644 \u0630\u0644\u0643", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0634\u062E\u0635\u064B\u0627 \u062C\u0627\u0644\u0633\u064B\u0627 \u0639\u0644\u0649 \u0643\u0631\u0633\u064A \u{1FA91}\u060C \u0648\u064A\u062F\u0647 \u0645\u062A\u0635\u0644\u0629 \u0628\u0643\u064A\u0633 \u062F\u0645 \u{1FA78}. \u0641\u062C\u0623\u0629\u060C \u064A\u0638\u0647\u0631 \u0634\u062E\u0635 \u0622\u062E\u0631 \u{1F9D1} \u064A\u0631\u0643\u0636 \u0648\u064A\u062C\u0644\u0633 \u0628\u062C\u0627\u0646\u0628\u0647. \u062B\u0645 \u062B\u0627\u0644\u062B \u0648\u0631\u0627\u0628\u0639. \u064A\u062A\u0633\u0627\u0628\u0642\u0648\u0646 \u0644\u0645\u0644\u0621 \u0627\u0644\u0643\u064A\u0633. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0634\u0627\u0634\u0629 \u{1F4FA}: '\u0643\u0644\u0645\u0627 \u0632\u0627\u062F \u0639\u062F\u062F \u0627\u0644\u0645\u062A\u0628\u0631\u0639\u064A\u0646\u060C \u0632\u0627\u062F \u0639\u062F\u062F \u0627\u0644\u0623\u0631\u0648\u0627\u062D \u0627\u0644\u062A\u064A \u062A\u064F\u0646\u0642\u0630!'" };
      HELP_DATA2["m\xFCndlich_exam13_q3"] = { text: "Freund \u2192 Krankenhaus \u2192 Blutgruppe \u2192 eingeladen \u2192 gespendet", meaning: "\u062A\u062C\u0631\u0628\u0629 \u062A\u0628\u0631\u0639 \u0628\u0627\u0644\u062F\u0645: \u0635\u062F\u064A\u0642 \u062F\u0639\u0627\u0646\u064A\u060C \u0648\u0639\u0631\u0641\u062A \u0641\u0635\u064A\u0644\u062A\u064A \u0648\u062A\u0628\u0631\u0639\u062A", keywords: ["Krankenhaus", "Blutgruppe", "gespendet"], simplified: "\u0635\u062F\u064A\u0642 \u062F\u0639\u0627\u0646\u064A \u0644\u0644\u062A\u0628\u0631\u0639\u060C \u0639\u0631\u0641\u062A \u0641\u0635\u064A\u0644\u0629 \u062F\u0645\u064A \u0648\u062A\u0628\u0631\u0639\u062A\u060C \u0643\u0627\u0646\u062A \u062A\u062C\u0631\u0628\u0629 \u062C\u0645\u064A\u0644\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0635\u062F\u064A\u0642\u064A\u0646 \u{1F9D1}\u{1F91D}\u{1F9D1} \u064A\u062F\u062E\u0644\u0627\u0646 \u0627\u0644\u0645\u0633\u062A\u0634\u0641\u0649 \u{1F3E5}. \u0623\u062D\u062F\u0647\u0645\u0627 \u064A\u0642\u0648\u0644: '\u062A\u0639\u0627\u0644 \u0646\u0639\u0631\u0641 \u0641\u0635\u0627\u0626\u0644 \u062F\u0645\u0646\u0627'. \u064A\u062E\u0631\u062C\u0627\u0646 \u0648\u0628\u0637\u0627\u0642\u0629 \u0641\u064A \u0627\u0644\u064A\u062F \u{1F0CF} \u0645\u0643\u062A\u0648\u0628 \u0639\u0644\u064A\u0647\u0627 'O+' \u0648'A-'. \u062B\u0645 \u064A\u062A\u0628\u0631\u0639\u0627\u0646 \u0648\u064A\u062E\u0631\u062C\u0627\u0646 \u0648\u0647\u0645\u0627 \u064A\u0636\u062D\u0643\u0627\u0646 \u{1F60A}. \u062A\u0638\u0647\u0631 \u0641\u0642\u0627\u0639\u0629: '\u0645\u0639\u064B\u0627 \u0646\u0635\u0646\u0639 \u0627\u0644\u0641\u0627\u0631\u0642!'" };
      HELP_DATA2["m\xFCndlich_exam14_q1"] = { text: "Lachen \u2192 Kinder \u2192 h\xE4ufiger \u2192 Angst reduzieren \u2192 Immunsystem st\xE4rken \u2192 Therapie", meaning: "\u0627\u0644\u0636\u062D\u0643 \u064A\u0642\u0644\u0644 \u0627\u0644\u062E\u0648\u0641 \u0648\u064A\u0642\u0648\u064A \u0627\u0644\u0645\u0646\u0627\u0639\u0629 \u0648\u064A\u0633\u062A\u062E\u062F\u0645 \u0643\u0639\u0644\u0627\u062C \u0641\u064A \u0627\u0644\u0645\u0633\u062A\u0634\u0641\u064A\u0627\u062A", keywords: ["Lachen", "Immunsystem", "Therapie"], simplified: "\u0627\u0644\u0636\u062D\u0643 \u0645\u0641\u064A\u062F \u062C\u062F\u064B\u0627 \u0644\u0644\u0635\u062D\u0629 \u0627\u0644\u0646\u0641\u0633\u064A\u0629 \u0648\u0627\u0644\u062C\u0633\u062F\u064A\u0629 \u0648\u064A\u0633\u062A\u062E\u062F\u0645 \u0641\u064A \u0627\u0644\u0639\u0644\u0627\u062C", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0645\u0633\u062A\u0634\u0641\u0649 \u{1F3E5}\u060C \u0645\u0631\u0636\u0649 \u062D\u0632\u064A\u0646\u0648\u0646 \u{1F61E}. \u0641\u062C\u0623\u0629\u060C \u064A\u062F\u062E\u0644 \u0645\u0647\u0631\u062C \u{1F921} \u0648\u064A\u0628\u062F\u0623 \u0628\u0625\u0636\u062D\u0627\u0643\u0647\u0645. \u062A\u062E\u062A\u0641\u064A \u0627\u0644\u0648\u062C\u0648\u0647 \u0627\u0644\u062D\u0632\u064A\u0646\u0629 \u0648\u062A\u0638\u0647\u0631 \u0636\u062D\u0643\u0627\u062A \u{1F602}. \u062B\u0645 \u062A\u0638\u0647\u0631 \u062F\u0631\u0639 \u{1F6E1}\uFE0F \u064A\u062D\u0645\u064A \u0645\u0646 \u0627\u0644\u0623\u0645\u0631\u0627\u0636. \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u0636\u062D\u0643 \u0623\u0641\u0636\u0644 \u062F\u0648\u0627\u0621!'" };
      HELP_DATA2["m\xFCndlich_exam14_q2"] = { text: "Lachen wichtig \u2192 Gesundheit \u2192 Alltag \u2192 vorsichtig \u2192 Auslachen verletzen", meaning: "\u0627\u0644\u0636\u062D\u0643 \u0645\u0647\u0645 \u0644\u0643\u0646 \u0627\u0644\u0633\u062E\u0631\u064A\u0629 \u062A\u0624\u0630\u064A \u0627\u0644\u0622\u062E\u0631\u064A\u0646", keywords: ["wichtig", "Gesundheit", "Auslachen"], simplified: "\u0627\u0636\u062D\u0643\u060C \u0644\u0643\u0646 \u0644\u0627 \u062A\u0633\u062E\u0631 \u0645\u0646 \u0627\u0644\u0622\u062E\u0631\u064A\u0646\u060C \u0641\u0627\u0644\u0636\u062D\u0643 \u0627\u0644\u0645\u0641\u064A\u062F \u0647\u0648 \u0627\u0644\u0630\u064A \u0645\u0639 \u0627\u0644\u0646\u0627\u0633 \u0644\u0627 \u0639\u0644\u064A\u0647\u0645", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0634\u062E\u0635\u064B\u0627 \u064A\u0636\u062D\u0643 \u0628\u0635\u0648\u062A \u0639\u0627\u0644\u064D \u{1F602} \u0648\u0641\u062C\u0623\u0629 \u064A\u062A\u062D\u0648\u0644 \u0636\u062D\u0643\u0647 \u0625\u0644\u0649 \u0633\u0647\u0627\u0645 \u{1F3F9} \u062A\u0635\u064A\u0628 \u0634\u062E\u0635\u064B\u0627 \u0622\u062E\u0631 \u0641\u064A\u0624\u0644\u0645\u0647 \u{1F622}. \u062B\u0645 \u064A\u062A\u0648\u0642\u0641\u060C \u0648\u064A\u0628\u062F\u0623 \u0628\u0627\u0644\u0636\u062D\u0643 \u0645\u0639 \u0627\u0644\u0634\u062E\u0635 \u0627\u0644\u0622\u062E\u0631 \u{1F91D}. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0641\u0642\u0627\u0639\u0629: '\u0627\u0636\u062D\u0643 \u0645\u0639 \u0627\u0644\u0646\u0627\u0633\u060C \u0644\u0627 \u0639\u0644\u064A\u0647\u0645!'" };
      HELP_DATA2["m\xFCndlich_exam14_q3"] = { text: "Freunde \u2192 lustiger Film \u2192 viel gelacht \u2192 entspannter \u2192 Stress reduziert", meaning: "\u062A\u062C\u0631\u0628\u0629: \u0641\u064A\u0644\u0645 \u0645\u0636\u062D\u0643 \u0645\u0639 \u0627\u0644\u0623\u0635\u062F\u0642\u0627\u0621 \u064A\u0642\u0644\u0644 \u0627\u0644\u062A\u0648\u062A\u0631", keywords: ["lustiger Film", "viel gelacht", "Stress reduziert"], simplified: "\u0634\u0627\u0647\u062F\u062A \u0641\u064A\u0644\u0645\u064B\u0627 \u0645\u0636\u062D\u0643\u064B\u0627 \u0645\u0639 \u0623\u0635\u062F\u0642\u0627\u0626\u064A\u060C \u0636\u062D\u0643\u0646\u0627 \u0643\u062B\u064A\u0631\u064B\u0627 \u0648\u0627\u0631\u062A\u0627\u062D \u0623\u0639\u0635\u0627\u0628\u0646\u0627", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0645\u062C\u0645\u0648\u0639\u0629 \u0623\u0635\u062F\u0642\u0627\u0621 \u{1F465} \u062C\u0627\u0644\u0633\u064A\u0646 \u0639\u0644\u0649 \u0623\u0631\u064A\u0643\u0629 \u{1F6CB}\uFE0F \u0623\u0645\u0627\u0645 \u062A\u0644\u0641\u0627\u0632 \u{1F4FA}. \u064A\u062E\u0631\u062C \u0645\u0646 \u0627\u0644\u062A\u0644\u0641\u0627\u0632 \u0645\u0648\u062C\u0629 \u0636\u062D\u0643 \u{1F30A} \u062A\u063A\u0645\u0631\u0647\u0645. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0633\u0627\u0639\u0629 \u062A\u0648\u0642\u064A\u062A \u23F1\uFE0F \u064A\u0642\u0644 \u0641\u064A\u0647\u0627 \u0627\u0644\u062A\u0648\u062A\u0631. \u062B\u0645 \u064A\u062A\u0646\u0641\u0633\u0648\u0646 \u0628\u0639\u0645\u0642 \u{1F9D8} \u0648\u064A\u0642\u0648\u0644\u0648\u0646: '\u0647\u0630\u0627 \u0623\u0641\u0636\u0644 \u0639\u0644\u0627\u062C!'" };
      HELP_DATA2["m\xFCndlich_exam15_q1"] = { text: "Gefundene Sachen \u2192 nicht behalten \u2192 Besitzer finden \u2192 Belohnung", meaning: "\u0627\u0644\u0623\u0634\u064A\u0627\u0621 \u0627\u0644\u0645\u0641\u0642\u0648\u062F\u0629 \u064A\u062C\u0628 \u0625\u0631\u062C\u0627\u0639\u0647\u0627 \u0644\u0635\u0627\u062D\u0628\u0647\u0627\u060C \u0648\u0642\u062F \u062A\u062D\u0635\u0644 \u0639\u0644\u0649 \u0645\u0643\u0627\u0641\u0623\u0629", keywords: ["gefunden", "Besitzer finden", "Belohnung"], simplified: "\u0644\u0627 \u062A\u062D\u062A\u0641\u0638 \u0628\u0627\u0644\u0634\u064A\u0621 \u0627\u0644\u0645\u0641\u0642\u0648\u062F\u060C \u0627\u0628\u062D\u062B \u0639\u0646 \u0635\u0627\u062D\u0628\u0647 \u062A\u0643\u0627\u0641\u0623", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0634\u062E\u0635\u064B\u0627 \u064A\u062C\u062F \u0645\u062D\u0641\u0638\u0629 \u0646\u0642\u0648\u062F \u{1F4B0} \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636. \u064A\u062D\u0627\u0648\u0644 \u0623\u0646 \u064A\u0641\u062A\u062D\u0647\u0627\u060C \u0641\u062A\u0635\u0631\u062E \u0627\u0644\u0645\u062D\u0641\u0638\u0629: '\u0623\u0646\u0627 \u0644\u0633\u062A \u0644\u0643!' \u0641\u064A\u0635\u062F\u0645 \u0648\u064A\u063A\u0644\u0642\u0647\u0627. \u062B\u0645 \u064A\u0630\u0647\u0628 \u0644\u0644\u0634\u0631\u0637\u0629 \u{1F46E} \u0648\u064A\u0633\u0644\u0645\u0647\u0627. \u0628\u0639\u062F \u064A\u0648\u0645\u060C \u064A\u0639\u0648\u062F \u0635\u0627\u062D\u0628\u0647\u0627 \u{1F9D1} \u0648\u064A\u0645\u0646\u062D\u0647 \u062C\u0627\u0626\u0632\u0629 \u{1F381}. \u062B\u0645 \u064A\u0628\u062A\u0633\u0645 \u{1F970}." };
      HELP_DATA2["m\xFCndlich_exam15_q2"] = { text: "Gefundene Sachen abgeben \u2192 ehrlich \u2192 fair \u2192 Recht des Besitzers", meaning: "\u0625\u0631\u062C\u0627\u0639 \u0627\u0644\u0645\u0641\u0642\u0648\u062F\u0627\u062A \u062A\u0635\u0631\u0641 \u0635\u0627\u062F\u0642 \u0648\u0639\u0627\u062F\u0644\u060C \u0641\u0627\u0644\u0645\u0627\u0644\u0643 \u0644\u0647 \u0627\u0644\u062D\u0642", keywords: ["abgeben", "ehrlich", "fair"], simplified: "\u0627\u0644\u0635\u062F\u0642 \u0648\u0627\u0644\u0639\u062F\u0644 \u064A\u0642\u062A\u0636\u064A\u0627\u0646 \u0625\u0631\u062C\u0627\u0639 \u0627\u0644\u0645\u0641\u0642\u0648\u062F\u0627\u062A \u0625\u0644\u0649 \u0623\u0635\u062D\u0627\u0628\u0647\u0627", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0634\u062E\u0635\u064A\u0646: \u0627\u0644\u0623\u0648\u0644 \u064A\u062D\u062A\u0641\u0638 \u0628\u0634\u064A\u0621 \u0648\u062C\u062F\u0647 \u{1F575}\uFE0F \u0648\u064A\u0638\u0647\u0631 \u0639\u0644\u064A\u0647 \u0639\u0644\u0627\u0645\u0629 '\u0644\u0635' \u{1F44E}. \u0648\u0627\u0644\u0622\u062E\u0631 \u064A\u0631\u062C\u0639\u0647 \u0648\u064A\u0638\u0647\u0631 \u0639\u0644\u064A\u0647 \u0639\u0644\u0627\u0645\u0629 '\u0635\u0627\u062F\u0642' \u{1F44D} \u0648\u062A\u0627\u062C \u{1F451}. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0645\u064A\u0632\u0627\u0646 \u2696\uFE0F \u064A\u0631\u062C\u062D \u0643\u0641\u0629 \u0627\u0644\u0635\u062F\u0642. \u062B\u0645 \u064A\u0635\u0631\u062E \u0627\u0644\u0645\u0627\u0644\u0643: '\u0647\u0630\u0627 \u062D\u0642\u064A!'" };
      HELP_DATA2["m\xFCndlich_exam15_q3"] = { text: "Freund \u2192 Brieftasche \u2192 Polizei \u2192 abgegeben \u2192 Belohnung", meaning: "\u062A\u062C\u0631\u0628\u0629 \u0635\u062F\u064A\u0642: \u0648\u062C\u062F \u0645\u062D\u0641\u0638\u0629\u060C \u0633\u0644\u0645\u0647\u0627 \u0644\u0644\u0634\u0631\u0637\u0629\u060C \u0648\u0643\u0648\u0641\u0626", keywords: ["Brieftasche", "Polizei", "Belohnung"], simplified: "\u0635\u062F\u064A\u0642\u064A \u0648\u062C\u062F \u0645\u062D\u0641\u0638\u0629 \u0648\u0630\u0647\u0628 \u0628\u0647\u0627 \u0644\u0644\u0634\u0631\u0637\u0629\u060C \u0648\u0634\u0643\u0631\u0647 \u0635\u0627\u062D\u0628\u0647\u0627 \u0648\u0623\u0639\u0637\u0627\u0647 \u0645\u0643\u0627\u0641\u0623\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0635\u062F\u064A\u0642\u0643 \u{1F9D1} \u064A\u062C\u062F \u0645\u062D\u0641\u0638\u0629 \u0641\u064A \u0627\u0644\u0634\u0627\u0631\u0639\u060C \u064A\u0631\u0643\u0636 \u0628\u0647\u0627 \u0625\u0644\u0649 \u0645\u0631\u0643\u0632 \u0627\u0644\u0634\u0631\u0637\u0629 \u{1F3E2}. \u062B\u0645 \u064A\u0639\u0648\u062F \u0645\u0628\u062A\u0633\u0645\u064B\u0627 \u{1F60A}. \u0628\u0639\u062F\u0647\u0627\u060C \u064A\u0638\u0647\u0631 \u0634\u062E\u0635 \u063A\u0631\u064A\u0628 \u{1F9D1} \u0648\u064A\u0639\u0627\u0646\u0642\u0647 \u{1F917} \u0648\u064A\u0636\u0639 \u0641\u064A \u064A\u062F\u0647 \u0646\u0642\u0648\u062F\u064B\u0627 \u{1F4B0}. \u062B\u0645 \u064A\u0642\u0648\u0644 \u0635\u062F\u064A\u0642\u0643: '\u0643\u0646\u062A \u0633\u0623\u0634\u0639\u0631 \u0628\u0627\u0644\u0630\u0646\u0628 \u0644\u0648 \u0627\u062D\u062A\u0641\u0638\u062A \u0628\u0647\u0627!'" };
      HELP_DATA2["m\xFCndlich_exam16_q1"] = { text: "Tiere \u2192 Geschenk \u2192 Freude \u2192 Verantwortung \u2192 Zeit \u2192 Pflege", meaning: "\u0627\u0644\u062D\u064A\u0648\u0627\u0646 \u0647\u062F\u064A\u0629 \u062A\u062C\u0644\u0628 \u0627\u0644\u0641\u0631\u062D\u0629 \u0644\u0643\u0646\u0647\u0627 \u062A\u062A\u0637\u0644\u0628 \u0645\u0633\u0624\u0648\u0644\u064A\u0629 \u0648\u0648\u0642\u062A\u064B\u0627 \u0648\u0631\u0639\u0627\u064A\u0629", keywords: ["Tiere", "Verantwortung", "Zeit", "Pflege"], simplified: "\u0627\u0644\u0647\u062F\u064A\u0629 \u0627\u0644\u062D\u064A\u0648\u0627\u0646\u064A\u0629 \u062A\u062D\u062A\u0627\u062C \u0625\u0644\u0649 \u062A\u0641\u0643\u064A\u0631 \u0639\u0645\u064A\u0642\u060C \u0641\u0647\u064A \u0645\u0633\u0624\u0648\u0644\u064A\u0629 \u0643\u0628\u064A\u0631\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0637\u0641\u0644\u0627\u064B \u064A\u0641\u062A\u062D \u0647\u062F\u064A\u0629 \u{1F381} \u0648\u064A\u062C\u062F \u062C\u0631\u0648\u064B\u0627 \u{1F436}\u060C \u064A\u0635\u0631\u062E \u0641\u0631\u062D\u064B\u0627. \u0628\u0639\u062F \u0623\u064A\u0627\u0645\u060C \u0627\u0644\u062C\u0631\u0648 \u064A\u0643\u0628\u0631 \u0648\u064A\u062D\u062A\u0627\u062C \u0644\u0644\u0645\u0634\u064A \u0648\u0627\u0644\u0637\u0639\u0627\u0645 \u0648\u0627\u0644\u062D\u0645\u0627\u0645. \u0627\u0644\u0637\u0641\u0644 \u064A\u0631\u0643\u0636 \u062E\u0644\u0641 \u0627\u0644\u062C\u0631\u0648 \u0645\u0646\u0647\u0643\u064B\u0627. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0641\u0643\u0631 \u0642\u0628\u0644 \u0623\u0646 \u062A\u0647\u062F\u064A!'" };
      HELP_DATA2["m\xFCndlich_exam16_q2"] = { text: "Tier kein spontanes Geschenk \u2192 sprechen \u2192 Verantwortung \u2192 Zeit", meaning: "\u0627\u0644\u062D\u064A\u0648\u0627\u0646 \u0647\u062F\u064A\u0629 \u0644\u064A\u0633\u062A \u0645\u0641\u0627\u062C\u0626\u0629 \u062C\u064A\u062F\u0629\u060C \u062A\u062D\u062F\u062B \u0645\u0639 \u0627\u0644\u0634\u062E\u0635 \u0623\u0648\u0644\u0627\u064B", keywords: ["kein Geschenk", "sprechen", "Verantwortung"], simplified: "\u0644\u0627 \u062A\u0647\u062F\u0650 \u062D\u064A\u0648\u0627\u0646\u064B\u0627 \u0641\u062C\u0623\u0629\u060C \u0646\u0627\u0642\u0634 \u0627\u0644\u0623\u0645\u0631 \u0645\u0639 \u0627\u0644\u0634\u062E\u0635 \u0623\u0648\u0644\u0627\u064B\u060C \u0641\u0627\u0644\u062D\u064A\u0648\u0627\u0646 \u0645\u0633\u0624\u0648\u0644\u064A\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0634\u062E\u0635\u064B\u0627 \u064A\u0642\u062F\u0645 \u062C\u0631\u0648\u064B\u0627 \u0643\u0647\u062F\u064A\u0629 \u0645\u0641\u0627\u062C\u0626\u0629 \u{1F381}\u060C \u0641\u064A\u062A\u0641\u0627\u062C\u0623 \u0627\u0644\u0634\u062E\u0635 \u0627\u0644\u0622\u062E\u0631 \u0648\u064A\u062A\u0631\u0627\u062C\u0639 \u062E\u0627\u0626\u0641\u064B\u0627 \u{1F628}. \u062B\u0645 \u064A\u0638\u0647\u0631 \u062D\u0648\u0627\u0631 \u{1F4AC} \u0628\u064A\u0646\u0647\u0645\u0627 \u064A\u062A\u0641\u0642\u0627\u0646 \u0641\u064A\u0647 \u0639\u0644\u0649 \u0646\u0648\u0639 \u0627\u0644\u062D\u064A\u0648\u0627\u0646 \u0648\u0627\u0644\u0645\u0633\u0624\u0648\u0644\u064A\u0629. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0639\u0644\u0627\u0645\u0629 \u2705 \u062E\u0636\u0631\u0627\u0621 \u0648\u064A\u0628\u062A\u0633\u0645\u0627\u0646 \u0645\u0639\u064B\u0627." };
      HELP_DATA2["m\xFCndlich_exam16_q3"] = { text: "Nachbar \u2192 Kind \u2192 Hund \u2192 gl\xFCcklich \u2192 sp\xE4ter k\xFCmmern", meaning: "\u0627\u0644\u062C\u0627\u0631 \u0623\u0647\u062F\u0649 \u0627\u0628\u0646\u0647 \u0643\u0644\u0628\u064B\u0627\u060C \u0627\u0628\u062A\u0647\u062C \u0623\u0648\u0644\u0627\u064B \u062B\u0645 \u062A\u0637\u0644\u0628 \u0627\u0644\u0631\u0639\u0627\u064A\u0629", keywords: ["Nachbar", "Hund", "gl\xFCcklich"], simplified: "\u0627\u0644\u0637\u0641\u0644 \u0643\u0627\u0646 \u0633\u0639\u064A\u062F\u064B\u0627 \u062C\u062F\u064B\u0627 \u0628\u0627\u0644\u0643\u0644\u0628\u060C \u0644\u0643\u0646 \u0627\u0644\u0639\u0627\u0626\u0644\u0629 \u0627\u0636\u0637\u0631\u062A \u0644\u0644\u0639\u0646\u0627\u064A\u0629 \u0628\u0647 \u064A\u0648\u0645\u064A\u064B\u0627 \u0644\u0627\u062D\u0642\u064B\u0627", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0637\u0641\u0644\u0627\u064B \u064A\u0644\u0639\u0628 \u0645\u0639 \u0643\u0644\u0628\u0647 \u{1F415} \u0648\u064A\u0636\u062D\u0643 \u{1F60A}. \u0628\u0639\u062F \u0641\u062A\u0631\u0629\u060C \u0627\u0644\u0643\u0644\u0628 \u064A\u0643\u0628\u0631 \u0648\u064A\u062C\u0644\u0633 \u0628\u062C\u0627\u0646\u0628 \u0627\u0644\u0628\u0627\u0628 \u{1F6AA} \u0645\u0646\u062A\u0638\u0631\u064B\u0627 \u0627\u0644\u062E\u0631\u0648\u062C. \u0627\u0644\u0637\u0641\u0644 \u064A\u0626\u0646 \u0645\u0646 \u0627\u0644\u062A\u0639\u0628 \u{1F629} \u0648\u064A\u0637\u0644\u0628 \u0627\u0644\u0645\u0633\u0627\u0639\u062F\u0629 \u0645\u0646 \u0648\u0627\u0644\u062F\u064A\u0647. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0623\u064A\u0627\u0645 \u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u{1F4C5} \u0643\u0644\u0647\u0627 \u0645\u0643\u062A\u0648\u0628 \u0639\u0644\u064A\u0647\u0627 '\u0631\u0639\u0627\u064A\u0629 \u0643\u0644\u0628'." };
      HELP_DATA2["m\xFCndlich_exam17_q1"] = { text: "Hausaufgaben \u2192 m\xFCde \u2192 keine Hilfe \u2192 Wiederholen wichtig \u2192 Selbstst\xE4ndigkeit f\xF6rdern", meaning: "\u0627\u0644\u0648\u0627\u062C\u0628\u0627\u062A \u0627\u0644\u0645\u0646\u0632\u0644\u064A\u0629 \u0645\u0631\u0647\u0642\u0629 \u0623\u062D\u064A\u0627\u0646\u064B\u0627 \u0644\u0643\u0646\u0647\u0627 \u062A\u0642\u0648\u064A \u0627\u0644\u062A\u0643\u0631\u0627\u0631 \u0648\u0627\u0644\u0627\u0639\u062A\u0645\u0627\u062F \u0639\u0644\u0649 \u0627\u0644\u0630\u0627\u062A", keywords: ["Hausaufgaben", "m\xFCde", "Selbstst\xE4ndigkeit"], simplified: "\u0627\u0644\u0628\u0639\u0636 \u064A\u0631\u0641\u0636\u0647\u0627 \u0644\u0644\u062A\u0639\u0628\u060C \u0648\u0627\u0644\u0628\u0639\u0636 \u064A\u0631\u0627\u0647\u0627 \u0636\u0631\u0648\u0631\u064A\u0629 \u0644\u0644\u062A\u0643\u0631\u0627\u0631 \u0648\u0627\u0644\u0627\u0633\u062A\u0642\u0644\u0627\u0644\u064A\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u062A\u0644\u0645\u064A\u0630\u064B\u0627 \u0646\u0627\u0626\u0645\u064B\u0627 \u0639\u0644\u0649 \u0645\u0643\u062A\u0628\u0647 \u{1F971}\u060C \u0648\u0627\u0644\u0643\u062A\u0628 \u0645\u0628\u0639\u062B\u0631\u0629 \u{1F4DA}. \u0641\u062C\u0623\u0629\u060C \u062A\u0646\u0647\u0636 \u0627\u0644\u0643\u062A\u0628 \u0648\u062A\u0635\u0641 \u0646\u0641\u0633\u0647\u0627 \u0648\u062A\u062C\u0644\u0633 \u0645\u0643\u0627\u0646\u0647. \u062B\u0645 \u064A\u0633\u062A\u064A\u0642\u0638 \u0648\u064A\u062C\u062F \u0627\u0644\u0645\u0647\u0627\u0645 \u0645\u0646\u062C\u0632\u0629 \u{1F3AF}. \u064A\u062A\u0639\u0644\u0645 \u0643\u064A\u0641 \u064A\u0639\u062A\u0645\u062F \u0639\u0644\u0649 \u0646\u0641\u0633\u0647 \u0648\u064A\u0628\u062A\u0633\u0645." };
      HELP_DATA2["m\xFCndlich_exam17_q2"] = { text: "Hausaufgaben notwendig \u2192 helfen \u2192 zu viele \u2192 m\xFCde \u2192 Freizeit weg", meaning: "\u0627\u0644\u0648\u0627\u062C\u0628\u0627\u062A \u0636\u0631\u0648\u0631\u064A\u0629 \u0623\u062D\u064A\u0627\u0646\u064B\u0627 \u0644\u0643\u0646 \u0643\u062B\u0631\u062A\u0647\u0627 \u0645\u0631\u0647\u0642\u0629", keywords: ["notwendig", "helfen", "Freizeit"], simplified: "\u0627\u0644\u0648\u0627\u062C\u0628 \u0627\u0644\u0645\u0646\u0632\u0644\u064A \u0645\u0641\u064A\u062F \u0644\u0643\u0646 \u0627\u0644\u0625\u0641\u0631\u0627\u0637 \u0641\u064A\u0647 \u064A\u0646\u0647\u0643 \u0627\u0644\u062A\u0644\u0645\u064A\u0630 \u0648\u064A\u0636\u064A\u0639 \u0648\u0642\u062A\u0647", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u062C\u0628\u0644\u064B\u0627 \u0645\u0646 \u0627\u0644\u0648\u0627\u062C\u0628\u0627\u062A \u{1F4DA}\u26F0\uFE0F\u060C \u062A\u0644\u0645\u064A\u0630 \u064A\u062D\u0627\u0648\u0644 \u062A\u0633\u0644\u0642\u0647 \u0648\u064A\u0643\u0627\u062F \u064A\u0633\u0642\u0637. \u062B\u0645 \u062A\u0635\u0628\u062D \u0645\u0637\u0631\u0642\u0629 \u{1F528} \u0648\u062A\u0643\u0633\u0631 \u0627\u0644\u062C\u0628\u0644 \u0625\u0644\u0649 \u0642\u0637\u0639 \u0635\u063A\u064A\u0631\u0629. \u062A\u0638\u0647\u0631 \u0633\u0627\u0639\u0629 \u23F0 \u0648\u064A\u062C\u0644\u0633 \u0627\u0644\u062A\u0644\u0645\u064A\u0630 \u0644\u064A\u0633\u062A\u0631\u064A\u062D \u0641\u064A \u062D\u062F\u064A\u0642\u0629 \u{1F333}. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u062A\u0648\u0627\u0632\u0646!'" };
      HELP_DATA2["m\xFCndlich_exam17_q3"] = { text: "Ich \u2192 viele Hausaufgaben \u2192 m\xFCde \u2192 Wiederholen \u2192 besser verstanden \u2192 Pr\xFCfungen", meaning: "\u062A\u062C\u0631\u0628\u0629: \u062A\u0639\u0628\u062A \u0645\u0646 \u0643\u062B\u0631\u0629 \u0627\u0644\u0648\u0627\u062C\u0628\u0627\u062A \u0644\u0643\u0646 \u0627\u0644\u062A\u0643\u0631\u0627\u0631 \u0633\u0627\u0639\u062F\u0646\u064A \u0641\u064A \u0627\u0644\u0627\u0645\u062A\u062D\u0627\u0646\u0627\u062A", keywords: ["viele Hausaufgaben", "Wiederholen", "Pr\xFCfungen"], simplified: "\u0627\u0644\u0648\u0627\u062C\u0628\u0627\u062A \u0643\u0627\u0646\u062A \u0645\u0631\u0647\u0642\u0629 \u0644\u0643\u0646\u0647\u0627 \u0633\u0627\u0639\u062F\u062A\u0646\u064A \u0641\u064A \u0627\u0644\u0641\u0647\u0645 \u0648\u0627\u0644\u0646\u062C\u0627\u062D", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0634\u062E\u0635\u064B\u0627 \u064A\u0631\u0643\u0636 \u0641\u064A \u062D\u0644\u0642\u0629 \u0645\u0641\u0631\u063A\u0629 \u{1F3C3}\u060C \u0645\u062A\u0639\u0628\u064B\u0627 \u0644\u0643\u0646\u0647 \u064A\u0635\u0631\u062E: '\u0633\u0623\u0646\u062C\u062D!' \u062A\u0638\u0647\u0631 \u0623\u0645\u0627\u0645\u0647 \u0634\u0647\u0627\u062F\u0629 \u0646\u062C\u0627\u062D \u{1F393}\u060C \u0641\u064A\u0633\u0631\u0639 \u0623\u0643\u062B\u0631. \u064A\u0635\u0644 \u0648\u064A\u0623\u062E\u0630 \u0627\u0644\u0634\u0647\u0627\u062F\u0629 \u0648\u064A\u062C\u0644\u0633 \u0645\u0631\u062A\u0627\u062D\u064B\u0627 \u{1F60C}. \u062B\u0645 \u064A\u0642\u0648\u0644: '\u0627\u0644\u062A\u0639\u0628 \u0643\u0627\u0646 \u064A\u0633\u062A\u062D\u0642 \u0627\u0644\u0639\u0646\u0627\u0621!'" };
      HELP_DATA2["m\xFCndlich_exam18_q1"] = { text: "Jugendliche \u2192 abends ausgehen \u2192 Eltern sch\xFCtzen \u2192 Freiheit \u2192 Vertrauen \u2192 Verantwortung", meaning: "\u062E\u0631\u0648\u062C \u0627\u0644\u0645\u0631\u0627\u0647\u0642\u064A\u0646 \u0644\u064A\u0644\u0627\u064B: \u0627\u0644\u0623\u0647\u0644 \u064A\u0631\u064A\u062F\u0648\u0646 \u0627\u0644\u062D\u0645\u0627\u064A\u0629\u060C \u0648\u0627\u0644\u0645\u0631\u0627\u0647\u0642\u0648\u0646 \u064A\u0631\u064A\u062F\u0648\u0646 \u0627\u0644\u062D\u0631\u064A\u0629", keywords: ["ausgehen", "Eltern sch\xFCtzen", "Freiheit"], simplified: "\u0627\u0644\u062D\u0644 \u0647\u0648 \u0627\u0644\u062B\u0642\u0629 \u0648\u0627\u0644\u0645\u0633\u0624\u0648\u0644\u064A\u0629 \u0627\u0644\u0645\u062A\u0628\u0627\u062F\u0644\u0629 \u0628\u064A\u0646 \u0627\u0644\u0623\u0647\u0644 \u0648\u0627\u0644\u0645\u0631\u0627\u0647\u0642\u064A\u0646", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0645\u0631\u0627\u0647\u0642\u064B\u0627 \u064A\u0631\u064A\u062F \u0627\u0644\u062E\u0631\u0648\u062C \u0644\u064A\u0644\u0627\u064B \u{1F319}\u060C \u0648\u0623\u0645\u0647 \u062A\u0645\u0633\u0643 \u0628\u064A\u062F\u0647 \u0648\u062A\u0642\u0648\u0644 '\u0644\u0627'. \u0641\u062C\u0623\u0629\u060C \u064A\u0638\u0647\u0631 \u0645\u0641\u062A\u0627\u062D \u{1F511} \u0648\u064A\u0641\u062A\u062D \u0628\u0627\u0628\u064B\u0627 \u0639\u0644\u064A\u0647 \u0643\u0644\u0645\u062A\u0627 '\u062B\u0642\u0629' \u0648'\u0645\u0633\u0624\u0648\u0644\u064A\u0629'. \u064A\u062E\u0631\u062C \u0627\u0644\u0645\u0631\u0627\u0647\u0642 \u0648\u064A\u0639\u0648\u062F \u0641\u064A \u0627\u0644\u0648\u0642\u062A \u0627\u0644\u0645\u062D\u062F\u062F \u23F0\u060C \u0648\u062A\u0635\u0641\u0642 \u0644\u0647 \u0627\u0644\u0623\u0645 \u{1F44F}." };
      HELP_DATA2["m\xFCndlich_exam18_q2"] = { text: "Jugendliche Freiheit \u2192 Eltern Regeln \u2192 sch\xFCtzen \u2192 Vertrauen", meaning: "\u0627\u0644\u0645\u0631\u0627\u0647\u0642\u0648\u0646 \u0628\u062D\u0627\u062C\u0629 \u0644\u062D\u0631\u064A\u0629 \u0645\u0639 \u0642\u0648\u0627\u0639\u062F \u0648\u0627\u0636\u062D\u0629 \u0645\u0646 \u0627\u0644\u0623\u0647\u0644 \u0644\u0644\u062D\u0645\u0627\u064A\u0629 \u0648\u0627\u0644\u062B\u0642\u0629", keywords: ["Freiheit", "Regeln", "Vertrauen"], simplified: "\u0627\u0644\u062D\u0631\u064A\u0629 \u0645\u0639 \u0627\u0644\u0642\u0648\u0627\u0639\u062F \u062A\u0628\u0646\u064A \u0627\u0644\u062B\u0642\u0629 \u0648\u062A\u062D\u0642\u0642 \u0627\u0644\u062D\u0645\u0627\u064A\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0637\u0627\u0626\u0631\u064B\u0627 \u{1F54A}\uFE0F \u064A\u0637\u064A\u0631 \u0641\u064A \u0627\u0644\u0633\u0645\u0627\u0621\u060C \u0644\u0643\u0646\u0647 \u0645\u0631\u0628\u0648\u0637 \u0628\u062D\u0628\u0644 \u0637\u0648\u064A\u0644 \u0625\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u{1FAA2}. \u0627\u0644\u062D\u0628\u0644 \u064A\u0633\u0645\u062D \u0644\u0647 \u0628\u0627\u0644\u0637\u064A\u0631\u0627\u0646 \u0644\u0643\u0646 \u0644\u0627 \u064A\u0636\u064A\u0639\u0647. \u0627\u0644\u0623\u0647\u0644 \u064A\u0645\u0633\u0643\u0648\u0646 \u0627\u0644\u062D\u0628\u0644 \u0648\u064A\u0637\u0645\u0626\u0646\u0648\u0646. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u062D\u0631\u064A\u0629 \u0645\u0633\u0624\u0648\u0644\u0629 = \u0623\u0645\u0627\u0646!'" };
      HELP_DATA2["m\xFCndlich_exam18_q3"] = { text: "Ich \u2192 Eltern gefragt \u2192 l\xE4nger drau\xDFen \u2192 vertraut \u2192 p\xFCnktlich zur\xFCck \u2192 sagen wo", meaning: "\u062A\u062C\u0631\u0628\u0629: \u0633\u0623\u0644\u062A \u0648\u0627\u0644\u062F\u064A \u0644\u0644\u0628\u0642\u0627\u0621 \u062E\u0627\u0631\u062C\u064B\u0627 \u0623\u0637\u0648\u0644\u060C \u0648\u062B\u0642\u0648\u0627 \u0628\u064A\u060C \u0648\u0643\u0646\u062A \u0645\u0644\u062A\u0632\u0645\u064B\u0627", keywords: ["l\xE4nger drau\xDFen", "vertraut", "p\xFCnktlich"], simplified: "\u0637\u0644\u0628\u062A \u0645\u0646 \u0648\u0627\u0644\u062F\u064A \u0627\u0644\u0628\u0642\u0627\u0621 \u062E\u0627\u0631\u062C\u064B\u0627 \u0623\u0643\u062B\u0631\u060C \u0648\u062B\u0642\u0648\u0627 \u0628\u064A \u0641\u0644\u0645 \u0623\u062E\u064A\u0628 \u0638\u0646\u0647\u0645", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0645\u0631\u0627\u0647\u0642\u064B\u0627 \u064A\u062A\u0635\u0644 \u0628\u0648\u0627\u0644\u062F\u064A\u0647 \u{1F4F1} \u0648\u064A\u0642\u0648\u0644: '\u0633\u0623\u062A\u0623\u062E\u0631 \u0642\u0644\u064A\u0644\u0627\u064B\u060C \u0623\u0646\u0627 \u0639\u0646\u062F \u0635\u062F\u064A\u0642\u064A'. \u062B\u0645 \u064A\u0639\u0648\u062F \u0641\u064A \u0627\u0644\u0648\u0642\u062A \u0627\u0644\u0645\u062D\u062F\u062F \u23F0 \u0648\u064A\u062C\u062F \u0627\u0628\u062A\u0633\u0627\u0645\u0629 \u062A\u0631\u062D\u064A\u0628 \u{1F60A}. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0634\u0627\u0634\u0629 \u{1F4FA}: '\u0627\u0644\u062B\u0642\u0629 \u062A\u064F\u0628\u0646\u0649 \u0628\u0627\u0644\u0635\u062F\u0642!'" };
      HELP_DATA2["m\xFCndlich_exam19_q1"] = { text: "Rauchen \u2192 Deutschland \u2192 21 Millionen \u2192 Jugendliche \u2192 Werbung \u2192 cool \u2192 gef\xE4hrlich", meaning: "21 \u0645\u0644\u064A\u0648\u0646 \u0645\u062F\u062E\u0646 \u0641\u064A \u0623\u0644\u0645\u0627\u0646\u064A\u0627\u060C \u0627\u0644\u0634\u0628\u0627\u0628 \u064A\u062A\u0623\u062B\u0631\u0648\u0646 \u0628\u0627\u0644\u0625\u0639\u0644\u0627\u0646\u0627\u062A\u060C \u0648\u0627\u0644\u062A\u062F\u062E\u064A\u0646 \u062E\u0637\u0631", keywords: ["Rauchen", "Jugendliche", "gef\xE4hrlich"], simplified: "\u0627\u0644\u0625\u0639\u0644\u0627\u0646\u0627\u062A \u062A\u062C\u0639\u0644 \u0627\u0644\u062A\u062F\u062E\u064A\u0646 \u064A\u0628\u062F\u0648 \u0631\u0627\u0626\u0639\u064B\u0627 \u0644\u0643\u0646\u0647 \u0641\u064A \u0627\u0644\u062D\u0642\u064A\u0642\u0629 \u0642\u0627\u062A\u0644", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0625\u0639\u0644\u0627\u0646\u064B\u0627 \u{1F4FA} \u0639\u0646 \u0633\u064A\u062C\u0627\u0631\u0629 \u062F\u062E\u0627\u0646 \u064A\u062E\u0631\u062C \u0645\u0646\u0647\u0627 \u0634\u0627\u0628 \u0648\u0633\u064A\u0645 \u{1F60E} \u064A\u0636\u062D\u0643. \u0641\u062C\u0623\u0629\u060C \u064A\u062F\u062E\u0646 \u0641\u064A\u062A\u062D\u0648\u0644 \u0625\u0644\u0649 \u0647\u064A\u0643\u0644 \u0639\u0638\u0645\u064A \u{1F480}\u060C \u0648\u062A\u062E\u0631\u062C \u0645\u0646 \u0627\u0644\u0625\u0639\u0644\u0627\u0646 \u0639\u0644\u0627\u0645\u0629 \u062E\u0637\u0631 \u26A0\uFE0F. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0631\u0626\u0629 \u0633\u0648\u062F\u0627\u0621 \u{1FAC1} \u0645\u0631\u064A\u0636\u0629 \u0648\u062A\u0642\u0648\u0644: '\u0644\u0627 \u062A\u0646\u062E\u062F\u0639!'" };
      HELP_DATA2["m\xFCndlich_exam19_q2"] = { text: "Niemand rauchen \u2192 Geld kostet \u2192 Gesundheit schadet \u2192 Verantwortung \u2192 Aufh\xF6ren beste Entscheidung", meaning: "\u0644\u0627 \u062A\u062F\u062E\u0646\u060C \u0641\u0627\u0644\u062A\u062F\u062E\u064A\u0646 \u064A\u0636\u064A\u0639 \u0627\u0644\u0645\u0627\u0644 \u0648\u064A\u0636\u0631 \u0627\u0644\u0635\u062D\u0629\u060C \u0648\u0627\u0644\u0625\u0642\u0644\u0627\u0639 \u0623\u0641\u0636\u0644 \u0642\u0631\u0627\u0631", keywords: ["Geld", "Gesundheit", "Aufh\xF6ren"], simplified: "\u0627\u0644\u0625\u0642\u0644\u0627\u0639 \u0639\u0646 \u0627\u0644\u062A\u062F\u062E\u064A\u0646 \u0647\u0648 \u0623\u0641\u0636\u0644 \u0647\u062F\u064A\u0629 \u062A\u0642\u062F\u0645\u0647\u0627 \u0644\u0646\u0641\u0633\u0643 \u0648\u0644\u0645\u0646 \u062A\u062D\u0628", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0645\u062D\u0641\u0638\u0629 \u0646\u0642\u0648\u062F \u{1F4B0} \u062A\u0634\u062A\u0639\u0644 \u0641\u064A\u0647\u0627 \u0627\u0644\u0646\u0627\u0631 \u{1F525}\u060C \u0648\u0631\u0626\u0629 \u{1FAC1} \u062A\u0633\u0639\u0644 \u062F\u0645\u0627\u064B. \u0641\u062C\u0623\u0629\u060C \u062A\u0637\u0641\u0623 \u0627\u0644\u0646\u0627\u0631 \u0648\u062A\u062A\u062D\u0648\u0644 \u0627\u0644\u0646\u0642\u0648\u062F \u0625\u0644\u0649 \u0648\u0631\u062F\u0629 \u{1F339}\u060C \u0648\u062A\u062A\u062D\u0648\u0644 \u0627\u0644\u0631\u0626\u0629 \u0625\u0644\u0649 \u0642\u0644\u0628 \u064A\u0646\u0628\u0636 \u2764\uFE0F. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u0625\u0642\u0644\u0627\u0639 = \u062D\u064A\u0627\u0629 \u062C\u062F\u064A\u062F\u0629!'" };
      HELP_DATA2["m\xFCndlich_exam19_q3"] = { text: "Onkel \u2192 stark geraucht \u2192 Sohn geboren \u2192 aufgeh\xF6rt \u2192 Vorbild \u2192 ges\xFCnder", meaning: "\u062A\u062C\u0631\u0628\u0629 \u0627\u0644\u0639\u0645: \u0643\u0627\u0646 \u0645\u062F\u062E\u0646\u064B\u0627 \u0634\u0631\u0633\u064B\u0627\u060C \u0641\u0644\u0645\u0627 \u0648\u0644\u062F \u0627\u0628\u0646\u0647 \u0623\u0642\u0644\u0639 \u0648\u0635\u0627\u0631 \u0642\u062F\u0648\u0629", keywords: ["stark geraucht", "aufgeh\xF6rt", "ges\xFCnder"], simplified: "\u0648\u0644\u0627\u062F\u0629 \u0627\u0628\u0646\u0647 \u062C\u0639\u0644\u062A\u0647 \u064A\u0642\u0644\u0639 \u0639\u0646 \u0627\u0644\u062A\u062F\u062E\u064A\u0646\u060C \u0648\u0623\u0635\u0628\u062D \u0623\u0643\u062B\u0631 \u0635\u062D\u0629 \u0648\u0642\u062F\u0648\u0629 \u062D\u0633\u0646\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0631\u062C\u0644\u0627\u064B \u064A\u062F\u062E\u0646 \u0633\u064A\u062C\u0627\u0631\u0629 \u{1F6AC}\u060C \u0648\u0641\u062C\u0623\u0629 \u064A\u0633\u0645\u0639 \u0628\u0643\u0627\u0621 \u0637\u0641\u0644 \u{1F476}. \u062A\u062E\u0631\u062C \u0627\u0644\u0633\u064A\u062C\u0627\u0631\u0629 \u0645\u0646 \u0641\u0645\u0647 \u0648\u062A\u062A\u062D\u0637\u0645 \u{1F4A5}. \u062B\u0645 \u064A\u0631\u0643\u0636 \u0646\u062D\u0648 \u0627\u0644\u0637\u0641\u0644 \u0648\u064A\u062D\u0645\u0644\u0647 \u{1FAC2}\u060C \u0648\u062A\u0638\u0647\u0631 \u062D\u0648\u0644\u0647 \u0647\u0627\u0644\u0629 \u0646\u0648\u0631 \u2728. \u062B\u0645 \u064A\u0642\u0648\u0644: '\u0623\u062C\u0645\u0644 \u0625\u0642\u0644\u0627\u0639 \u0641\u064A \u062D\u064A\u0627\u062A\u064A!'" };
      HELP_DATA2["m\xFCndlich_exam20_q1"] = { text: "Hochbegabte Kinder \u2192 F\xF6rderung \u2192 Spezialschulen \u2192 Integration \u2192 soziale Entwicklung", meaning: "\u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0627\u0644\u0645\u0648\u0647\u0648\u0628\u0648\u0646 \u064A\u062D\u062A\u0627\u062C\u0648\u0646 \u0645\u062F\u0627\u0631\u0633 \u062E\u0627\u0635\u0629 \u0644\u0643\u0646 \u0627\u0644\u062F\u0645\u062C \u0645\u0647\u0645 \u0644\u0644\u0646\u0645\u0648 \u0627\u0644\u0627\u062C\u062A\u0645\u0627\u0639\u064A", keywords: ["Hochbegabte", "Spezialschulen", "Integration"], simplified: "\u0627\u0644\u0645\u0648\u0647\u0648\u0628 \u064A\u062D\u062A\u0627\u062C \u062A\u062D\u0641\u064A\u0632\u064B\u0627 \u0639\u0642\u0644\u064A\u064B\u0627 \u0648\u062A\u0648\u0627\u0635\u0644\u064B\u0627 \u0627\u062C\u062A\u0645\u0627\u0639\u064A\u064B\u0627 \u0645\u0639\u064B\u0627", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0637\u0641\u0644\u064B\u0627 \u0630\u0643\u064A\u064B\u0627 \u{1F9D2} \u064A\u062D\u0645\u0644 \u0635\u0627\u0631\u0648\u062E\u064B\u0627 \u{1F680} \u064A\u0637\u064A\u0631 \u0628\u0647 \u0641\u064A \u0627\u0644\u0641\u0636\u0627\u0621. \u0641\u062C\u0623\u0629\u060C \u064A\u0647\u0628\u0637 \u0641\u064A \u062C\u0632\u064A\u0631\u0629 \u0648\u062D\u064A\u062F\u0629 \u{1F3DD}\uFE0F \u0648\u064A\u0634\u0639\u0631 \u0628\u0627\u0644\u0648\u062D\u062F\u0629. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0623\u064A\u062F\u064A \u{1F91D} \u062A\u0623\u062E\u0630\u0647 \u0625\u0644\u0649 \u0645\u062C\u0645\u0648\u0639\u0629 \u0645\u0646 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u064A\u0644\u0639\u0628\u0648\u0646 \u0645\u0639\u064B\u0627. \u062B\u0645 \u064A\u0642\u0648\u0644: '\u0627\u0644\u0630\u0643\u0627\u0621 \u0645\u0639 \u0627\u0644\u0623\u0635\u062F\u0642\u0627\u0621 \u0623\u0641\u0636\u0644!'" };
      HELP_DATA2["m\xFCndlich_exam20_q2"] = { text: "Mischung am besten \u2192 F\xF6rderung \u2192 Kontakt mit anderen \u2192 soziale F\xE4higkeiten entwickeln", meaning: "\u0627\u0644\u0645\u0632\u062C \u0628\u064A\u0646 \u0627\u0644\u062A\u0639\u0644\u064A\u0645 \u0627\u0644\u062E\u0627\u0635 \u0648\u0627\u0644\u062F\u0645\u062C \u0647\u0648 \u0627\u0644\u0623\u0641\u0636\u0644 \u0644\u062A\u0637\u0648\u064A\u0631 \u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062A \u0627\u0644\u0627\u062C\u062A\u0645\u0627\u0639\u064A\u0629", keywords: ["Mischung", "F\xF6rderung", "soziale F\xE4higkeiten"], simplified: "\u0627\u062C\u0645\u0639 \u0628\u064A\u0646 \u0627\u0644\u062A\u062D\u0641\u064A\u0632 \u0627\u0644\u0630\u0647\u0646\u064A \u0648\u0627\u0644\u062A\u0648\u0627\u0635\u0644 \u0627\u0644\u0627\u062C\u062A\u0645\u0627\u0639\u064A \u0644\u062A\u0646\u0645\u064A\u0629 \u0645\u062A\u0643\u0627\u0645\u0644\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0643\u0639\u0643\u0629 \u{1F382} \u0646\u0635\u0641\u0647\u0627 \u0643\u062A\u0627\u0628 \u{1F4DA} \u0648\u0646\u0635\u0641\u0647\u0627 \u0623\u0637\u0641\u0627\u0644 \u064A\u0644\u0639\u0628\u0648\u0646 \u{1F467}\u{1F9D2}. \u0639\u0646\u062F\u0645\u0627 \u062A\u0623\u0643\u0644\u0647\u0627\u060C \u062A\u0634\u0639\u0631 \u0623\u0646 \u0639\u0642\u0644\u0643 \u064A\u0646\u0645\u0648 \u{1F9E0} \u0648\u062A\u0636\u062D\u0643 \u{1F60A}. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u062A\u0648\u0627\u0632\u0646 = \u0646\u062C\u0627\u062D \u0634\u0627\u0645\u0644!'" };
      HELP_DATA2["m\xFCndlich_exam20_q3"] = { text: "Mitsch\xFCler \u2192 sehr intelligent \u2192 zus\xE4tzliche Aufgaben \u2192 gleiche Klasse \u2192 gut entwickelt", meaning: "\u062A\u062C\u0631\u0628\u0629 \u0632\u0645\u064A\u0644 \u0645\u0648\u0647\u0648\u0628: \u0645\u0647\u0627\u0645 \u0625\u0636\u0627\u0641\u064A\u0629 \u0641\u064A \u0646\u0641\u0633 \u0627\u0644\u0635\u0641\u060C \u062A\u0637\u0648\u0631 \u062C\u064A\u062F", keywords: ["intelligent", "zus\xE4tzliche Aufgaben", "gut entwickelt"], simplified: "\u0632\u0645\u064A\u0644\u064A \u0627\u0644\u0630\u0643\u064A \u0628\u0642\u064A \u0641\u064A \u0646\u0641\u0633 \u0627\u0644\u0635\u0641 \u0645\u0639 \u0645\u0647\u0627\u0645 \u0625\u0636\u0627\u0641\u064A\u0629 \u0648\u062A\u0637\u0648\u0631 \u0628\u0634\u0643\u0644 \u0631\u0627\u0626\u0639", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0637\u0627\u0644\u0628\u064B\u0627 \u0630\u0643\u064A\u064B\u0627 \u{1F9D1}\u200D\u{1F393} \u064A\u062C\u0644\u0633 \u0641\u064A \u0627\u0644\u0635\u0641 \u{1F3EB}\u060C \u0648\u0623\u0633\u062A\u0627\u0630 \u064A\u0636\u0639 \u0628\u062C\u0627\u0646\u0628\u0647 \u0643\u062A\u0627\u0628\u064B\u0627 \u0625\u0636\u0627\u0641\u064A\u064B\u0627 \u{1F4D6} \u0648\u064A\u0633\u0623\u0644\u0647: '\u0647\u0644 \u062A\u0633\u062A\u0637\u064A\u0639\u061F' \u0641\u064A\u062C\u064A\u0628 \u0628\u0646\u0639\u0645 \u0648\u064A\u0641\u062A\u062D\u0647. \u0628\u0639\u062F \u0641\u062A\u0631\u0629\u060C \u064A\u062E\u0631\u062C \u0645\u0646\u0647 \u0636\u0648\u0621 \u{1F4A1} \u0648\u064A\u0636\u064A\u0621 \u0627\u0644\u0635\u0641 \u0628\u0623\u0643\u0645\u0644\u0647. \u062B\u0645 \u064A\u0642\u0648\u0644: '\u0627\u0644\u0634\u062F\u0629 \u062A\u0648\u0644\u062F \u0627\u0644\u0642\u0648\u0629!'" };
      HELP_DATA2["m\xFCndlich_exam21_q1"] = { text: "Hochzeit \u2192 ohne G\xE4ste \u2192 einfach \u2192 Geld sparen \u2192 ruhig genie\xDFen", meaning: "\u0632\u0648\u0627\u062C \u0628\u062F\u0648\u0646 \u0636\u064A\u0648\u0641 \u0628\u0633\u064A\u0637 \u064A\u0648\u0641\u0631 \u0627\u0644\u0645\u0627\u0644 \u0648\u064A\u0633\u0645\u062D \u0628\u0627\u0644\u0627\u0633\u062A\u0645\u062A\u0627\u0639 \u0628\u0647\u062F\u0648\u0621", keywords: ["ohne G\xE4ste", "einfach", "Geld sparen"], simplified: "\u0627\u062D\u062A\u0641\u0627\u0644 \u0628\u0633\u064A\u0637 \u0628\u062F\u0648\u0646 \u0636\u064A\u0648\u0641 \u064A\u0648\u0641\u0631 \u0627\u0644\u0645\u0627\u0644 \u0648\u064A\u0643\u0648\u0646 \u0647\u0627\u062F\u0626\u064B\u0627 \u0648\u0645\u0645\u062A\u0639\u064B\u0627", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0639\u0631\u0648\u0633\u064A\u0646 \u{1F470}\u{1F935} \u0639\u0644\u0649 \u0634\u0627\u0637\u0626 \u0627\u0644\u0628\u062D\u0631 \u{1F3D6}\uFE0F\u060C \u0644\u0627 \u0623\u062D\u062F \u0645\u0639\u0647\u0645\u0627 \u0633\u0648\u0649 \u0637\u064A\u0648\u0631 \u0627\u0644\u0646\u0648\u0631\u0633 \u{1F54A}\uFE0F. \u064A\u062A\u0628\u0627\u062F\u0644\u0627\u0646 \u0627\u0644\u062E\u0648\u0627\u062A\u0645 \u{1F48D} \u0641\u064A \u0647\u062F\u0648\u0621\u060C \u0648\u062A\u0638\u0647\u0631 \u0646\u0642\u0648\u062F \u{1F4B0} \u062A\u062A\u0631\u0627\u0642\u0635 \u0641\u0631\u062D\u064B\u0627 \u0644\u062A\u0648\u0641\u064A\u0631\u0647\u0627. \u062B\u0645 \u064A\u0642\u0648\u0644\u0627\u0646: '\u0627\u0644\u0633\u0639\u0627\u062F\u0629 \u0644\u064A\u0633\u062A \u0641\u064A \u0627\u0644\u0639\u062F\u062F!'" };
      HELP_DATA2["m\xFCndlich_exam21_q2"] = { text: "Kleine Hochzeit \u2192 gute Idee \u2192 Familie & Freunde wichtig", meaning: "\u0627\u0644\u0632\u0641\u0627\u0641 \u0627\u0644\u0635\u063A\u064A\u0631 \u0641\u0643\u0631\u0629 \u062C\u064A\u062F\u0629 \u0644\u0643\u0646 \u0648\u062C\u0648\u062F \u0627\u0644\u0623\u0647\u0644 \u0648\u0627\u0644\u0623\u0635\u062F\u0642\u0627\u0621 \u0645\u0647\u0645", keywords: ["kleine Hochzeit", "gute Idee", "Familie wichtig"], simplified: "\u0627\u0644\u0641\u0631\u062D \u0627\u0644\u0635\u063A\u064A\u0631 \u062C\u0645\u064A\u0644\u060C \u0644\u0643\u0646 \u0648\u062C\u0648\u062F \u0627\u0644\u0623\u062D\u0628\u0629 \u064A\u0636\u0641\u064A \u0644\u0645\u0633\u0629 \u062E\u0627\u0635\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0639\u0631\u0648\u0633\u064A\u0646 \u064A\u0631\u0642\u0635\u0627\u0646 \u0641\u064A \u0642\u0627\u0639\u0629 \u0635\u063A\u064A\u0631\u0629 \u{1F492}\u060C \u0648\u0628\u062C\u0627\u0646\u0628\u0647\u0645\u0627 \u0623\u0645\u0647\u0645\u0627 \u{1F469}\u200D\u{1F467} \u0648\u0623\u0628\u0648\u0647\u0645\u0627 \u{1F468}\u200D\u{1F466} \u064A\u0635\u0641\u0642\u0627\u0646. \u0641\u062C\u0623\u0629\u060C \u064A\u0646\u0641\u062A\u062D \u0627\u0644\u0642\u0644\u0628 \u2764\uFE0F \u0648\u062A\u062E\u0631\u062C \u0645\u0646\u0647 \u0642\u0644\u0648\u0628 \u0635\u063A\u064A\u0631\u0629 \u{1FAC0} \u062A\u062D\u064A\u0637 \u0628\u0647\u0645\u0627. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u0639\u0627\u0626\u0644\u0629 \u0646\u0639\u0645\u0629!'" };
      HELP_DATA2["m\xFCndlich_exam21_q3"] = { text: "Freund \u2192 kleine Hochzeit \u2192 Geld sparen \u2192 ruhig genie\xDFen", meaning: "\u0635\u062F\u064A\u0642 \u064A\u0641\u0636\u0644 \u0627\u0644\u0632\u0641\u0627\u0641 \u0627\u0644\u0635\u063A\u064A\u0631 \u0644\u062A\u0648\u0641\u064A\u0631 \u0627\u0644\u0645\u0627\u0644 \u0648\u0627\u0644\u0647\u062F\u0648\u0621", keywords: ["Freund", "kleine Hochzeit", "ruhig genie\xDFen"], simplified: "\u0635\u062F\u064A\u0642\u064A \u064A\u0631\u064A\u062F \u062D\u0641\u0644 \u0632\u0641\u0627\u0641 \u0635\u063A\u064A\u0631\u064B\u0627 \u0644\u062A\u0648\u0641\u064A\u0631 \u0627\u0644\u0645\u0627\u0644 \u0648\u0642\u0636\u0627\u0621 \u064A\u0648\u0645 \u0647\u0627\u062F\u0626", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0635\u062F\u064A\u0642\u0643 \u{1F9D1} \u064A\u062C\u0644\u0633 \u0645\u0639 \u062E\u0637\u064A\u0628\u062A\u0647 \u0648\u064A\u0646\u0638\u0631\u0627\u0646 \u0625\u0644\u0649 \u062D\u0635\u0627\u0644\u0629 \u0646\u0642\u0648\u062F \u{1F416} \u062A\u0646\u0645\u0648. \u062B\u0645 \u064A\u062A\u062C\u0647\u0627\u0646 \u0625\u0644\u0649 \u0645\u0643\u0627\u0646 \u0647\u0627\u062F\u0626 \u{1F332} \u0648\u064A\u062C\u0644\u0633\u0627\u0646 \u062A\u062D\u062A \u0634\u062C\u0631\u0629 \u{1F333}. \u062B\u0645 \u064A\u0631\u0641\u0639\u0627\u0646 \u0643\u0623\u0633\u064A\u0646 \u{1F942} \u0648\u064A\u0642\u0648\u0644\u0627\u0646: '\u0644\u062D\u064A\u0627\u0629 \u0628\u0633\u064A\u0637\u0629 \u0648\u0633\u0639\u064A\u062F\u0629!'" };
      HELP_DATA2["m\xFCndlich_exam23_q1"] = { text: "Stadtwohnung \u2192 Arbeit \u2192 Kultur \u2192 kurze Wege \u2192 Haus im Gr\xFCnen \u2192 Ruhe \u2192 Natur \u2192 Umweltprobleme", meaning: "\u0634\u0642\u0629 \u0627\u0644\u0645\u062F\u064A\u0646\u0629 \u062A\u0648\u0641\u0631 \u0627\u0644\u0639\u0645\u0644 \u0648\u0627\u0644\u062B\u0642\u0627\u0641\u0629\u060C \u0648\u0627\u0644\u0628\u064A\u062A \u0641\u064A \u0627\u0644\u0631\u064A\u0641 \u064A\u0648\u0641\u0631 \u0627\u0644\u0647\u062F\u0648\u0621 \u0648\u0627\u0644\u0637\u0628\u064A\u0639\u0629", keywords: ["Stadtwohnung", "Haus im Gr\xFCnen", "Umweltprobleme"], simplified: "\u0644\u0643\u0644 \u0646\u0645\u0637 \u0633\u0643\u0646 \u0645\u0645\u064A\u0632\u0627\u062A\u0647\u060C \u0627\u0644\u0631\u064A\u0641 \u0623\u0641\u0636\u0644 \u0644\u0644\u0635\u062D\u0629 \u0648\u0627\u0644\u0623\u0633\u0631\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0634\u0642\u0629 \u0641\u064A \u0627\u0644\u0645\u062F\u064A\u0646\u0629 \u{1F3E2} \u0628\u0647\u0627 \u0645\u0635\u0627\u0639\u062F \u0648\u0633\u064A\u0627\u0631\u0627\u062A \u{1F697}\u060C \u0648\u0628\u064A\u062A\u064B\u0627 \u0641\u064A \u0627\u0644\u0631\u064A\u0641 \u{1F3E1} \u0628\u0647 \u0623\u0634\u062C\u0627\u0631 \u0648\u0637\u064A\u0648\u0631 \u{1F54A}\uFE0F. \u0641\u062C\u0623\u0629\u060C \u062A\u062A\u0646\u0627\u0641\u0633 \u0627\u0644\u0635\u0648\u0631\u062A\u0627\u0646: \u0635\u062E\u0628 \u0627\u0644\u0645\u0637\u0627\u0631 \u{1F6EB} \u0645\u0642\u0627\u0628\u0644 \u0647\u062F\u0648\u0621 \u0627\u0644\u063A\u0627\u0628\u0629 \u{1F332}. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u062E\u062A\u0631 \u062A\u0648\u0627\u0632\u0646\u0643!'" };
      HELP_DATA2["m\xFCndlich_exam23_q2"] = { text: "Wohnformen Vorteile \u2192 Ruhe \u2192 Natur \u2192 Gesundheit \u2192 Familie", meaning: "\u0627\u0644\u0647\u062F\u0648\u0621 \u0648\u0627\u0644\u0637\u0628\u064A\u0639\u0629 \u0623\u0641\u0636\u0644 \u0644\u0644\u0635\u062D\u0629 \u0648\u0627\u0644\u0623\u0633\u0631\u0629", keywords: ["Ruhe", "Natur", "Gesundheit"], simplified: "\u0627\u0644\u0639\u064A\u0634 \u0641\u064A \u0627\u0644\u0637\u0628\u064A\u0639\u0629 \u064A\u0645\u0646\u062D\u0643 \u0635\u062D\u0629 \u0623\u0641\u0636\u0644 \u0648\u0648\u0642\u062A\u064B\u0627 \u0623\u0643\u0628\u0631 \u0644\u0644\u0639\u0627\u0626\u0644\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0639\u0627\u0626\u0644\u0629 \u{1F468}\u200D\u{1F469}\u200D\u{1F467}\u200D\u{1F466} \u062A\u062C\u0644\u0633 \u0641\u064A \u062D\u062F\u064A\u0642\u0629 \u{1F333}\u060C \u0648\u0623\u0634\u0639\u0629 \u0627\u0644\u0634\u0645\u0633 \u2600\uFE0F \u062A\u0636\u0631\u0628\u0647\u0645. \u0641\u062C\u0623\u0629\u060C \u062A\u0638\u0647\u0631 \u0642\u0644\u0648\u0628 \u2764\uFE0F \u062D\u0648\u0644\u0647\u0645 \u0648\u064A\u062E\u062A\u0641\u064A \u0627\u0644\u062A\u0648\u062A\u0631. \u062B\u0645 \u064A\u0635\u0639\u062F\u0648\u0646 \u062C\u0628\u0644\u064B\u0627 \u26F0\uFE0F \u0648\u064A\u0646\u0638\u0631\u0648\u0646 \u0625\u0644\u0649 \u0627\u0644\u0623\u0641\u0642. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u0637\u0628\u064A\u0639\u0629 \u0647\u064A \u0627\u0644\u0635\u062D\u0629!'" };
      HELP_DATA2["m\xFCndlich_exam23_q3"] = { text: "Familie \u2192 Wochenende Land \u2192 ruhig \u2192 spazieren \u2192 frische Luft \u2192 Landleben m\xF6gen", meaning: "\u062A\u062C\u0631\u0628\u0629 \u0639\u0637\u0644\u0629 \u0646\u0647\u0627\u064A\u0629 \u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u0641\u064A \u0627\u0644\u0631\u064A\u0641: \u0647\u062F\u0648\u0621\u060C \u0645\u0634\u064A\u060C \u0647\u0648\u0627\u0621 \u0646\u0642\u064A\u060C \u0648\u062D\u0628 \u0644\u0644\u062D\u064A\u0627\u0629 \u0627\u0644\u0631\u064A\u0641\u064A\u0629", keywords: ["Wochenende Land", "frische Luft", "Landleben"], simplified: "\u0642\u0636\u064A\u0646\u0627 \u0639\u0637\u0644\u0629 \u0646\u0647\u0627\u064A\u0629 \u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u0641\u064A \u0627\u0644\u0631\u064A\u0641\u060C \u0643\u0627\u0646 \u0647\u0627\u062F\u0626\u064B\u0627 \u0648\u062C\u0645\u064A\u0644\u0627\u064B\u060C \u0648\u0641\u0647\u0645\u062A \u0633\u062D\u0631 \u0627\u0644\u062D\u064A\u0627\u0629 \u0627\u0644\u0631\u064A\u0641\u064A\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0639\u0627\u0626\u0644\u0629 \u062A\u0645\u0634\u064A \u0639\u0644\u0649 \u0637\u0631\u064A\u0642 \u062A\u0631\u0627\u0628\u064A \u{1F97E}\u060C \u0648\u0627\u0644\u0647\u0648\u0627\u0621 \u0627\u0644\u0646\u0642\u064A \u064A\u062F\u0627\u0639\u0628 \u0648\u062C\u0648\u0647\u0647\u0645 \u{1F4A8}. \u0641\u062C\u0623\u0629\u060C \u062A\u062A\u0648\u0642\u0641 \u0642\u0637\u0629 \u0635\u063A\u064A\u0631\u0629 \u{1F431} \u0648\u062A\u0631\u0628\u062A \u0639\u0644\u064A\u0647\u0627 \u0627\u0644\u0637\u0641\u0644\u0629. \u062B\u0645 \u064A\u062C\u0644\u0633\u0648\u0646 \u062A\u062D\u062A \u0634\u062C\u0631\u0629 \u{1F333} \u0648\u064A\u0623\u0643\u0644\u0648\u0646 \u0633\u0646\u062F\u0648\u064A\u0634\u0627\u062A \u{1F96A}. \u062B\u0645 \u064A\u0642\u0648\u0644\u0648\u0646: '\u0647\u0630\u0647 \u0647\u064A \u0627\u0644\u062D\u064A\u0627\u0629!'" };
      HELP_DATA2["m\xFCndlich_exam24_q1"] = { text: "Doping \u2192 Leistungssport \u2192 erlauben oder verbieten \u2192 Fairness \u2192 Gesundheit \u2192 Kontrollen", meaning: "\u062C\u062F\u0644 \u062D\u0648\u0644 \u0627\u0644\u0645\u0646\u0634\u0637\u0627\u062A \u0641\u064A \u0627\u0644\u0631\u064A\u0627\u0636\u0629 \u0628\u064A\u0646 \u0627\u0644\u0633\u0645\u0627\u062D \u0648\u0627\u0644\u0645\u0646\u0639\u060C \u0627\u0644\u0639\u062F\u0627\u0644\u0629 \u0648\u0627\u0644\u0635\u062D\u0629 \u0623\u0647\u0645", keywords: ["Doping", "Fairness", "Gesundheit"], simplified: "\u0627\u0644\u0645\u0646\u0634\u0637\u0627\u062A \u062A\u062B\u064A\u0631 \u062C\u062F\u0644\u0627\u064B: \u0627\u0644\u0628\u0639\u0636 \u064A\u0631\u064A\u062F \u0627\u0644\u0633\u0645\u0627\u062D \u0628\u0647\u0627\u060C \u0648\u0627\u0644\u0628\u0639\u0636 \u064A\u0631\u0641\u0636\u0647\u0627 \u0644\u0623\u0633\u0628\u0627\u0628 \u0623\u062E\u0644\u0627\u0642\u064A\u0629 \u0648\u0635\u062D\u064A\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0645\u064A\u062F\u0627\u0646\u064B\u0627 \u0631\u064A\u0627\u0636\u064A\u064B\u0627 \u{1F3DF}\uFE0F\u060C \u0631\u064A\u0627\u0636\u064A\u0627\u0646 \u{1F3C3}\u200D\u2642\uFE0F\u{1F3C3}\u200D\u2642\uFE0F \u064A\u062A\u0633\u0627\u0628\u0642\u0627\u0646. \u0623\u062D\u062F\u0647\u0645\u0627 \u064A\u0623\u062E\u0630 \u062D\u0642\u0646\u0629 \u{1F489} \u0641\u064A\u0637\u064A\u0631 \u{1F54A}\uFE0F \u0648\u0627\u0644\u0622\u062E\u0631 \u064A\u0631\u0643\u0636 \u0637\u0628\u064A\u0639\u064A\u064B\u0627. \u0641\u062C\u0623\u0629\u060C \u064A\u0638\u0647\u0631 \u062D\u0643\u0645 \u{1F468}\u200D\u2696\uFE0F \u0648\u064A\u0634\u0637\u0628 \u0627\u0644\u0623\u0648\u0644. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u0639\u062F\u0627\u0644\u0629 \u0623\u0647\u0645 \u0645\u0646 \u0627\u0644\u0641\u0648\u0632!'" };
      HELP_DATA2["m\xFCndlich_exam24_q2"] = { text: "Doping verboten \u2192 unfair \u2192 ungesund \u2192 Sport Vorbild", meaning: "\u0627\u0644\u0645\u0646\u0634\u0637\u0627\u062A \u0645\u062D\u0638\u0648\u0631\u0629 \u0644\u0623\u0646\u0647\u0627 \u063A\u064A\u0631 \u0639\u0627\u062F\u0644\u0629 \u0648\u063A\u064A\u0631 \u0635\u062D\u064A\u0629\u060C \u0648\u0627\u0644\u0631\u064A\u0627\u0636\u0629 \u0642\u062F\u0648\u0629", keywords: ["verboten", "unfair", "Vorbild"], simplified: "\u0627\u0644\u0645\u0646\u0634\u0637\u0627\u062A \u0636\u0627\u0631\u0629 \u0648\u063A\u064A\u0631 \u0639\u0627\u062F\u0644\u0629\u060C \u0648\u0627\u0644\u0631\u064A\u0627\u0636\u064A \u0627\u0644\u0646\u0638\u064A\u0641 \u0642\u062F\u0648\u0629 \u062D\u0633\u0646\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0631\u064A\u0627\u0636\u064A\u064B\u0627 \u064A\u062D\u0645\u0644 \u0643\u0623\u0633\u064B\u0627 \u{1F3C6} \u0646\u0638\u064A\u0641\u064B\u0627\u060C \u0648\u0622\u062E\u0631 \u064A\u062D\u0645\u0644 \u0643\u0623\u0633\u064B\u0627 \u0628\u0647 \u0628\u0642\u0639\u0629 \u0633\u0648\u062F\u0627\u0621 \u26AB. \u0641\u062C\u0623\u0629\u060C \u064A\u062A\u062D\u0648\u0644 \u0627\u0644\u0643\u0623\u0633 \u0627\u0644\u0646\u0638\u064A\u0641 \u0625\u0644\u0649 \u062A\u0627\u062C \u{1F451}\u060C \u0648\u062A\u062A\u0634\u0642\u0642 \u0627\u0644\u0628\u0642\u0639\u0629 \u0627\u0644\u0633\u0648\u062F\u0627\u0621. \u062B\u0645 \u064A\u0635\u0637\u0641 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u{1F467}\u{1F9D2} \u062E\u0644\u0641 \u0627\u0644\u0631\u064A\u0627\u0636\u064A \u0627\u0644\u0646\u0638\u064A\u0641 \u0648\u064A\u0642\u0644\u062F\u0648\u0646\u0647. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0643\u0646 \u0642\u062F\u0648\u0629!'" };
