      HELP_DATA2["m\xFCndlich_exam25_q3"] = { text: "Ich \u2192 Fernsehen \u2192 Dokumentationen \u2192 gelernt \u2192 Filme \u2192 keine Infos", meaning: "\u062A\u062C\u0631\u0628\u0629: \u062A\u0627\u0628\u0639\u062A \u0648\u062B\u0627\u0626\u0642\u064A\u0627\u062A \u0645\u0641\u064A\u062F\u0629\u060C \u0648\u0623\u0641\u0644\u0627\u0645\u064B\u0627 \u0628\u062F\u0648\u0646 \u0641\u0627\u0626\u062F\u0629", keywords: ["Dokumentationen", "gelernt", "keine Infos"], simplified: "\u0634\u0627\u0647\u062F\u062A \u0648\u062B\u0627\u0626\u0642\u064A\u0627\u062A \u0648\u062A\u0639\u0644\u0645\u062A \u0645\u0646\u0647\u0627\u060C \u0648\u0623\u0641\u0644\u0627\u0645\u064B\u0627 \u0639\u0627\u062F\u064A\u0629 \u0628\u062F\u0648\u0646 \u0645\u0639\u0644\u0648\u0645\u0627\u062A \u062C\u062F\u064A\u062F\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0634\u062E\u0635\u064B\u0627 \u0623\u0645\u0627\u0645 \u062A\u0644\u0641\u0627\u0632 \u{1F4FA}\u060C \u062A\u062E\u0631\u062C \u0645\u0646 \u0627\u0644\u0634\u0627\u0634\u0629 \u0643\u062A\u0628 \u{1F4DA} \u062A\u0637\u064A\u0631 \u0625\u0644\u0649 \u0631\u0623\u0633\u0647 \u0639\u0646\u062F\u0645\u0627 \u064A\u0634\u0627\u0647\u062F \u0648\u062B\u0627\u0626\u0642\u064A\u064B\u0627. \u0648\u0639\u0646\u062F\u0645\u0627 \u064A\u0634\u0627\u0647\u062F \u0641\u064A\u0644\u0645\u064B\u0627\u060C \u0644\u0627 \u064A\u062E\u0631\u062C \u0634\u064A\u0621. \u062B\u0645 \u062A\u0646\u0645\u0648 \u0639\u0636\u0644\u0627\u062A \u{1F9E0} \u0641\u064A \u0627\u0644\u0631\u0623\u0633 \u0648\u062A\u0642\u0648\u0649. \u062B\u0645 \u064A\u0642\u0648\u0644: '\u0627\u0644\u0645\u0641\u064A\u062F \u064A\u0628\u0646\u064A\u0643\u060C \u0627\u0644\u0641\u0627\u0631\u063A \u064A\u0636\u064A\u0639 \u0648\u0642\u062A\u0643!'" };
      HELP_DATA2["m\xFCndlich_exam26_q1"] = { text: "Kinderkonten \u2192 fr\xFCh Geld lernen \u2192 sparen \u2192 Bank \u2192 Vorteile \u2192 Kritik Banken \u2192 Verschuldung", meaning: "\u062D\u0633\u0627\u0628\u0627\u062A \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u062A\u0639\u0644\u0645\u0647\u0645 \u0627\u0644\u062A\u0639\u0627\u0645\u0644 \u0645\u0639 \u0627\u0644\u0645\u0627\u0644 \u0645\u0628\u0643\u0631\u0627\u064B\u060C \u0644\u0643\u0646 \u0627\u0644\u0628\u0646\u0648\u0643 \u062A\u0646\u062A\u0642\u062F \u0627\u0644\u062F\u064A\u0648\u0646", keywords: ["Kinderkonten", "Geld lernen", "Verschuldung"], simplified: "\u062A\u0639\u0644\u064A\u0645 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0627\u0644\u0627\u062F\u062E\u0627\u0631 \u0645\u0641\u064A\u062F\u060C \u0644\u0643\u0646 \u0627\u062D\u0630\u0631 \u0645\u0646 \u0627\u0633\u062A\u063A\u0644\u0627\u0644 \u0627\u0644\u0628\u0646\u0648\u0643", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0637\u0641\u0644\u0627\u064B \u{1F467} \u064A\u0636\u0639 \u0646\u0642\u0648\u062F\u064B\u0627 \u0641\u064A \u062D\u0635\u0627\u0644\u0629 \u{1F416}\u060C \u0648\u062A\u0643\u0628\u0631 \u0627\u0644\u062D\u0635\u0627\u0644\u0629 \u0648\u062A\u062A\u062D\u0648\u0644 \u0625\u0644\u0649 \u0628\u0646\u0643 \u{1F3E6}. \u0641\u062C\u0623\u0629\u060C \u062A\u062E\u0631\u062C \u0645\u0646 \u0627\u0644\u0628\u0646\u0643 \u064A\u062F \u{1F932} \u062A\u062D\u0627\u0648\u0644 \u0623\u062E\u0630 \u0627\u0644\u0646\u0642\u0648\u062F \u0623\u0643\u062B\u0631 \u0645\u0645\u0627 \u0648\u0636\u0639. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u062F\u062E\u0631 \u0628\u062D\u0643\u0645\u0629!'" };
      HELP_DATA2["m\xFCndlich_exam26_q2"] = { text: "Kinderkonten sinnvoll \u2192 fr\xFCh lernen \u2192 Eltern begleiten \u2192 kontrollieren", meaning: "\u062D\u0633\u0627\u0628\u0627\u062A \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0645\u0641\u064A\u062F\u0629 \u0645\u0639 \u0645\u0631\u0627\u0642\u0628\u0629 \u0627\u0644\u0648\u0627\u0644\u062F\u064A\u0646", keywords: ["sinnvoll", "Eltern begleiten", "kontrollieren"], simplified: "\u0627\u0641\u062A\u062D \u062D\u0633\u0627\u0628\u064B\u0627 \u0644\u0637\u0641\u0644\u0643 \u0645\u0639 \u0627\u0644\u0625\u0634\u0631\u0627\u0641\u060C \u0641\u0647\u0630\u0627 \u064A\u0639\u0644\u0645\u0647 \u0627\u0644\u0645\u0633\u0624\u0648\u0644\u064A\u0629 \u0627\u0644\u0645\u0627\u0644\u064A\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0623\u0628\u064B\u0627 \u{1F468} \u0648\u0627\u0628\u0646\u0647 \u{1F9D1} \u062C\u0627\u0644\u0633\u064A\u0646 \u0623\u0645\u0627\u0645 \u0643\u0645\u0628\u064A\u0648\u062A\u0631 \u{1F4BB}\u060C \u064A\u0641\u062A\u062A\u062D\u0627\u0646 \u062D\u0633\u0627\u0628\u064B\u0627 \u0628\u0646\u0643\u064A\u064B\u0627. \u0641\u062C\u0623\u0629\u060C \u062A\u0638\u0647\u0631 \u0623\u064A\u0627\u062F\u064A \u062A\u0631\u0627\u0642\u0628 \u{1F440} \u0643\u0644 \u062D\u0631\u0643\u0629. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0643\u0644\u0645\u0629 '\u0645\u0633\u0624\u0648\u0644\u064A\u0629' \u0648\u062A\u0643\u0628\u0631. \u062B\u0645 \u064A\u0642\u0648\u0644 \u0627\u0644\u0623\u0628: '\u0645\u0639\u064B\u0627 \u0646\u062A\u0639\u0644\u0645!'" };
      HELP_DATA2["m\xFCndlich_exam26_q3"] = { text: "Freund \u2192 Sparkonto \u2192 Taschengeld sparen \u2192 Besonderes gekauft \u2192 verantwortungsvoll Geld", meaning: "\u062A\u062C\u0631\u0628\u0629 \u0635\u062F\u064A\u0642: \u0627\u062F\u062E\u0631 \u0645\u0635\u0631\u0648\u0641\u0647 \u0641\u064A \u062D\u0633\u0627\u0628 \u062A\u0648\u0641\u064A\u0631\u060C \u0627\u0634\u062A\u0631\u0649 \u0634\u064A\u0626\u064B\u0627 \u0645\u0645\u064A\u0632\u064B\u0627 \u0648\u062A\u0639\u0644\u0645 \u0627\u0644\u0645\u0633\u0624\u0648\u0644\u064A\u0629", keywords: ["Sparkonto", "Taschengeld sparen", "verantwortungsvoll"], simplified: "\u0635\u062F\u064A\u0642\u064A \u0627\u062F\u062E\u0631 \u0645\u0635\u0631\u0648\u0641 \u062C\u064A\u0628\u0647 \u0648\u0627\u0634\u062A\u0631\u0649 \u0634\u064A\u0626\u064B\u0627 \u062B\u0645\u064A\u0646\u064B\u0627\u060C \u0648\u062A\u0639\u0644\u0645 \u0627\u0644\u062A\u0639\u0627\u0645\u0644 \u0627\u0644\u0645\u0633\u0624\u0648\u0644 \u0645\u0639 \u0627\u0644\u0645\u0627\u0644", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0635\u062F\u064A\u0642\u0643 \u{1F9D1} \u064A\u0636\u0639 \u0639\u0645\u0644\u0627\u062A \u0645\u0639\u062F\u0646\u064A\u0629 \u{1FA99} \u0648\u0627\u062D\u062F\u0629 \u062A\u0644\u0648 \u0627\u0644\u0623\u062E\u0631\u0649 \u0641\u064A \u0628\u0646\u0643 \u0623\u0635\u0628\u0639 \u{1F437}. \u062A\u0643\u0628\u0631 \u0627\u0644\u0639\u0645\u0644\u0627\u062A \u0648\u062A\u062A\u062D\u0648\u0644 \u0625\u0644\u0649 \u062F\u0631\u0627\u062C\u0629 \u0647\u0648\u0627\u0626\u064A\u0629 \u{1F6B2}. \u064A\u0631\u0643\u0628\u0647\u0627 \u0648\u064A\u0636\u062D\u0643 \u{1F60A}. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u0635\u0628\u0631 \u064A\u0648\u0635\u0644\u0643!'" };
      HELP_DATA2["m\xFCndlich_exam27_q1"] = { text: "Haustausch \u2192 g\xFCnstig \u2192 spannend \u2192 Kulturen \u2192 Nachteile \u2192 Sicherheit \u2192 Risiken", meaning: "\u062A\u0628\u0627\u062F\u0644 \u0627\u0644\u0645\u0646\u0627\u0632\u0644 \u0641\u064A \u0627\u0644\u0625\u062C\u0627\u0632\u0629: \u0631\u062E\u064A\u0635 \u0648\u0645\u062B\u064A\u0631 \u0644\u0643\u0646\u0647 \u064A\u0646\u0637\u0648\u064A \u0639\u0644\u0649 \u0645\u062E\u0627\u0637\u0631 \u0623\u0645\u0646\u064A\u0629", keywords: ["Haustausch", "g\xFCnstig", "Sicherheit"], simplified: "\u062A\u0628\u0627\u062F\u0644 \u0627\u0644\u0645\u0646\u0627\u0632\u0644 \u0641\u0643\u0631\u0629 \u0631\u0627\u0626\u0639\u0629 \u0644\u0643\u0646 \u0627\u062D\u0630\u0631 \u0645\u0646 \u0627\u0644\u0645\u062E\u0627\u0637\u0631 \u0627\u0644\u0623\u0645\u0646\u064A\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0645\u0646\u0632\u0644\u064A\u0646 \u{1F3E0}\u{1F3E0} \u064A\u062A\u0628\u0627\u062F\u0644\u0627\u0646 \u0627\u0644\u0623\u0628\u0648\u0627\u0628 \u{1F6AA}. \u0634\u062E\u0635 \u064A\u062F\u062E\u0644 \u0645\u0646\u0632\u0644\u064B\u0627 \u063A\u0631\u064A\u0628\u064B\u0627 \u0648\u064A\u062A\u062C\u0648\u0644 \u0628\u062D\u0630\u0631 \u{1F440}. \u0641\u062C\u0623\u0629\u060C \u062A\u0638\u0647\u0631 \u0643\u0644\u0627\u0628 \u062D\u0631\u0627\u0633\u0629 \u{1F415} \u0648\u062A\u0631\u0627\u0642\u0628\u0647. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u062B\u0642\u0629 \u0642\u0628\u0644 \u0627\u0644\u062A\u0628\u0627\u062F\u0644!'" };
      HELP_DATA2["m\xFCndlich_exam27_q2"] = { text: "Haustausch keine gute Idee \u2192 Risiken gro\xDF \u2192 Hotels sicherer", meaning: "\u062A\u0628\u0627\u062F\u0644 \u0627\u0644\u0645\u0646\u0627\u0632\u0644 \u0641\u0643\u0631\u0629 \u0633\u064A\u0626\u0629\u060C \u0627\u0644\u0645\u062E\u0627\u0637\u0631 \u0623\u0643\u0628\u0631 \u0645\u0646 \u0627\u0644\u0641\u0648\u0627\u0626\u062F\u060C \u0648\u0627\u0644\u0641\u0646\u0627\u062F\u0642 \u0623\u0643\u062B\u0631 \u0623\u0645\u0627\u0646\u064B\u0627", keywords: ["keine gute Idee", "Risiken", "Hotels sicherer"], simplified: "\u0644\u0627 \u062A\u062E\u0627\u0637\u0631 \u0628\u062A\u0628\u0627\u062F\u0644 \u0627\u0644\u0645\u0646\u0627\u0632\u0644\u060C \u0627\u062D\u062C\u0632 \u0641\u0646\u062F\u0642\u064B\u0627 \u064A\u0643\u0648\u0646 \u0622\u0645\u0646\u064B\u0627 \u0648\u0645\u0646\u0638\u0645\u064B\u0627", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0634\u062E\u0635\u064B\u0627 \u064A\u0642\u0631\u0631 \u0628\u064A\u0646 \u0645\u0646\u0632\u0644 \u063A\u0631\u064A\u0628 \u{1F3DA}\uFE0F \u0648\u0641\u0646\u062F\u0642 \u{1F3E8}. \u0641\u062C\u0623\u0629\u060C \u064A\u062A\u062D\u0648\u0644 \u0627\u0644\u0645\u0646\u0632\u0644 \u0627\u0644\u063A\u0631\u064A\u0628 \u0625\u0644\u0649 \u0648\u062D\u0634 \u{1F479} \u0648\u0627\u0644\u0641\u0646\u062F\u0642 \u0625\u0644\u0649 \u0642\u0644\u0639\u0629 \u0645\u062D\u0635\u0646\u0629 \u{1F3F0}. \u064A\u0631\u0643\u0636 \u0646\u062D\u0648 \u0627\u0644\u0642\u0644\u0639\u0629 \u0648\u064A\u063A\u0644\u0642 \u0627\u0644\u0628\u0627\u0628 \u062E\u0644\u0641\u0647. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u0623\u0645\u0627\u0646 \u0623\u0648\u0644\u0627\u064B!'" };
      HELP_DATA2["m\xFCndlich_exam27_q3"] = { text: "Bekannter \u2192 Haustausch \u2192 unsicher \u2192 Sicherheit \u2192 Hotel gew\xE4hlt", meaning: "\u062A\u062C\u0631\u0628\u0629 \u0645\u0639 \u062A\u0628\u0627\u062F\u0644 \u0627\u0644\u0645\u0646\u0627\u0632\u0644: \u0643\u0627\u0646 \u063A\u064A\u0631 \u0645\u0631\u062A\u0627\u062D \u0648\u0627\u062E\u062A\u0627\u0631 \u0627\u0644\u0641\u0646\u062F\u0642", keywords: ["Haustausch", "unsicher", "Hotel"], simplified: "\u0635\u062F\u064A\u0642 \u0641\u0643\u0631 \u0628\u062A\u0628\u0627\u062F\u0644 \u0627\u0644\u0645\u0646\u0627\u0632\u0644 \u0644\u0643\u0646\u0647 \u0634\u0639\u0631 \u0628\u0639\u062F\u0645 \u0627\u0644\u0623\u0645\u0627\u0646 \u0648\u0641\u0636\u0644 \u0627\u0644\u0641\u0646\u062F\u0642", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0634\u062E\u0635\u064B\u0627 \u0648\u0627\u0642\u0641\u064B\u0627 \u0628\u064A\u0646 \u0628\u0627\u0628\u064A\u0646: \u0628\u0627\u0628 \u0645\u0643\u062A\u0648\u0628 \u0639\u0644\u064A\u0647 '\u062A\u0628\u0627\u062F\u0644 \u0645\u0646\u0627\u0632\u0644' \u0648\u0627\u0644\u0622\u062E\u0631 '\u0641\u0646\u062F\u0642'. \u064A\u0641\u062A\u062D \u0628\u0627\u0628 \u0627\u0644\u062A\u0628\u0627\u062F\u0644 \u0648\u064A\u0634\u0645 \u0631\u0627\u0626\u062D\u0629 \u063A\u0631\u064A\u0628\u0629 \u{1F443}\u060C \u0641\u064A\u063A\u0644\u0642 \u0628\u0633\u0631\u0639\u0629 \u0648\u064A\u062F\u062E\u0644 \u0627\u0644\u0641\u0646\u062F\u0642 \u{1F3E8}. \u062B\u0645 \u064A\u062C\u0644\u0633 \u0645\u0631\u062A\u0627\u062D\u064B\u0627 \u0639\u0644\u0649 \u0633\u0631\u064A\u0631 \u{1F6CF}\uFE0F \u0648\u064A\u0642\u0648\u0644: '\u0627\u0644\u0623\u0641\u0636\u0644 \u0627\u0644\u0644\u064A \u0645\u0636\u0645\u0648\u0646!'" };
      HELP_DATA2["m\xFCndlich_exam28_q1"] = { text: "Solarium \u2192 Gesundheit \u2192 Vitamin D \u2192 Hautsch\xE4den \u2192 Krebs", meaning: "\u0623\u0633\u0631\u0629 \u0627\u0644\u062A\u0633\u0645\u064A\u0631 \u0641\u064A \u0627\u0644\u0634\u062A\u0627\u0621: \u0642\u062F \u062A\u0636\u0631 \u0627\u0644\u0628\u0634\u0631\u0629 \u0648\u062A\u0633\u0628\u0628 \u0627\u0644\u0633\u0631\u0637\u0627\u0646", keywords: ["Solarium", "Vitamin D", "Krebs"], simplified: "\u0627\u0644\u0634\u0645\u0633 \u0637\u0628\u064A\u0639\u064A\u064B\u0651\u0629 \u0623\u0641\u0636\u0644 \u0645\u0646 \u0623\u0633\u0631\u0629 \u0627\u0644\u062A\u0633\u0645\u064A\u0631\u060C \u0641\u0647\u064A \u062E\u0637\u064A\u0631\u0629 \u062C\u062F\u064B\u0627", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0634\u062E\u0635\u064B\u0627 \u064A\u0633\u062A\u0644\u0642\u064A \u0641\u064A \u0633\u0631\u064A\u0631 \u062A\u0633\u0645\u064A\u0631 \u{1F6CF}\uFE0F\u060C \u0641\u062A\u0638\u0647\u0631 \u0628\u0642\u0639 \u0633\u0648\u062F\u0627\u0621 \u26AB \u0639\u0644\u0649 \u0628\u0634\u0631\u062A\u0647. \u0641\u062C\u0623\u0629\u060C \u064A\u0635\u0631\u062E \u0627\u0644\u0633\u0631\u064A\u0631 \u0648\u064A\u062E\u0631\u062C \u0645\u0646\u0647 \u062F\u062E\u0627\u0646 \u0623\u0633\u0648\u062F \u{1F4A8}. \u062B\u0645 \u064A\u0631\u0643\u0636 \u0646\u062D\u0648 \u0627\u0644\u0634\u0645\u0633 \u2600\uFE0F \u0648\u064A\u0633\u062A\u0644\u0642\u064A \u062A\u062D\u062A\u0647\u0627 \u0633\u0639\u064A\u062F\u064B\u0627. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0637\u0628\u064A\u0639\u064A \u062F\u0627\u0626\u0645\u064B\u0627 \u0623\u0641\u0636\u0644!'" };
      HELP_DATA2["m\xFCndlich_exam28_q2"] = { text: "Solarien vermeiden \u2192 besser nat\xFCrlich gesund bleiben", meaning: "\u062A\u062C\u0646\u0628 \u0623\u0633\u0631\u0629 \u0627\u0644\u062A\u0633\u0645\u064A\u0631\u060C \u0648\u0627\u0644\u0628\u0642\u0627\u0621 \u0628\u0635\u062D\u0629 \u0637\u0628\u064A\u0639\u064A\u0629 \u0623\u0641\u0636\u0644", keywords: ["vermeiden", "nat\xFCrlich", "gesund bleiben"], simplified: "\u0627\u0628\u062A\u0639\u062F \u0639\u0646 \u0623\u0633\u0631\u0629 \u0627\u0644\u062A\u0633\u0645\u064A\u0631\u060C \u0641\u0637\u0628\u064A\u0639\u062A\u0643 \u0623\u062C\u0645\u0644 \u0648\u0623\u0643\u062B\u0631 \u0635\u062D\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u064A\u062F\u064B\u0627 \u062A\u062D\u0645\u0644 \u0644\u0627\u0641\u062A\u0629 '\u0645\u0645\u0646\u0648\u0639' \u{1F6AB} \u0639\u0644\u0649 \u0633\u0631\u064A\u0631 \u062A\u0633\u0645\u064A\u0631. \u0648\u0641\u062C\u0623\u0629\u060C \u062A\u062A\u062D\u0648\u0644 \u0627\u0644\u064A\u062F \u0625\u0644\u0649 \u0634\u062C\u0631\u0629 \u{1F333} \u0648\u064A\u0646\u0645\u0648 \u062D\u0648\u0644\u0647\u0627 \u0632\u0647\u0648\u0631 \u{1F338}. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0623\u0634\u0639\u0629 \u0634\u0645\u0633 \u2600\uFE0F \u0630\u0647\u0628\u064A\u0629 \u062A\u0636\u064A\u0621 \u0627\u0644\u0645\u0643\u0627\u0646. \u062B\u0645 \u062A\u0642\u0648\u0644 \u0627\u0644\u064A\u062F: '\u0627\u0644\u0637\u0628\u064A\u0639\u0629 \u0623\u0645 \u0627\u0644\u062C\u0645\u0627\u0644!'" };
      HELP_DATA2["m\xFCndlich_exam28_q3"] = { text: "Winter \u2192 m\xFCde \u2192 wenig Energie \u2192 Sonnenlicht fehlt", meaning: "\u062A\u062C\u0631\u0628\u0629: \u0627\u0644\u062A\u0639\u0628 \u0648\u0642\u0644\u0629 \u0627\u0644\u0637\u0627\u0642\u0629 \u0641\u064A \u0627\u0644\u0634\u062A\u0627\u0621 \u0628\u0633\u0628\u0628 \u0646\u0642\u0635 \u0627\u0644\u0634\u0645\u0633", keywords: ["Winter", "m\xFCde", "Sonnenlicht"], simplified: "\u0641\u064A \u0627\u0644\u0634\u062A\u0627\u0621 \u0643\u0646\u062A \u0645\u062A\u0639\u0628\u064B\u0627 \u0648\u0623\u062F\u0631\u0643\u062A \u0623\u0646 \u0627\u0644\u0633\u0628\u0628 \u0647\u0648 \u0642\u0644\u0629 \u0627\u0644\u0634\u0645\u0633", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0634\u062E\u0635\u064B\u0627 \u0646\u0627\u0626\u0645\u064B\u0627 \u0641\u064A \u0627\u0644\u0634\u062A\u0627\u0621 \u2744\uFE0F \u0645\u063A\u0637\u0649 \u0628\u0628\u0637\u0627\u0646\u064A\u0629\u060C \u0648\u0639\u0644\u064A\u0647 \u0639\u0644\u0627\u0645\u0629 '\u062A\u0639\u0628' \u{1F634}. \u0641\u062C\u0623\u0629\u060C \u062A\u0634\u0631\u0642 \u0634\u0645\u0633 \u2600\uFE0F \u0648\u062A\u0641\u062A\u062D \u0627\u0644\u0633\u062A\u0627\u0626\u0631\u060C \u0641\u064A\u0646\u0647\u0636 \u0646\u0634\u064A\u0637\u064B\u0627 \u{1F3C3}. \u062B\u0645 \u064A\u0628\u062A\u0633\u0645 \u0648\u064A\u0642\u0648\u0644: '\u0623\u0646\u0627 \u0628\u062D\u0627\u062C\u0629 \u0644\u0634\u0645\u0633\u064A!'" };
      HELP_DATA2["m\xFCndlich_exam29_q1"] = { text: "Schulqualit\xE4t \u2192 Tests \u2192 Deutsch \u2192 Mathematik \u2192 Kritik \u2192 Wohlbefinden \u2192 soziale F\xE4higkeiten", meaning: "\u0627\u062E\u062A\u0628\u0627\u0631\u0627\u062A \u062C\u0648\u062F\u0629 \u0627\u0644\u0645\u062F\u0631\u0633\u0629 \u062A\u0642\u064A\u0633 \u0627\u0644\u0631\u064A\u0627\u0636\u064A\u0627\u062A \u0648\u0627\u0644\u0623\u0644\u0645\u0627\u0646\u064A\u0629 \u0641\u0642\u0637\u060C \u0648\u062A\u0647\u0645\u0644 \u0627\u0644\u0631\u0641\u0627\u0647\u064A\u0629 \u0648\u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062A \u0627\u0644\u0627\u062C\u062A\u0645\u0627\u0639\u064A\u0629", keywords: ["Schulqualit\xE4t", "Tests", "soziale F\xE4higkeiten"], simplified: "\u0627\u0644\u0627\u062E\u062A\u0628\u0627\u0631\u0627\u062A \u0644\u0627 \u062A\u0643\u0641\u064A \u0644\u0642\u064A\u0627\u0633 \u062C\u0648\u062F\u0629 \u0627\u0644\u0645\u062F\u0631\u0633\u0629\u060C \u0641\u0627\u0644\u0633\u0639\u0627\u062F\u0629 \u0648\u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062A \u0627\u0644\u0627\u062C\u062A\u0645\u0627\u0639\u064A\u0629 \u0644\u0627 \u062A\u0642\u0627\u0633", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0645\u064A\u0632\u0627\u0646\u064B\u0627 \u2696\uFE0F \u064A\u0648\u0636\u0639 \u0641\u064A\u0647 \u0643\u062A\u0627\u0628 \u0631\u064A\u0627\u0636\u064A\u0627\u062A \u{1F4D0} \u0648\u0622\u062E\u0631 \u0623\u0644\u0645\u0627\u0646\u064A \u{1F1E9}\u{1F1EA}\u060C \u0644\u0643\u0646 \u0642\u0644\u0628\u064B\u0627 \u2764\uFE0F \u0648\u064A\u062F\u064B\u0627 \u{1F91D} \u062A\u0633\u0642\u0637\u0627\u0646 \u0645\u0646 \u0627\u0644\u0643\u0641\u0629 \u0627\u0644\u0623\u062E\u0631\u0649. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0647\u0646\u0627\u0643 \u0645\u0627 \u0647\u0648 \u0623\u0647\u0645 \u0645\u0646 \u0627\u0644\u062F\u0631\u062C\u0627\u062A!'" };
      HELP_DATA2["m\xFCndlich_exam29_q2"] = { text: "Tests hilfreich \u2192 nicht ausreichend \u2192 mehr als Noten", meaning: "\u0627\u0644\u0627\u062E\u062A\u0628\u0627\u0631\u0627\u062A \u0645\u0641\u064A\u062F\u0629 \u0644\u0643\u0646\u0647\u0627 \u063A\u064A\u0631 \u0643\u0627\u0641\u064A\u0629\u060C \u0641\u0627\u0644\u0645\u062F\u0631\u0633\u0629 \u0623\u0643\u062B\u0631 \u0645\u0646 \u062F\u0631\u062C\u0627\u062A", keywords: ["hilfreich", "nicht ausreichend", "mehr als Noten"], simplified: "\u0627\u0644\u0627\u062E\u062A\u0628\u0627\u0631\u0627\u062A \u0645\u0641\u064A\u062F\u0629\u060C \u0644\u0643\u0646 \u0627\u0644\u0645\u062F\u0631\u0633\u0629 \u062A\u0639\u062F\u0643 \u0644\u0644\u062D\u064A\u0627\u0629\u060C \u0648\u0644\u064A\u0633 \u0641\u0642\u0637 \u0644\u0644\u0646\u062C\u0627\u062D \u0641\u064A\u0647\u0627", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0637\u0627\u0644\u0628\u064B\u0627 \u064A\u062D\u0645\u0644 \u0634\u0647\u0627\u062F\u0629 \u0628\u062A\u0642\u062F\u064A\u0631 \u0645\u0645\u062A\u0627\u0632 \u{1F393}\u060C \u0644\u0643\u0646\u0647 \u064A\u0628\u062F\u0648 \u062D\u0632\u064A\u0646\u064B\u0627 \u{1F614}. \u0641\u062C\u0623\u0629\u060C \u062A\u0638\u0647\u0631 \u0623\u0637\u0641\u0627\u0644 \u064A\u0644\u0639\u0628\u0648\u0646 \u0645\u0639\u0647 \u0648\u064A\u0636\u062D\u0643\u0648\u0646 \u{1F60A}\u060C \u0648\u062A\u0638\u0647\u0631 \u0645\u0647\u0627\u0631\u0627\u062A \u0627\u062C\u062A\u0645\u0627\u0639\u064A\u0629 \u0643\u0627\u0644\u0646\u062C\u0648\u0645 \u062D\u0648\u0644\u0647 \u2B50. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u0646\u062C\u0627\u062D \u0644\u064A\u0633 \u0645\u062C\u0631\u062F \u0648\u0631\u0642\u0629!'" };
      HELP_DATA2["m\xFCndlich_exam29_q3"] = { text: "Ich \u2192 viele Tests \u2192 gute Noten \u2192 Stress \u2192 nicht alles zeigen", meaning: "\u062A\u062C\u0631\u0628\u0629: \u0627\u062E\u062A\u0628\u0627\u0631\u0627\u062A \u0643\u062B\u064A\u0631\u0629 \u0648\u062F\u0631\u062C\u0627\u062A \u062C\u064A\u062F\u0629\u060C \u0644\u0643\u0646 \u0627\u0644\u062A\u0648\u062A\u0631 \u0643\u0627\u0646 \u0645\u0648\u062C\u0648\u062F\u064B\u0627\u060C \u0641\u0627\u0644\u0627\u062E\u062A\u0628\u0627\u0631\u0627\u062A \u0644\u0627 \u062A\u0638\u0647\u0631 \u0643\u0644 \u0634\u064A\u0621", keywords: ["viele Tests", "gute Noten", "Stress"], simplified: "\u062D\u0635\u0644\u062A \u0639\u0644\u0649 \u062F\u0631\u062C\u0627\u062A \u0639\u0627\u0644\u064A\u0629 \u0644\u0643\u0646\u064A \u0643\u0646\u062A \u0645\u062A\u0648\u062A\u0631\u064B\u0627\u060C \u0641\u0627\u0644\u062F\u0631\u062C\u0627\u062A \u0644\u0627 \u062A\u0639\u0643\u0633 \u0643\u0644 \u0634\u064A\u0621", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0637\u0627\u0644\u0628\u064B\u0627 \u064A\u062C\u0644\u0633 \u0641\u064A \u0627\u0645\u062A\u062D\u0627\u0646 \u270D\uFE0F\u060C \u0639\u0631\u0642\u0647 \u064A\u062A\u0635\u0628\u0628 \u{1F4A6} \u0648\u064A\u062F\u0647 \u062A\u0631\u062A\u062C\u0641. \u064A\u062E\u0631\u062C \u0628\u0634\u0647\u0627\u062F\u0629 \u0645\u0645\u062A\u0627\u0632\u0629 \u{1F393} \u0644\u0643\u0646 \u0642\u0644\u0628\u0647 \u064A\u0646\u0628\u0636 \u0628\u0633\u0631\u0639\u0629 \u{1F493}. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0623\u064A\u0627\u062F\u064A \u062A\u0637\u0628\u0637\u062D \u0639\u0644\u0649 \u0643\u062A\u0641\u0647 \u0648\u062A\u0642\u0648\u0644: '\u0647\u062F\u0626\u060C \u0623\u0646\u062A \u0623\u0643\u062B\u0631 \u0645\u0646 \u062F\u0631\u062C\u0627\u062A\u0643!'" };
      HELP_DATA2["m\xFCndlich_exam30_q1"] = { text: "Hausfrau \u2192 Familie \u2192 Kinder \u2192 Bef\xFCrworter \u2192 Kritiker \u2192 Abh\xE4ngigkeit \u2192 Rollenbilder", meaning: "\u0631\u0628\u0629 \u0627\u0644\u0645\u0646\u0632\u0644: \u0645\u0624\u064A\u062F\u0648\u0646 \u064A\u0631\u0648\u0646 \u0648\u0642\u062A\u064B\u0627 \u0644\u0644\u0639\u0627\u0626\u0644\u0629\u060C \u0648\u0645\u0639\u0627\u0631\u0636\u0648\u0646 \u064A\u0631\u0648\u0646 \u0627\u0639\u062A\u0645\u0627\u062F\u064B\u0627 \u0648\u0623\u062F\u0648\u0627\u0631\u064B\u0627 \u062A\u0642\u0644\u064A\u062F\u064A\u0629", keywords: ["Hausfrau", "Abh\xE4ngigkeit", "Rollenbilder"], simplified: "\u0643\u0648\u0646\u0643 \u0631\u0628\u0629 \u0645\u0646\u0632\u0644 \u0627\u062E\u062A\u064A\u0627\u0631 \u0634\u062E\u0635\u064A\u060C \u0644\u0643\u0646 \u0627\u0644\u0627\u0633\u062A\u0642\u0644\u0627\u0644 \u0627\u0644\u0645\u0627\u0644\u064A \u0645\u0647\u0645 \u0623\u064A\u0636\u064B\u0627", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0627\u0645\u0631\u0623\u0629 \u{1F469} \u062C\u0627\u0644\u0633\u0629 \u0645\u0639 \u0623\u0637\u0641\u0627\u0644\u0647\u0627 \u{1F9D2}\u{1F467}\u060C \u0644\u0643\u0646\u0647\u0627 \u0645\u0642\u064A\u062F\u0629 \u0628\u0633\u0644\u0627\u0633\u0644 \u26D3\uFE0F. \u0641\u062C\u0623\u0629\u060C \u062A\u0638\u0647\u0631 \u0646\u0642\u0648\u062F \u{1F4B0} \u0648\u062A\u0642\u0637\u0639 \u0627\u0644\u0633\u0644\u0627\u0633\u0644. \u062B\u0645 \u062A\u0642\u0641 \u0648\u062A\u0645\u0634\u064A \u0628\u062D\u0631\u064A\u0629 \u{1F54A}\uFE0F. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u062D\u0631\u064A\u0629 \u0627\u0644\u0645\u0627\u0644\u064A\u0629 \u0645\u0647\u0645\u0629!'" };
      HELP_DATA2["m\xFCndlich_exam30_q2"] = { text: "Hausfrau Entscheidung \u2192 Unabh\xE4ngigkeit wichtig", meaning: "\u0643\u0648\u0646\u0643 \u0631\u0628\u0629 \u0645\u0646\u0632\u0644 \u0642\u0631\u0627\u0631 \u0634\u062E\u0635\u064A\u060C \u0644\u0643\u0646 \u0627\u0644\u0627\u0633\u062A\u0642\u0644\u0627\u0644\u064A\u0629 \u0645\u0647\u0645\u0629", keywords: ["Entscheidung", "Unabh\xE4ngigkeit", "wichtig"], simplified: "\u0644\u0643 \u0627\u0644\u062E\u064A\u0627\u0631 \u0641\u064A \u0623\u0646 \u062A\u0643\u0648\u0646 \u0631\u0628\u0629 \u0645\u0646\u0632\u0644\u060C \u0645\u0639 \u0639\u062F\u0645 \u0627\u0644\u062A\u062E\u0644\u064A \u0639\u0646 \u0627\u0633\u062A\u0642\u0644\u0627\u0644\u064A\u062A\u0643", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0627\u0645\u0631\u0623\u0629 \u0623\u0645\u0627\u0645 \u0628\u0627\u0628\u064A\u0646: \u0628\u0627\u0628 \u0645\u0643\u062A\u0648\u0628 \u0639\u0644\u064A\u0647 '\u0628\u064A\u062A' \u{1F3E0} \u0648\u0628\u0627\u0628 \u0645\u0643\u062A\u0648\u0628 \u0639\u0644\u064A\u0647 '\u0639\u0645\u0644' \u{1F4BC}. \u062A\u0641\u062A\u062D \u0627\u0644\u0628\u0627\u0628\u064A\u0646 \u0645\u0639\u064B\u0627 \u0648\u062A\u062E\u0631\u062C \u0645\u0646\u0647\u0645\u0627 \u0623\u064A\u0627\u062F\u064D \u{1F91D} \u062A\u0645\u0633\u0643 \u0628\u064A\u062F\u064A\u0647\u0627. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0646\u062C\u0645\u0629 \u2B50 \u0648\u062A\u0636\u064A\u0621 \u0648\u062C\u0647\u0647\u0627. \u062B\u0645 \u062A\u0642\u0648\u0644: '\u0623\u0646\u0627 \u0623\u062E\u062A\u0627\u0631 \u0627\u0644\u062A\u0648\u0627\u0632\u0646!'" };
      HELP_DATA2["m\xFCndlich_exam30_q3"] = { text: "Bekannte \u2192 Hausfrau \u2192 Kinder \u2192 Haushalt \u2192 Unsicherheit", meaning: "\u062A\u062C\u0631\u0628\u0629 \u0635\u062F\u064A\u0642\u0629 \u0631\u0628\u0629 \u0645\u0646\u0632\u0644: \u0643\u0627\u0646\u062A \u0642\u0644\u0642\u0629 \u0628\u0634\u0623\u0646 \u0645\u0633\u062A\u0642\u0628\u0644\u0647\u0627 \u0627\u0644\u0645\u0647\u0646\u064A", keywords: ["Bekannte", "Hausfrau", "Unsicherheit"], simplified: "\u0635\u062F\u064A\u0642\u0629 \u0631\u0628\u0629 \u0645\u0646\u0632\u0644 \u0643\u0627\u0646\u062A \u0633\u0639\u064A\u062F\u0629 \u0644\u0643\u0646\u0647\u0627 \u0642\u0644\u0642\u062A \u0623\u062D\u064A\u0627\u0646\u064B\u0627 \u0645\u0646 \u0645\u0633\u062A\u0642\u0628\u0644\u0647\u0627 \u0627\u0644\u0645\u0647\u0646\u064A", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0627\u0645\u0631\u0623\u0629 \u062A\u0646\u0638\u0641 \u0627\u0644\u0645\u0646\u0632\u0644 \u{1F9F9}\u060C \u0648\u0641\u062C\u0623\u0629 \u062A\u0638\u0647\u0631 \u0623\u0645\u0627\u0645\u0647\u0627 \u0633\u0627\u0639\u0629 \u23F0 \u062A\u0633\u064A\u0631 \u0628\u0633\u0631\u0639\u0629 \u0648\u062A\u0630\u0643\u0651\u0631\u0647\u0627 \u0628\u0627\u0644\u0648\u0642\u062A. \u062A\u062A\u0648\u0642\u0641 \u0648\u062A\u0646\u0638\u0631 \u0625\u0644\u0649 \u0627\u0644\u0645\u0631\u0622\u0629 \u0648\u062A\u062A\u0633\u0627\u0621\u0644 \u{1F914}. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u062A\u062E\u0637\u064A\u0637 \u0644\u0644\u0645\u0633\u062A\u0642\u0628\u0644 \u064A\u0631\u064A\u062D \u0627\u0644\u0628\u0627\u0644!'" };
      HELP_DATA2["m\xFCndlich_exam31_q1"] = { text: "Fernsehen \u2192 Kinder \u2192 schlechte Noten \u2192 weniger Bewegung \u2192 Gesundheit", meaning: "\u0643\u062B\u0631\u0629 \u0627\u0644\u062A\u0644\u0641\u0627\u0632 \u062A\u0624\u062F\u064A \u0644\u062F\u0631\u062C\u0627\u062A \u0623\u0633\u0648\u0623 \u0648\u0646\u0634\u0627\u0637 \u0623\u0642\u0644\u060C \u0648\u062A\u0636\u0631 \u0628\u0627\u0644\u0635\u062D\u0629", keywords: ["schlechte Noten", "weniger Bewegung", "Gesundheit"], simplified: "\u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0627\u0644\u0630\u064A\u0646 \u064A\u0634\u0627\u0647\u062F\u0648\u0646 \u062A\u0644\u0641\u0627\u0632\u064B\u0627 \u0643\u062B\u064A\u0631\u064B\u0627 \u062A\u0643\u0648\u0646 \u062F\u0631\u062C\u0627\u062A\u0647\u0645 \u0623\u0633\u0648\u0623 \u0648\u0635\u062D\u062A\u0647\u0645 \u0623\u0636\u0639\u0641", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0637\u0641\u0644\u064B\u0627 \u062C\u0627\u0644\u0633\u064B\u0627 \u0623\u0645\u0627\u0645 \u062A\u0644\u0641\u0627\u0632 \u{1F4FA}\u060C \u062A\u062E\u0631\u062C \u0645\u0646 \u0627\u0644\u0634\u0627\u0634\u0629 \u0623\u064A\u0627\u062F\u064D \u{1F590}\uFE0F \u062A\u0633\u062D\u0628\u0647 \u0646\u062D\u0648\u0647\u0627. \u062F\u0631\u062C\u0627\u062A\u0647 \u062A\u0646\u062E\u0641\u0636 \u{1F4C9} \u0648\u0639\u0636\u0644\u0627\u062A\u0647 \u062A\u0636\u0639\u0641 \u{1F4AA}. \u0641\u062C\u0623\u0629\u060C \u064A\u0636\u063A\u0637 \u0632\u0631 \u0627\u0644\u0625\u064A\u0642\u0627\u0641 \u23F9\uFE0F \u0648\u064A\u062E\u0631\u062C \u0644\u0644\u062D\u062F\u064A\u0642\u0629 \u{1F333}. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u062D\u0631\u0643\u0629 = \u062D\u064A\u0627\u0629!'" };
      HELP_DATA2["m\xFCndlich_exam31_q2"] = { text: "Zu viel Fernsehen schlecht \u2192 gute Programme manchmal n\xFCtzlich", meaning: "\u0643\u062B\u0631\u0629 \u0627\u0644\u062A\u0644\u0641\u0627\u0632 \u0645\u0636\u0631\u0629\u060C \u0644\u0643\u0646 \u0627\u0644\u0628\u0631\u0627\u0645\u062C \u0627\u0644\u062C\u064A\u062F\u0629 \u0645\u0641\u064A\u062F\u0629 \u0623\u062D\u064A\u0627\u0646\u064B\u0627", keywords: ["schlecht", "gute Programme", "n\xFCtzlich"], simplified: "\u0644\u0627 \u062A\u0641\u0631\u0637 \u0641\u064A \u0627\u0644\u062A\u0644\u0641\u0627\u0632\u060C \u0644\u0643\u0646 \u0628\u0639\u0636 \u0627\u0644\u0628\u0631\u0627\u0645\u062C \u0627\u0644\u062C\u064A\u062F\u0629 \u0642\u062F \u062A\u0641\u064A\u062F\u0643", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u062C\u0647\u0627\u0632 \u062A\u062D\u0643\u0645 \u{1F4FA}\u060C \u064A\u062F \u062A\u062A\u062D\u0643\u0645 \u0628\u0647 \u0648\u062A\u0642\u0644\u0628 \u0627\u0644\u0642\u0646\u0648\u0627\u062A \u0628\u0633\u0631\u0639\u0629 \u23E9. \u0641\u062C\u0623\u0629\u060C \u062A\u062A\u0648\u0642\u0641 \u0639\u0646\u062F \u0642\u0646\u0627\u0629 \u0648\u062B\u0627\u0626\u0642\u064A\u0629 \u{1F418}\u060C \u0641\u064A\u062A\u0648\u0642\u0641 \u0627\u0644\u0639\u0642\u0644 \u{1F9E0} \u0648\u064A\u062A\u0623\u0645\u0644. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u062C\u0648\u062F\u0629 > \u0627\u0644\u0643\u0645\u064A\u0629!'" };
      HELP_DATA2["m\xFCndlich_exam31_q3"] = { text: "Ich \u2192 Kind \u2192 viel Fernsehen \u2192 Hausaufgaben schlecht \u2192 sp\xE4ter besser konzentriert", meaning: "\u062A\u062C\u0631\u0628\u0629 \u0627\u0644\u0637\u0641\u0648\u0644\u0629: \u062A\u0644\u0641\u0627\u0632 \u0643\u062B\u064A\u0631 = \u0648\u0627\u062C\u0628\u0627\u062A \u0645\u0647\u0645\u0644\u0629\u060C \u0642\u0644\u0629 \u062A\u0644\u0641\u0627\u0632 = \u062A\u0631\u0643\u064A\u0632 \u0623\u0641\u0636\u0644", keywords: ["viel Fernsehen", "Hausaufgaben", "konzentriert"], simplified: "\u0639\u0646\u062F\u0645\u0627 \u0643\u0646\u062A \u0637\u0641\u0644\u0627\u064B \u0634\u0627\u0647\u062F\u062A \u062A\u0644\u0641\u0627\u0632\u064B\u0627 \u0643\u062B\u064A\u0631\u064B\u0627 \u0648\u0623\u0647\u0645\u0644\u062A \u0648\u0627\u062C\u0628\u0627\u062A\u064A\u060C \u0648\u0644\u0645\u0627 \u0642\u0644\u0644\u062A\u060C \u062A\u062D\u0633\u0646 \u062A\u0631\u0643\u064A\u0632\u064A", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0637\u0641\u0644\u064B\u0627 \u0623\u0645\u0627\u0645 \u062A\u0644\u0641\u0627\u0632\u060C \u064A\u0647\u0645\u0634 \u0648\u0627\u062C\u0628\u0627\u062A\u0647 \u{1F4DA}\u060C \u0641\u062A\u0638\u0647\u0631 \u0639\u0644\u0627\u0645\u0629 '\u0645\u0647\u0645\u0644' \u{1F6AB}. \u062B\u0645 \u064A\u063A\u0644\u0642 \u0627\u0644\u062A\u0644\u0641\u0627\u0632 \u0648\u064A\u0628\u062F\u0623 \u0628\u0627\u0644\u0645\u0630\u0627\u0643\u0631\u0629 \u270D\uFE0F\u060C \u0641\u062A\u0638\u0647\u0631 \u0639\u0644\u0627\u0645\u0629 '\u062A\u0631\u0643\u064A\u0632' \u{1F50D}. \u062B\u0645 \u064A\u0636\u062D\u0643 \u{1F60A} \u0648\u064A\u0642\u0648\u0644: '\u0627\u0644\u0622\u0646 \u0641\u0647\u0645\u062A!'" };
      HELP_DATA2["m\xFCndlich_exam32_q1"] = { text: "Kinder \u2192 digitale Medien \u2192 t\xE4glich \u2192 Risiken \u2192 Gewalt \u2192 Cybermobbing \u2192 Fotos", meaning: "\u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u064A\u0633\u062A\u062E\u062F\u0645\u0648\u0646 \u0627\u0644\u0648\u0633\u0627\u0626\u0637 \u0627\u0644\u0631\u0642\u0645\u064A\u0629 \u064A\u0648\u0645\u064A\u0627\u064B \u0644\u0643\u0646\u0647\u0645 \u064A\u0642\u0644\u0644\u0648\u0646 \u0645\u0646 \u0645\u062E\u0627\u0637\u0631 \u0627\u0644\u0639\u0646\u0641 \u0648\u0627\u0644\u062A\u0646\u0645\u0631", keywords: ["digitale Medien", "Risiken", "Cybermobbing"], simplified: "\u0627\u062D\u0630\u0631\u060C \u0641\u0627\u0644\u0639\u0627\u0644\u0645 \u0627\u0644\u0631\u0642\u0645\u064A \u0645\u0644\u064A\u0621 \u0628\u0627\u0644\u0645\u062E\u0627\u0637\u0631 \u0627\u0644\u062A\u064A \u0644\u0627 \u064A\u0631\u0627\u0647\u0627 \u0627\u0644\u0623\u0637\u0641\u0627\u0644", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0637\u0641\u0644\u064B\u0627 \u064A\u062D\u062F\u0642 \u0641\u064A \u0647\u0627\u062A\u0641 \u{1F4F1}\u060C \u0648\u0641\u062C\u0623\u0629 \u062A\u062E\u0631\u062C \u0645\u0646 \u0627\u0644\u0647\u0627\u062A\u0641 \u0648\u062D\u0648\u0634 \u0635\u063A\u064A\u0631\u0629 \u{1F9A0} \u062A\u062A\u0631\u0627\u0642\u0635 \u062D\u0648\u0644\u0647. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0623\u064A\u0627\u062F\u064D \u{1F47B} \u062A\u062D\u0627\u0648\u0644 \u0627\u0646\u062A\u0632\u0627\u0639 \u0635\u0648\u0631\u0647 \u{1F4F8}. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u0639\u0627\u0644\u0645 \u0627\u0644\u0631\u0642\u0645\u064A \u0644\u064A\u0633 \u0622\u0645\u0646\u064B\u0627 \u062F\u0627\u0626\u0645\u064B\u0627!'" };
      HELP_DATA2["m\xFCndlich_exam32_q2"] = { text: "Nutzung wichtig \u2192 Gefahren erkl\xE4ren \u2192 Hilfe suchen", meaning: "\u0627\u0644\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0645\u0647\u0645 \u0644\u0643\u0646 \u064A\u062C\u0628 \u0634\u0631\u062D \u0627\u0644\u0645\u062E\u0627\u0637\u0631 \u0648\u062A\u0639\u0644\u064A\u0645 \u0637\u0644\u0628 \u0627\u0644\u0645\u0633\u0627\u0639\u062F\u0629", keywords: ["Nutzung wichtig", "Gefahren erkl\xE4ren", "Hilfe suchen"], simplified: "\u0639\u0644\u0651\u0645 \u0637\u0641\u0644\u0643 \u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A \u0645\u0639 \u0634\u0631\u062D \u0627\u0644\u0645\u062E\u0627\u0637\u0631 \u0648\u062A\u0639\u0644\u064A\u0645\u0647 \u0637\u0644\u0628 \u0627\u0644\u0645\u0633\u0627\u0639\u062F\u0629 \u0639\u0646\u062F \u0627\u0644\u062D\u0627\u062C\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0623\u0628\u064B\u0627 \u{1F468} \u064A\u0645\u0633\u0643 \u0628\u064A\u062F \u0627\u0628\u0646\u0647 \u{1F9D1}\u060C \u0648\u064A\u0634\u0631\u062D \u0644\u0647 \u0627\u0644\u0647\u0627\u062A\u0641 \u{1F4F1}\u060C \u0648\u062A\u0638\u0647\u0631 \u0623\u064A\u0627\u062F\u064D \u062A\u062D\u0630\u0631 \u0645\u0646 \u0628\u0639\u0636 \u0627\u0644\u062A\u0637\u0628\u064A\u0642\u0627\u062A \u{1F6AB}. \u062B\u0645 \u064A\u0636\u063A\u0637 \u0627\u0644\u0637\u0641\u0644 \u0639\u0644\u0649 \u0632\u0631 '\u0645\u0633\u0627\u0639\u062F\u0629' \u{1F198} \u0648\u062A\u0638\u0647\u0631 \u0646\u062C\u0627\u0629 \u{1F6E1}\uFE0F. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u0648\u0639\u064A \u0647\u0648 \u0627\u0644\u062D\u0645\u0627\u064A\u0629!'" };
      HELP_DATA2["m\xFCndlich_exam32_q3"] = { text: "Freund \u2192 Handy \u2192 unbekannte Nachrichten \u2192 Eltern gefragt", meaning: "\u062A\u062C\u0631\u0628\u0629 \u0635\u062F\u064A\u0642: \u062A\u0644\u0642\u0649 \u0631\u0633\u0627\u0626\u0644 \u063A\u0631\u064A\u0628\u0629 \u0641\u0633\u0623\u0644 \u0648\u0627\u0644\u062F\u064A\u0647", keywords: ["Handy", "unbekannte Nachrichten", "Eltern"], simplified: "\u0635\u062F\u064A\u0642\u064A \u062A\u0644\u0642\u0649 \u0631\u0633\u0627\u0626\u0644 \u0645\u0646 \u0623\u0634\u062E\u0627\u0635 \u0644\u0627 \u064A\u0639\u0631\u0641\u0647\u0645 \u0641\u0633\u0623\u0644 \u0648\u0627\u0644\u062F\u064A\u0647 \u0627\u0644\u0644\u0630\u064A\u0646 \u0633\u0627\u0639\u062F\u0627\u0647", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0635\u062F\u064A\u0642\u0643 \u{1F9D1} \u064A\u0646\u0638\u0631 \u0625\u0644\u0649 \u0647\u0627\u062A\u0641\u0647 \u0641\u064A \u0630\u0647\u0648\u0644\u060C \u0631\u0633\u0627\u0626\u0644 \u063A\u0631\u064A\u0628\u0629 \u062A\u0638\u0647\u0631 \u0639\u0644\u0649 \u0627\u0644\u0634\u0627\u0634\u0629 \u{1F4E8}. \u064A\u0631\u0643\u0636 \u0625\u0644\u0649 \u0648\u0627\u0644\u062F\u064A\u0647 \u{1F3C3} \u0648\u064A\u0639\u0631\u0636\u0647\u0627 \u0639\u0644\u064A\u0647\u0645\u0627. \u062B\u0645 \u064A\u0628\u062A\u0633\u0645\u0627\u0646 \u0648\u064A\u0634\u0631\u062D\u0627\u0646 \u0644\u0647 \u0643\u064A\u0641 \u064A\u062A\u0635\u0631\u0641. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u0623\u0633\u0631\u0629 \u0647\u064A \u0627\u0644\u0645\u0644\u0627\u0630 \u0627\u0644\u0622\u0645\u0646!'" };
      HELP_DATA2["m\xFCndlich_exam33_q1"] = { text: "Klassenfahrten \u2192 Gemeinschaft \u2192 Freundschaften \u2192 Lernen \u2192 Kosten \u2192 Organisation", meaning: "\u0627\u0644\u0631\u062D\u0644\u0627\u062A \u0627\u0644\u0645\u062F\u0631\u0633\u064A\u0629 \u062A\u0642\u0648\u064A \u0627\u0644\u0645\u062C\u062A\u0645\u0639 \u0648\u062A\u0639\u0632\u0632 \u0627\u0644\u0635\u062F\u0627\u0642\u0627\u062A \u0648\u062A\u0633\u0645\u062D \u0628\u0627\u0644\u062A\u0639\u0644\u0645 \u062E\u0627\u0631\u062C \u0627\u0644\u0645\u062F\u0631\u0633\u0629", keywords: ["Klassenfahrten", "Gemeinschaft", "Lernen"], simplified: "\u0627\u0644\u0633\u0641\u0631 \u0645\u0639 \u0627\u0644\u0635\u0641 \u064A\u0642\u0648\u064A \u0627\u0644\u0639\u0644\u0627\u0642\u0627\u062A \u0648\u064A\u062A\u064A\u062D \u0627\u0644\u062A\u0639\u0644\u0645 \u062E\u0627\u0631\u062C \u0627\u0644\u0641\u0635\u0644 \u0627\u0644\u062F\u0631\u0627\u0633\u064A", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u062D\u0627\u0641\u0644\u0629 \u{1F68C} \u0645\u0644\u064A\u0626\u0629 \u0628\u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u064A\u0636\u062D\u0643\u0648\u0646 \u{1F60A}\u060C \u0648\u0647\u0645 \u064A\u062A\u062C\u0647\u0648\u0646 \u0625\u0644\u0649 \u0645\u062A\u062D\u0641 \u{1F3DB}\uFE0F. \u0641\u062C\u0623\u0629\u060C \u062A\u062E\u0631\u062C \u0642\u0644\u0648\u0628 \u2764\uFE0F \u0645\u0646 \u0627\u0644\u062D\u0627\u0641\u0644\u0629 \u0648\u062A\u0644\u062A\u0641 \u062D\u0648\u0644\u0647\u0645. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u0633\u0641\u0631 \u0645\u0639\u064B\u0627 = \u0630\u0643\u0631\u064A\u0627\u062A \u0644\u0627 \u062A\u0646\u0633\u0649!'" };
      HELP_DATA2["m\xFCndlich_exam33_q2"] = { text: "Klassenfahrten sinnvoll \u2192 st\xE4rken Miteinander \u2192 gut planen", meaning: "\u0627\u0644\u0631\u062D\u0644\u0627\u062A \u0627\u0644\u0645\u062F\u0631\u0633\u064A\u0629 \u0645\u0641\u064A\u062F\u0629 \u0648\u062A\u0642\u0648\u064A \u0627\u0644\u0639\u0644\u0627\u0642\u0627\u062A\u060C \u0645\u0639 \u0636\u0631\u0648\u0631\u0629 \u0627\u0644\u062A\u062E\u0637\u064A\u0637 \u0627\u0644\u062C\u064A\u062F", keywords: ["sinnvoll", "Miteinander", "planen"], simplified: "\u0627\u0644\u0631\u062D\u0644\u0629 \u0627\u0644\u0645\u062F\u0631\u0633\u064A\u0629 \u0631\u0627\u0626\u0639\u0629\u060C \u0644\u0643\u0646\u0647\u0627 \u062A\u062D\u062A\u0627\u062C \u0625\u0644\u0649 \u062A\u062E\u0637\u064A\u0637 \u062C\u064A\u062F \u062D\u062A\u0649 \u0644\u0627 \u062A\u0643\u0648\u0646 \u0645\u0643\u0644\u0641\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u062F \u062E\u0631\u064A\u0637\u0629 \u{1F5FA}\uFE0F\u060C \u064A\u062F \u062A\u0631\u0633\u0645 \u0639\u0644\u064A\u0647\u0627 \u062E\u0637\u0648\u0637 \u0627\u0644\u0631\u062D\u0644\u0629 \u270D\uFE0F. \u0641\u062C\u0623\u0629\u060C \u062A\u0638\u0647\u0631 \u0623\u064A\u0627\u062F\u064D \u062A\u0648\u0632\u0639 \u0627\u0644\u0645\u0647\u0627\u0645 \u{1F91D} \u0648\u0623\u062E\u0631\u0649 \u062A\u0645\u0633\u0643 \u0628\u0627\u0644\u0645\u064A\u0632\u0627\u0646\u064A\u0629 \u{1F4B0}. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u062A\u062E\u0637\u064A\u0637 = \u0646\u062C\u0627\u062D \u0627\u0644\u0631\u062D\u0644\u0629!'" };
      HELP_DATA2["m\xFCndlich_exam33_q3"] = { text: "Ich \u2192 Klassenreise \u2192 Orte besucht \u2192 Mitsch\xFCler kennengelernt", meaning: "\u062A\u062C\u0631\u0628\u0629 \u0631\u062D\u0644\u0629 \u0645\u062F\u0631\u0633\u064A\u0629: \u0632\u0631\u0646\u0627 \u0623\u0645\u0627\u0643\u0646 \u062C\u0645\u064A\u0644\u0629 \u0648\u062A\u0639\u0631\u0641\u062A \u0639\u0644\u0649 \u0632\u0645\u0644\u0627\u0626\u064A \u0623\u0643\u062B\u0631", keywords: ["Klassenreise", "Orte besucht", "Mitsch\xFCler"], simplified: "\u0631\u062D\u0644\u062A\u064A \u0627\u0644\u0645\u062F\u0631\u0633\u064A\u0629 \u0643\u0627\u0646\u062A \u0631\u0627\u0626\u0639\u0629\u060C \u0632\u0631\u0646\u0627 \u0623\u0645\u0627\u0643\u0646 \u062C\u062F\u064A\u062F\u0629 \u0648\u0623\u0635\u0628\u062D\u062A \u0623\u0635\u062F\u0642\u0627\u0621 \u0645\u0639 \u0632\u0645\u0644\u0627\u0626\u064A", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0646\u0641\u0633\u0643 \u0641\u064A \u0631\u062D\u0644\u0629 \u{1F68C}\u060C \u062A\u0632\u0648\u0631 \u0645\u062A\u062D\u0641\u064B\u0627 \u{1F3DB}\uFE0F \u0648\u062A\u062A\u0635\u0648\u0631 \u0645\u0639 \u0623\u0635\u062F\u0642\u0627\u0626\u0643 \u{1F4F8}. \u062B\u0645 \u062A\u062C\u0644\u0633\u0648\u0646 \u0645\u0639\u064B\u0627 \u0639\u0644\u0649 \u0627\u0644\u0639\u0634\u0627\u0621 \u{1F355} \u0648\u062A\u0636\u062D\u0643\u0648\u0646. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u0623\u0635\u062F\u0642\u0627\u0621 \u0627\u0644\u062C\u062F\u062F = \u0643\u0646\u0632!'" };
      HELP_DATA2["m\xFCndlich_exam34_q1"] = { text: "Alter \u2192 Zuhause \u2192 Seniorenresidenz \u2192 Vorteile \u2192 Nachteile", meaning: "\u0627\u0644\u0633\u0643\u0646 \u0641\u064A \u0627\u0644\u0634\u064A\u062E\u0648\u062E\u0629: \u0627\u0644\u0628\u064A\u062A \u0623\u0645 \u062F\u0627\u0631 \u0627\u0644\u0645\u0633\u0646\u064A\u0646\u060C \u0644\u0643\u0644\u4F18\u70B9 \u0648\u0639\u064A\u0648\u0628", keywords: ["Zuhause", "Seniorenresidenz", "Einsamkeit"], simplified: "\u0627\u0644\u062E\u064A\u0627\u0631 \u0628\u064A\u0646 \u0627\u0644\u0628\u064A\u062A \u0648\u062F\u0627\u0631 \u0627\u0644\u0645\u0633\u0646\u064A\u0646 \u0644\u0647 \u0625\u064A\u062C\u0627\u0628\u064A\u0627\u062A \u0648\u0633\u0644\u0628\u064A\u0627\u062A\u060C \u064A\u0639\u062A\u0645\u062F \u0639\u0644\u0649 \u0627\u0644\u0634\u062E\u0635", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0634\u062E\u0635\u064B\u0627 \u0645\u0633\u0646\u064B\u0627 \u{1F474} \u064A\u0642\u0641 \u0628\u064A\u0646 \u0645\u0646\u0632\u0644\u0647 \u0627\u0644\u0642\u062F\u064A\u0645 \u{1F3E0} \u0648\u062F\u0627\u0631 \u0645\u0633\u0646\u064A\u0646 \u062D\u062F\u064A\u062B\u0629 \u{1F3E5}. \u0645\u0646\u0632\u0644\u0647 \u064A\u0644\u0645\u0639 \u0628\u0623\u0636\u0648\u0627\u0621 \u062F\u0627\u0641\u0626\u0629 \u{1F525} \u0648\u0627\u0644\u062F\u0627\u0631 \u062A\u0644\u0645\u0639 \u0628\u0623\u0636\u0648\u0627\u0621 \u0628\u0627\u0631\u062F\u0629 \u2744\uFE0F. \u064A\u062E\u062A\u0627\u0631 \u0643\u0644\u0627\u0647\u0645\u0627 \u0648\u064A\u0645\u0634\u064A \u0641\u064A \u0627\u0644\u0648\u0633\u0637 \u0648\u064A\u0628\u062A\u0633\u0645. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u062E\u064A\u0627\u0631 \u0644\u0643!'" };
      HELP_DATA2["m\xFCndlich_exam34_q2"] = { text: "Wohnform abh\xE4ngig \u2192 Sicherheit \u2192 Kontakte \u2192 Selbstst\xE4ndigkeit", meaning: "\u0623\u0641\u0636\u0644 \u0634\u0643\u0644 \u0633\u0643\u0646 \u064A\u0639\u062A\u0645\u062F \u0639\u0644\u0649 \u0627\u062D\u062A\u064A\u0627\u062C\u0627\u062A \u0627\u0644\u0634\u062E\u0635: \u0627\u0644\u0623\u0645\u0627\u0646\u060C \u0627\u0644\u0639\u0644\u0627\u0642\u0627\u062A\u060C \u0627\u0644\u0627\u0633\u062A\u0642\u0644\u0627\u0644\u064A\u0629", keywords: ["abh\xE4ngig", "Kontakte", "Selbstst\xE4ndigkeit"], simplified: "\u0627\u062E\u062A\u0631 \u0627\u0644\u0633\u0643\u0646 \u0627\u0644\u0630\u064A \u064A\u0648\u0641\u0631 \u0644\u0643 \u0627\u0644\u0623\u0645\u0627\u0646 \u0648\u0627\u0644\u0639\u0644\u0627\u0642\u0627\u062A \u0627\u0644\u0627\u062C\u062A\u0645\u0627\u0639\u064A\u0629 \u0648\u0627\u0644\u0627\u0633\u062A\u0642\u0644\u0627\u0644\u064A\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0634\u062E\u0635\u064B\u0627 \u0645\u0633\u0646\u064B\u0627 \u064A\u062D\u0645\u0644 \u062B\u0644\u0627\u062B \u0645\u0641\u0627\u062A\u064A\u062D \u{1F511}\u{1F511}\u{1F511}: \u0645\u0641\u062A\u0627\u062D \u0623\u0645\u0627\u0646 \u{1F6E1}\uFE0F\u060C \u0645\u0641\u062A\u0627\u062D \u0639\u0644\u0627\u0642\u0627\u062A \u{1F91D}\u060C \u0648\u0645\u0641\u062A\u0627\u062D \u0627\u0633\u062A\u0642\u0644\u0627\u0644 \u{1F54A}\uFE0F. \u064A\u0641\u062A\u062D \u062B\u0644\u0627\u062B\u0629 \u0623\u0628\u0648\u0627\u0628 \u0648\u064A\u062F\u062E\u0644 \u0648\u064A\u062C\u0644\u0633 \u0645\u0631\u062A\u0627\u062D\u064B\u0627. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u0633\u0643\u0646 \u0627\u0644\u0645\u062B\u0627\u0644\u064A = \u062A\u0648\u0627\u0632\u0646!'" };
      HELP_DATA2["m\xFCndlich_exam34_q3"] = { text: "Gro\xDFmutter \u2192 allein \u2192 Seniorenwohnung \u2192 sicherer \u2192 Kontakte", meaning: "\u062A\u062C\u0631\u0628\u0629 \u0627\u0644\u062C\u062F\u0629: \u0643\u0627\u0646\u062A \u0648\u062D\u064A\u062F\u0629\u060C \u0627\u0646\u062A\u0642\u0644\u062A \u0644\u0634\u0642\u0629 \u0643\u0628\u0627\u0631 \u0627\u0644\u0633\u0646 \u0641\u0634\u0639\u0631\u062A \u0628\u0627\u0644\u0623\u0645\u0627\u0646 \u0648\u0627\u0644\u0639\u0644\u0627\u0642\u0627\u062A", keywords: ["allein", "Seniorenwohnung", "sicherer"], simplified: "\u062C\u062F\u062A\u064A \u0643\u0627\u0646\u062A \u0648\u062D\u064A\u062F\u0629\u060C \u0641\u0644\u0645\u0627 \u0627\u0646\u062A\u0642\u0644\u062A \u0644\u0634\u0642\u0629 \u0643\u0628\u0627\u0631 \u0627\u0644\u0633\u0646 \u0634\u0639\u0631\u062A \u0628\u0627\u0644\u0623\u0645\u0627\u0646 \u0648\u0627\u0644\u0631\u0641\u0642\u0629", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u062C\u062F\u0629 \u{1F475} \u062C\u0627\u0644\u0633\u0629 \u0648\u062D\u062F\u0647\u0627\u060C \u062D\u0648\u0644\u0647\u0627 \u0638\u0644\u0627\u0644 \u0633\u0648\u062F\u0627\u0621 \u{1F311}. \u0641\u062C\u0623\u0629\u060C \u062A\u0646\u062A\u0642\u0644 \u0625\u0644\u0649 \u0634\u0642\u0629 \u0628\u0647\u0627 \u0623\u0635\u062F\u0642\u0627\u0621 \u062C\u062F\u062F \u{1F46D} \u0648\u062A\u0638\u0647\u0631 \u0623\u0636\u0648\u0627\u0621 \u0645\u0644\u0648\u0646\u0629 \u{1F308} \u062D\u0648\u0644\u0647\u0627. \u062B\u0645 \u062A\u0628\u062A\u0633\u0645 \u0648\u062A\u0642\u0648\u0644: '\u0623\u062E\u064A\u0631\u064B\u0627 \u0648\u062C\u062F\u062A \u0639\u0627\u0626\u0644\u062A\u064A \u0627\u0644\u062B\u0627\u0646\u064A\u0629!'" };
      HELP_DATA2["m\xFCndlich_exam35_q1"] = { text: "Ganztagsschule \u2192 Sch\xFCler \u2192 Kosten \u2192 Chancengleichheit \u2192 Verantwortung", meaning: "\u0627\u0644\u0645\u062F\u0627\u0631\u0633 \u0627\u0644\u0646\u0647\u0627\u0631\u064A\u0629: \u062A\u0632\u0627\u064A\u062F \u0627\u0644\u0625\u0642\u0628\u0627\u0644 \u0644\u0623\u0633\u0628\u0627\u0628 \u0627\u0642\u062A\u0635\u0627\u062F\u064A\u0629 \u0648\u062A\u0643\u0627\u0641\u0624 \u0641\u0631\u0635 \u0648\u0645\u0633\u0624\u0648\u0644\u064A\u0629", keywords: ["Ganztagsschule", "Kosten", "Chancengleichheit"], simplified: "\u0627\u0644\u0645\u062F\u0627\u0631\u0633 \u0627\u0644\u0646\u0647\u0627\u0631\u064A\u0629 \u062A\u062D\u0642\u0642 \u062A\u0643\u0627\u0641\u0624 \u0627\u0644\u0641\u0631\u0635 \u0644\u0643\u0646\u0647\u0627 \u0645\u0643\u0644\u0641\u0629 \u0648\u062A\u062E\u062A\u0644\u0641 \u0642\u0648\u0627\u0639\u062F\u0647\u0627", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0645\u062F\u0631\u0633\u0629 \u{1F3EB} \u062A\u0641\u062A\u062D \u0630\u0631\u0627\u0639\u064A\u0647\u0627 \u{1FAC2} \u0644\u0627\u0633\u062A\u0642\u0628\u0627\u0644 \u0627\u0644\u0637\u0644\u0627\u0628. \u0641\u062C\u0623\u0629\u060C \u062A\u0638\u0647\u0631 \u0646\u0642\u0648\u062F \u{1F4B0} \u0641\u064A \u064A\u062F\u060C \u0648\u0643\u062A\u0627\u0628 \u{1F4D6} \u0641\u064A \u0627\u0644\u064A\u062F \u0627\u0644\u0623\u062E\u0631\u0649. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u062A\u0639\u0644\u064A\u0645 \u062C\u064A\u062F = \u0645\u0633\u062A\u0642\u0628\u0644 \u0645\u0634\u0631\u0642!'" };
      HELP_DATA2["m\xFCndlich_exam35_q2"] = { text: "Ganztagsschule praktisch \u2192 Eltern entscheiden", meaning: "\u0627\u0644\u0645\u062F\u0627\u0631\u0633 \u0627\u0644\u0646\u0647\u0627\u0631\u064A\u0629 \u0639\u0645\u0644\u064A\u0629 \u0644\u0644\u0639\u0627\u0626\u0644\u0627\u062A\u060C \u0644\u0643\u0646 \u0627\u0644\u0642\u0631\u0627\u0631 \u0644\u0644\u0622\u0628\u0627\u0621", keywords: ["praktisch", "Eltern", "entscheiden"], simplified: "\u0627\u0644\u0645\u062F\u0631\u0633\u0629 \u0627\u0644\u0646\u0647\u0627\u0631\u064A\u0629 \u0645\u0641\u064A\u062F\u0629 \u0644\u0643\u0646 \u0627\u0644\u0622\u0628\u0627\u0621 \u0647\u0645 \u0645\u0646 \u064A\u0642\u0631\u0631\u0648\u0646 \u0645\u0627 \u064A\u0646\u0627\u0633\u0628 \u0623\u0628\u0646\u0627\u0621\u0647\u0645", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0623\u0628\u064B\u0627 \u0648\u0623\u0645\u064B\u0627 \u{1F468}\u200D\u{1F469} \u062C\u0627\u0644\u0633\u064A\u0646 \u0645\u0639 \u0627\u0628\u0646\u0647\u0645\u0627 \u{1F9D1}\u060C \u0623\u0645\u0627\u0645\u0647\u0645 \u062B\u0644\u0627\u062B\u0629 \u062E\u064A\u0627\u0631\u0627\u062A \u{1F3B2}: \u0645\u062F\u0631\u0633\u0629 \u0639\u0627\u062F\u064A\u0629\u060C \u0645\u062F\u0631\u0633\u0629 \u0646\u0647\u0627\u0631\u064A\u0629\u060C \u062A\u0639\u0644\u064A\u0645 \u0645\u0646\u0632\u0644\u064A. \u064A\u062E\u062A\u0627\u0631\u0648\u0646 \u0645\u0639\u064B\u0627 \u0648\u064A\u0628\u062A\u0633\u0645\u0648\u0646. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u0623\u0633\u0631\u0629 \u062A\u062E\u062A\u0627\u0631 \u0627\u0644\u0623\u0641\u0636\u0644!'" };
      HELP_DATA2["m\xFCndlich_exam35_q3"] = { text: "Freund \u2192 besucht \u2192 zufrieden \u2192 sp\xE4ter Freizeit vermisst", meaning: "\u062A\u062C\u0631\u0628\u0629 \u0635\u062F\u064A\u0642 \u0645\u0639 \u0627\u0644\u0645\u062F\u0631\u0633\u0629 \u0627\u0644\u0646\u0647\u0627\u0631\u064A\u0629: \u0643\u0627\u0646 \u0631\u0627\u0636\u064A\u064B\u0627 \u062B\u0645 \u0627\u0634\u062A\u0627\u0642 \u0644\u0644\u062D\u0631\u064A\u0629", keywords: ["besucht", "zufrieden", "Freizeit vermisst"], simplified: "\u0635\u062F\u064A\u0642 \u0627\u0644\u062A\u062D\u0642 \u0628\u0645\u062F\u0631\u0633\u0629 \u0646\u0647\u0627\u0631\u064A\u0629\u060C \u0643\u0627\u0646 \u0633\u0639\u064A\u062F\u064B\u0627 \u0641\u064A \u0627\u0644\u0628\u062F\u0627\u064A\u0629 \u0644\u0643\u0646\u0647 \u0627\u0634\u062A\u0627\u0642 \u0644\u0623\u0648\u0642\u0627\u062A \u0641\u0631\u0627\u063A\u0647 \u0644\u0627\u062D\u0642\u064B\u0627", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0635\u062F\u064A\u0642\u0643 \u{1F9D1} \u064A\u062C\u0644\u0633 \u0641\u064A \u0645\u062F\u0631\u0633\u0629\u060C \u064A\u0628\u062F\u0648 \u0633\u0639\u064A\u062F\u064B\u0627 \u{1F60A}. \u062B\u0645 \u062A\u0645\u0631 \u0627\u0644\u0623\u064A\u0627\u0645 \u23F3 \u0648\u064A\u0628\u062F\u0623 \u0628\u0627\u0644\u0646\u0638\u0631 \u0625\u0644\u0649 \u0627\u0644\u0633\u0627\u0639\u0629 \u23F0 \u0648\u064A\u062A\u062B\u0627\u0621\u0628 \u{1F629}. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u062D\u0631\u064A\u0629 \u0643\u0646\u0632!'" };
