      HELP_DATA2["m\xFCndlich_exam36_q2"] = { text: "Gewaltspiele eingeschr\xE4nkt \u2192 Erziehung wichtiger", meaning: "\u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u0639\u0646\u0641 \u064A\u062C\u0628 \u062A\u0642\u064A\u064A\u062F\u0647\u0627\u060C \u0644\u0643\u0646 \u0627\u0644\u062A\u0631\u0628\u064A\u0629 \u0623\u0647\u0645", keywords: ["eingeschr\xE4nkt", "Erziehung", "wichtiger"], simplified: "\u062D\u062F \u0645\u0646 \u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u0639\u0646\u0641\u060C \u0644\u0643\u0646 \u0631\u0643\u0632 \u0639\u0644\u0649 \u062A\u0631\u0628\u064A\u0629 \u0623\u0628\u0646\u0627\u0626\u0643 \u0641\u0647\u064A \u0627\u0644\u0623\u0647\u0645", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0644\u0639\u0628\u0629 \u0639\u0646\u0641 \u0645\u0642\u064A\u062F\u0629 \u0628\u0627\u0644\u0633\u0644\u0627\u0633\u0644 \u26D3\uFE0F\u060C \u0628\u064A\u0646\u0645\u0627 \u0623\u0633\u0631\u0629 \u062A\u0632\u0631\u0639 \u0648\u0631\u062F\u0629 \u{1F331} \u0648\u062A\u0646\u0645\u0648 \u0644\u062A\u0635\u0628\u062D \u0634\u062C\u0631\u0629 \u0643\u0628\u064A\u0631\u0629 \u{1F333}. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u062A\u0631\u0628\u064A\u0629 = \u063A\u0631\u0633 \u0627\u0644\u0642\u064A\u0645!'" };
      HELP_DATA2["m\xFCndlich_exam36_q3"] = { text: "Freund \u2192 gespielt \u2192 aggressiv \u2192 Mutter sprach \u2192 ruhiger", meaning: "\u062A\u062C\u0631\u0628\u0629 \u0635\u062F\u064A\u0642: \u0644\u0639\u0628 \u0623\u0644\u0639\u0627\u0628 \u0639\u0646\u0641 \u0641\u0635\u0627\u0631 \u0639\u062F\u0648\u0627\u0646\u064A\u064B\u0627\u060C \u062A\u062D\u062F\u062B\u062A \u0645\u0639\u0647 \u0623\u0645\u0647 \u0641\u0647\u062F\u0623", keywords: ["gespielt", "aggressiv", "Mutter sprach"], simplified: "\u0635\u062F\u064A\u0642\u064A \u0635\u0627\u0631 \u0639\u062F\u0648\u0627\u0646\u064A\u064B\u0627 \u0645\u0646 \u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u0639\u0646\u0641\u060C \u0644\u0643\u0646 \u062D\u062F\u064A\u062B \u0623\u0645\u0647 \u0645\u0639\u0647 \u063A\u064A\u064E\u0651\u0631\u0647", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0635\u062F\u064A\u0642\u0643 \u{1F9D1} \u064A\u0644\u0639\u0628 \u0628\u0639\u0646\u0641 \u{1F3AE}\u060C \u0639\u0631\u0648\u0642\u0647 \u062A\u0646\u062A\u0641\u062E \u{1F624}. \u0641\u062C\u0623\u0629\u060C \u062A\u0638\u0647\u0631 \u0623\u0645\u0647 \u{1F469} \u0648\u062A\u062C\u0644\u0633 \u0628\u062C\u0627\u0646\u0628\u0647 \u0648\u062A\u062A\u062D\u062F\u062B \u0645\u0639\u0647 \u{1F5E3}\uFE0F. \u062B\u0645 \u064A\u0628\u062A\u0633\u0645 \u0648\u064A\u063A\u0644\u0642 \u0627\u0644\u0644\u0639\u0628\u0629. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0643\u0644\u0645\u0629 \u062D\u0627\u0646\u064A\u0629 \u062A\u063A\u064A\u0651\u0631!'" };
      HELP_DATA2["m\xFCndlich_exam37_q1"] = { text: "Internet \u2192 Alltag \u2192 Einkaufen \u2192 Reisen \u2192 schwieriger \u2192 analoge F\xE4higkeiten", meaning: "\u0627\u0644\u062D\u064A\u0627\u0629 \u0628\u062F\u0648\u0646 \u0625\u0646\u062A\u0631\u0646\u062A \u0635\u0639\u0628\u0629\u060C \u0644\u0643\u0646 \u0627\u0644\u0628\u0639\u0636 \u064A\u0633\u062A\u0639\u064A\u062F \u0645\u0647\u0627\u0631\u0627\u062A\u0647 \u0627\u0644\u062A\u0642\u0644\u064A\u062F\u064A\u0629", keywords: ["kein Internet", "analoge F\xE4higkeiten", "neue M\xF6glichkeiten"], simplified: "\u0628\u062F\u0648\u0646 \u0625\u0646\u062A\u0631\u0646\u062A \u062A\u0635\u0628\u062D \u0628\u0639\u0636 \u0627\u0644\u0623\u0645\u0648\u0631 \u0623\u0635\u0639\u0628\u060C \u0644\u0643\u0646\u0643 \u062A\u0643\u062A\u0634\u0641 \u0645\u0647\u0627\u0631\u0627\u062A \u062C\u062F\u064A\u062F\u0629 \u0628\u062F\u0627\u062E\u0644\u0643", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0634\u062E\u0635\u064B\u0627 \u0628\u0644\u0627 \u0647\u0627\u062A\u0641 \u{1F4F1}\u060C \u064A\u062D\u0627\u0648\u0644 \u0634\u0631\u0627\u0621 \u0637\u0639\u0627\u0645 \u{1F6D2} \u0644\u0643\u0646\u0647 \u0644\u0627 \u064A\u0633\u062A\u062E\u062F\u0645 \u062A\u0637\u0628\u064A\u0642\u064B\u0627\u060C \u0641\u064A\u0630\u0647\u0628 \u0644\u0644\u0633\u0648\u0642 \u0628\u0646\u0641\u0633\u0647 \u{1F6B6}. \u062B\u0645 \u064A\u0643\u062A\u0634\u0641 \u0623\u0646\u0647 \u064A\u0633\u062A\u0637\u064A\u0639 \u0627\u0644\u0637\u0628\u062E \u{1F373}. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0623\u0642\u0648\u0649 \u0645\u0645\u0627 \u064A\u0638\u0646!'" };
      HELP_DATA2["m\xFCndlich_exam37_q2"] = { text: "Leben ohne Internet \u2192 kaum vorstellbar \u2192 Pause hilft", meaning: "\u0627\u0644\u062D\u064A\u0627\u0629 \u0628\u062F\u0648\u0646 \u0625\u0646\u062A\u0631\u0646\u062A \u0635\u0639\u0628\u0629 \u0627\u0644\u062A\u0635\u0648\u0631\u060C \u0644\u0643\u0646 \u0641\u062A\u0631\u0629 \u0631\u0627\u062D\u0629 \u0642\u0635\u064A\u0631\u0629 \u0645\u0641\u064A\u062F\u0629", keywords: ["kaum vorstellbar", "Pause", "hilft"], simplified: "\u0642\u062F \u062A\u0628\u062F\u0648 \u0627\u0644\u062D\u064A\u0627\u0629 \u0628\u062F\u0648\u0646 \u0625\u0646\u062A\u0631\u0646\u062A \u0645\u0633\u062A\u062D\u064A\u0644\u0629\u060C \u0644\u0643\u0646 \u062C\u0631\u0628 \u0641\u062A\u0631\u0629 \u0631\u0627\u062D\u0629 \u0648\u0633\u062A\u0631\u0649 \u0627\u0644\u0641\u0631\u0642", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0634\u062E\u0635\u064B\u0627 \u0645\u0631\u062A\u0628\u0637\u064B\u0627 \u0628\u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A \u0643\u0627\u0644\u062D\u0628\u0644 \u{1F517}\u060C \u0641\u062C\u0623\u0629 \u064A\u0642\u0637\u0639 \u0627\u0644\u062D\u0628\u0644 \u2702\uFE0F \u0648\u064A\u062C\u0644\u0633 \u0641\u064A \u0627\u0644\u0637\u0628\u064A\u0639\u0629 \u{1F332}. \u062B\u0645 \u064A\u062A\u0646\u0641\u0633 \u0628\u0639\u0645\u0642 \u{1F9D8} \u0648\u064A\u0634\u0639\u0631 \u0628\u0627\u0644\u0631\u0627\u062D\u0629. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0646\u0642\u0637\u0639 \u0644\u062A\u062A\u0635\u0644 \u0628\u0646\u0641\u0633\u0643!'" };
      HELP_DATA2["m\xFCndlich_exam37_q3"] = { text: "Ich \u2192 Tag ohne Internet \u2192 schwierig \u2192 sp\xE4ter konzentriert", meaning: "\u062A\u062C\u0631\u0628\u0629 \u064A\u0648\u0645 \u0628\u062F\u0648\u0646 \u0625\u0646\u062A\u0631\u0646\u062A: \u0635\u0639\u0628 \u0641\u064A \u0627\u0644\u0628\u062F\u0627\u064A\u0629\u060C \u062B\u0645 \u062A\u062D\u0633\u0646 \u0627\u0644\u062A\u0631\u0643\u064A\u0632", keywords: ["Tag ohne Internet", "schwierig", "konzentriert"], simplified: "\u0642\u0636\u064A\u062A \u064A\u0648\u0645\u064B\u0627 \u062F\u0648\u0646 \u0625\u0646\u062A\u0631\u0646\u062A\u060C \u0643\u0627\u0646 \u0635\u0639\u0628\u064B\u0627 \u0623\u0648\u0644\u0627\u064B \u062B\u0645 \u062A\u062D\u0633\u0646 \u062A\u0631\u0643\u064A\u0632\u064A \u0628\u0634\u0643\u0644 \u0643\u0628\u064A\u0631", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0646\u0641\u0633\u0643 \u062A\u0628\u062D\u062B \u0639\u0646 \u0645\u0639\u0644\u0648\u0645\u0629 \u062F\u0648\u0646 \u0625\u0646\u062A\u0631\u0646\u062A \u{1F50D}\u060C \u0641\u062A\u0630\u0647\u0628 \u0644\u0644\u0645\u0643\u062A\u0628\u0629 \u{1F4DA} \u0648\u062A\u0642\u0631\u0623 \u0643\u062A\u0627\u0628\u064B\u0627. \u0641\u062C\u0623\u0629\u060C \u062A\u0634\u0639\u0631 \u0628\u062A\u0631\u0643\u064A\u0632 \u0639\u0627\u0644\u064D \u{1F3AF} \u0648\u062A\u0641\u0647\u0645 \u0643\u0644 \u0634\u064A\u0621. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u062F\u0645\u0627\u063A \u064A\u062D\u062A\u0627\u062C \u0644\u0644\u0631\u0627\u062D\u0629 \u0623\u062D\u064A\u0627\u0646\u064B\u0627!'" };
      HELP_DATA2["m\xFCndlich_exam38_q1"] = { text: "Tierversuche \u2192 Forschung \u2192 Medizin \u2192 Medikamente \u2192 Kritik \u2192 Tierleid \u2192 Ethik", meaning: "\u062A\u062C\u0627\u0631\u0628 \u0627\u0644\u062D\u064A\u0648\u0627\u0646\u0627\u062A \u0641\u064A \u0627\u0644\u0623\u0628\u062D\u0627\u062B: \u0645\u0624\u064A\u062F \u0644\u0644\u0637\u0628\u060C \u0645\u0639\u0627\u0631\u0636 \u0644\u0623\u062E\u0644\u0627\u0642\u064A\u0627\u062A \u0648\u0645\u0639\u0627\u0646\u0627\u0629 \u0627\u0644\u062D\u064A\u0648\u0627\u0646\u0627\u062A", keywords: ["Tierversuche", "Tierleid", "Ethik"], simplified: "\u062A\u062C\u0627\u0631\u0628 \u0627\u0644\u062D\u064A\u0648\u0627\u0646\u0627\u062A \u062A\u062D\u0642\u0642 \u062A\u0642\u062F\u0645\u064B\u0627 \u0637\u0628\u064A\u064B\u0627 \u0644\u0643\u0646\u0647\u0627 \u062A\u0633\u0628\u0628 \u0622\u0644\u0627\u0645\u064B\u0627 \u0644\u0644\u062D\u064A\u0648\u0627\u0646\u0627\u062A \u0648\u062A\u062B\u064A\u0631 \u062C\u062F\u0644\u0627\u064B \u0623\u062E\u0644\u0627\u0642\u064A\u064B\u0627", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0645\u0639\u0637\u0641 \u0623\u0628\u064A\u0636 \u{1F468}\u200D\u{1F52C} \u0648\u0623\u0631\u0646\u0628 \u{1F407} \u064A\u062C\u0631\u064A \u0641\u064A \u0639\u062C\u0644\u0629 \u{1F3A1}. \u0641\u062C\u0623\u0629\u060C \u062A\u0638\u0647\u0631 \u062F\u0645\u0648\u0639 \u{1F4A7} \u0645\u0646 \u0639\u064A\u0646\u064A \u0627\u0644\u0623\u0631\u0646\u0628\u060C \u0641\u062A\u062A\u0648\u0642\u0641 \u0627\u0644\u062A\u062C\u0631\u0628\u0629. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u062D\u064A\u0627\u0629 \u0644\u0627 \u062A\u064F\u062C\u0631\u064E\u0628!'" };
      HELP_DATA2["m\xFCndlich_exam38_q2"] = { text: "Tierversuche erlaubt \u2192 nur ohne Alternativen \u2192 Schutz wichtig", meaning: "\u062A\u062C\u0627\u0631\u0628 \u0627\u0644\u062D\u064A\u0648\u0627\u0646\u0627\u062A \u0645\u0633\u0645\u0648\u062D\u0629 \u0641\u0642\u0637 \u0639\u0646\u062F \u0639\u062F\u0645 \u0648\u062C\u0648\u062F \u0628\u062F\u064A\u0644\u060C \u0648\u062D\u0645\u0627\u064A\u0629 \u0627\u0644\u062D\u064A\u0648\u0627\u0646 \u0645\u0647\u0645\u0629", keywords: ["Alternativen", "Schutz", "wichtig"], simplified: "\u0644\u0627 \u062A\u062C\u0631\u0650\u0628 \u0639\u0644\u0649 \u0627\u0644\u062D\u064A\u0648\u0627\u0646 \u0625\u0644\u0627 \u0639\u0646\u062F \u0627\u0644\u0636\u0631\u0648\u0631\u0629 \u0627\u0644\u0642\u0635\u0648\u0649\u060C \u0648\u0627\u062D\u0645\u0650\u0647 \u062F\u0627\u0626\u0645\u064B\u0627", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0641\u0623\u0631\u064B\u0627 \u{1F42D} \u064A\u0647\u0631\u0628 \u0645\u0646 \u0623\u0646\u0628\u0648\u0628 \u0627\u062E\u062A\u0628\u0627\u0631 \u{1F9EA}\u060C \u0648\u064A\u062E\u062A\u0628\u0626 \u062E\u0644\u0641 \u062F\u0631\u0639 \u{1F6E1}\uFE0F \u0645\u0643\u062A\u0648\u0628 \u0639\u0644\u064A\u0647 '\u062D\u0645\u0627\u064A\u0629'. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u0631\u0641\u0642 \u0628\u0627\u0644\u062D\u064A\u0648\u0627\u0646 \u0648\u0627\u062C\u0628!'" };
      HELP_DATA2["m\xFCndlich_exam38_q3"] = { text: "Biologieunterricht \u2192 Diskussion \u2192 Freund dagegen \u2192 andere daf\xFCr", meaning: "\u0646\u0642\u0627\u0634 \u0641\u064A \u062D\u0635\u0629 \u0627\u0644\u0623\u062D\u064A\u0627\u0621: \u0628\u0639\u0636 \u0627\u0644\u0632\u0645\u0644\u0627\u0621 \u0645\u0639 \u0627\u0644\u062A\u062C\u0627\u0631\u0628 \u0648\u0622\u062E\u0631\u0648\u0646 \u0636\u062F\u0647\u0627", keywords: ["Biologieunterricht", "Diskussion", "dagegen"], simplified: "\u062A\u0646\u0627\u0642\u0634\u0646\u0627 \u0641\u064A \u0627\u0644\u0645\u062F\u0631\u0633\u0629: \u0627\u0644\u0628\u0639\u0636 \u064A\u0631\u0649 \u062A\u062C\u0627\u0631\u0628 \u0627\u0644\u062D\u064A\u0648\u0627\u0646\u0627\u062A \u0636\u0631\u0648\u0631\u064A\u0629 \u0648\u0627\u0644\u0628\u0639\u0636 \u0627\u0644\u0622\u062E\u0631 \u064A\u0631\u0641\u0636\u0647\u0627", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0641\u0635\u0644\u064B\u0627 \u062F\u0631\u0627\u0633\u064A\u064B\u0627 \u{1F3EB}\u060C \u0623\u064A\u0627\u062F\u064D \u0645\u0631\u062A\u0641\u0639\u0629 \u{1F64B}\u{1F64B}\u200D\u2642\uFE0F\u060C \u0628\u0639\u0636\u0647\u0627 \u064A\u062D\u0645\u0644 \u0644\u0627\u0641\u062A\u0629 '\u0645\u0639' \u2705 \u0648\u0628\u0639\u0636\u0647\u0627 '\u0636\u062F' \u274C. \u0641\u062C\u0623\u0629\u060C \u064A\u0638\u0647\u0631 \u0627\u0644\u0623\u0633\u062A\u0627\u0630 \u0648\u064A\u0647\u062F\u0626 \u0627\u0644\u062C\u0645\u064A\u0639. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u0627\u062E\u062A\u0644\u0627\u0641 \u0641\u064A \u0627\u0644\u0631\u0623\u064A \u0644\u0627 \u064A\u0641\u0633\u062F \u0627\u0644\u0648\u062F!'" };
      HELP_DATA2["m\xFCndlich_exam39_q1"] = { text: "Englisch \u2192 internationale Firmen \u2192 Kommunikation \u2192 Missverst\xE4ndnisse \u2192 Akzent", meaning: "\u0627\u0644\u0625\u0646\u062C\u0644\u064A\u0632\u064A\u0629 \u0644\u063A\u0629 \u0627\u0644\u0634\u0631\u0643\u0627\u062A \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u0629: \u062A\u0633\u0647\u0644 \u0627\u0644\u062A\u0648\u0627\u0635\u0644 \u0644\u0643\u0646 \u0642\u062F \u062A\u0633\u0628\u0628 \u0633\u0648\u0621 \u0641\u0647\u0645 \u0628\u0633\u0628\u0628 \u0627\u0644\u0644\u0647\u062C\u0627\u062A", keywords: ["Englisch", "Kommunikation", "Missverst\xE4ndnisse"], simplified: "\u0627\u0644\u0625\u0646\u062C\u0644\u064A\u0632\u064A\u0629 \u0645\u0645\u062A\u0627\u0632\u0629 \u0644\u0644\u062A\u0648\u0627\u0635\u0644 \u0627\u0644\u0639\u0627\u0644\u0645\u064A\u060C \u0644\u0643\u0646 \u0627\u062D\u0630\u0631 \u0645\u0646 \u0633\u0648\u0621 \u0627\u0644\u0641\u0647\u0645 \u0628\u0633\u0628\u0628 \u0627\u0644\u0627\u062E\u062A\u0644\u0627\u0641\u0627\u062A \u0641\u064A \u0627\u0644\u0646\u0637\u0642", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0634\u062E\u0635\u064A\u0646 \u064A\u062A\u062D\u062F\u062B\u0627\u0646 \u0627\u0644\u0625\u0646\u062C\u0644\u064A\u0632\u064A\u0629 \u{1F5E3}\uFE0F\u060C \u0644\u0643\u0646 \u0643\u0644 \u0645\u0646\u0647\u0645\u0627 \u0628\u0644\u0647\u062C\u0629 \u0645\u062E\u062A\u0644\u0641\u0629 \u{1F5FA}\uFE0F\u060C \u0641\u062A\u062E\u0631\u062C \u0623\u0633\u0626\u0644\u0629 \u2753 \u0628\u064A\u0646\u0647\u0645\u0627. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u062A\u0648\u0627\u0635\u0644 \u0628\u0648\u0636\u0648\u062D!'" };
      HELP_DATA2["m\xFCndlich_exam39_q2"] = { text: "Englisch praktisch \u2192 andere Sprachen respektieren", meaning: "\u0627\u0644\u0625\u0646\u062C\u0644\u064A\u0632\u064A\u0629 \u0639\u0645\u0644\u064A\u0629\u060C \u0644\u0643\u0646 \u0627\u062D\u062A\u0631\u0645 \u0627\u0644\u0644\u063A\u0627\u062A \u0627\u0644\u0623\u062E\u0631\u0649 \u0623\u064A\u0636\u064B\u0627", keywords: ["praktisch", "respektieren", "andere Sprachen"], simplified: "\u0627\u0633\u062A\u062E\u062F\u0645 \u0627\u0644\u0625\u0646\u062C\u0644\u064A\u0632\u064A\u0629 \u062D\u064A\u062B \u062A\u0643\u0648\u0646 \u0645\u0641\u064A\u062F\u0629\u060C \u0644\u0643\u0646 \u0644\u0627 \u062A\u0647\u0645\u0634 \u0627\u0644\u0644\u063A\u0627\u062A \u0627\u0644\u0623\u062E\u0631\u0649", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0639\u0644\u0645 \u0628\u0631\u064A\u0637\u0627\u0646\u064A\u0627 \u{1F1EC}\u{1F1E7} \u0648\u0639\u0644\u0645 \u0641\u0631\u0646\u0633\u0627 \u{1F1EB}\u{1F1F7} \u0648\u0639\u0644\u0645 \u0623\u0644\u0645\u0627\u0646\u064A\u0627 \u{1F1E9}\u{1F1EA} \u064A\u0631\u0642\u0635\u0648\u0646 \u0645\u0639\u064B\u0627 \u{1F483}. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u062A\u0646\u0648\u0639 \u0627\u0644\u0644\u063A\u0648\u064A \u062B\u0631\u0627\u0621!'" };
      HELP_DATA2["m\xFCndlich_exam39_q3"] = { text: "Freund \u2192 Laden \u2192 Englisch \u2192 Missverst\xE4ndnisse \u2192 funktioniert", meaning: "\u062A\u062C\u0631\u0628\u0629 \u0635\u062F\u064A\u0642: \u0627\u0633\u062A\u062E\u062F\u0645 \u0627\u0644\u0625\u0646\u062C\u0644\u064A\u0632\u064A\u0629 \u0641\u064A \u0645\u062A\u062C\u0631\u0647\u060C \u062D\u062F\u062B\u062A \u0628\u0639\u0636 \u0633\u0648\u0621 \u0627\u0644\u0641\u0647\u0645 \u0644\u0643\u0646 \u0627\u0644\u0623\u0645\u0648\u0631 \u0633\u0627\u0631\u062A", keywords: ["Laden", "Englisch", "Missverst\xE4ndnisse"], simplified: "\u0635\u062F\u064A\u0642\u064A \u062A\u062D\u062F\u062B \u0627\u0644\u0625\u0646\u062C\u0644\u064A\u0632\u064A\u0629 \u0645\u0639 \u0632\u0628\u0627\u0626\u0646\u0647 \u0627\u0644\u0623\u062C\u0627\u0646\u0628\u060C \u062D\u062F\u062B\u062A \u0628\u0639\u0636 \u0627\u0644\u0623\u062E\u0637\u0627\u0621 \u0644\u0643\u0646 \u0627\u0644\u062A\u0648\u0627\u0635\u0644 \u0646\u062C\u062D", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0635\u062F\u064A\u0642\u0643 \u{1F9D1} \u0641\u064A \u0645\u062A\u062C\u0631\u0647 \u{1F3EA}\u060C \u064A\u062A\u062D\u062F\u062B \u0628\u0627\u0644\u0625\u0646\u062C\u0644\u064A\u0632\u064A\u0629 \u0645\u0639 \u0633\u0627\u0626\u062D \u{1F9F3}. \u0641\u062C\u0623\u0629\u060C \u064A\u062E\u0637\u0626 \u0641\u064A \u0627\u0644\u0643\u0644\u0645\u0629 \u0641\u064A\u0636\u062D\u0643\u0627\u0646 \u{1F602} \u062B\u0645 \u064A\u0641\u0647\u0645\u0627\u0646 \u0642\u0635\u062F\u0647. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u0646\u0648\u0627\u064A\u0627 \u0627\u0644\u062D\u0633\u0646\u0629 \u062A\u0635\u0644!'" };
      HELP_DATA2["m\xFCndlich_exam40_q1"] = { text: "Trinkgeld \u2192 Anerkennung \u2192 Service \u2192 Unterschiede L\xE4nder", meaning: "\u0627\u0644\u0628\u0642\u0634\u064A\u0634 \u062A\u0642\u062F\u064A\u0631 \u0644\u0644\u062E\u062F\u0645\u0629 \u0627\u0644\u062C\u064A\u062F\u0629\u060C \u0644\u0643\u0646 \u0627\u0644\u0639\u0627\u062F\u0627\u062A \u062A\u062E\u062A\u0644\u0641 \u0628\u064A\u0646 \u0627\u0644\u062F\u0648\u0644", keywords: ["Trinkgeld", "Anerkennung", "Unterschiede"], simplified: "\u0627\u0644\u0628\u0642\u0634\u064A\u0634 \u0644\u0641\u062A\u0629 \u062A\u0642\u062F\u064A\u0631\u060C \u0644\u0643\u0646 \u062A\u062E\u062A\u0644\u0641 \u0642\u0648\u0627\u0639\u062F\u0647 \u0645\u0646 \u0628\u0644\u062F \u0644\u0622\u062E\u0631", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u0637\u0628\u0642 \u0637\u0639\u0627\u0645 \u{1F37D}\uFE0F\u060C \u0628\u062C\u0627\u0646\u0628\u0647 \u0639\u0645\u0644\u0627\u062A \u0645\u0639\u062F\u0646\u064A\u0629 \u{1FA99}. \u0641\u062C\u0623\u0629\u060C \u062A\u062E\u0631\u062C \u064A\u062F \u{1F932} \u0648\u062A\u0639\u0637\u064A\u0647\u0627 \u0644\u0644\u0646\u0627\u062F\u0644 \u{1F468}\u200D\u{1F373} \u0641\u064A\u0628\u062A\u0633\u0645. \u062B\u0645 \u062A\u0638\u0647\u0631 \u062E\u0631\u064A\u0637\u0629 \u0627\u0644\u0639\u0627\u0644\u0645 \u{1F5FA}\uFE0F \u0648\u062A\u062A\u063A\u064A\u0631 \u0642\u0648\u0627\u0639\u062F \u0627\u0644\u0628\u0642\u0634\u064A\u0634 \u062D\u0633\u0628 \u0643\u0644 \u062F\u0648\u0644\u0629. \u062B\u0645 \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u062D\u062A\u0631\u0645 \u0639\u0627\u062F\u0627\u062A \u0627\u0644\u0645\u0643\u0627\u0646!'" };
      HELP_DATA2["m\xFCndlich_exam40_q2"] = { text: "Trinkgeld zeigt Wertsch\xE4tzung \u2192 nicht Pflicht", meaning: "\u0627\u0644\u0628\u0642\u0634\u064A\u0634 \u064A\u0638\u0647\u0631 \u0627\u0644\u062A\u0642\u062F\u064A\u0631 \u0644\u0643\u0646\u0647 \u0644\u064A\u0633 \u0625\u0644\u0632\u0627\u0645\u064A\u064B\u0627", keywords: ["Wertsch\xE4tzung", "nicht Pflicht", "Service"], simplified: "\u0627\u0644\u0628\u0642\u0634\u064A\u0634 \u0644\u0641\u062A\u0629 \u0637\u064A\u0628\u0629 \u0648\u0644\u064A\u0633 \u0625\u062C\u0628\u0627\u0631\u064B\u0627", imagine: "\u{1F9E0} \u062A\u062E\u064A\u0644 \u064A\u062F\u064B\u0627 \u062A\u0636\u0639 \u0646\u0642\u0648\u062F\u064B\u0627 \u{1F4B0} \u0628\u062C\u0627\u0646\u0628 \u0637\u0628\u0642\u060C \u0648\u064A\u062F\u064B\u0627 \u0623\u062E\u0631\u0649 \u062A\u0634\u064A\u0631 '\u0644\u064A\u0633 \u0625\u062C\u0628\u0627\u0631\u064A\u064B\u0627' \u{1F6AB}. \u062B\u0645 \u064A\u0628\u062A\u0633\u0645 \u0627\u0644\u0646\u0627\u062F\u0644 \u{1F60A} \u0648\u064A\u0642\u0648\u0644: '\u0634\u0643\u0631\u064B\u0627 \u0644\u0643 \u0639\u0644\u0649 \u0644\u0637\u0641\u0643!' \u062A\u0638\u0647\u0631 \u0644\u0627\u0641\u062A\u0629: '\u0627\u0644\u0639\u0637\u0627\u0621 \u0645\u0646 \u0627\u0644\u0642\u0644\u0628 \u064A\u0641\u0631\u062D!'" };
